-- Revision19 helpers. No changes to previously released migrations/components.
create or replace function ml_private.playtest_role_choice(s jsonb,kind text) returns boolean language sql immutable as $$
 select s->>'version'='web-v0.1.8' and kind in ('draw-start','draw-end','lemon-reward','lemon-support','runner-roll','runner-pay','teleport','easy','qb-pursuit','east-start','xiao-overflow','xie-ledger','elbow-push','west-carry') $$;
create or replace function ml_private.playtest_north_targets(s jsonb,targets jsonb,branch text default null,automatic boolean default false) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$
declare north integer;result jsonb;begin
 if s->>'version'<>'web-v0.1.8' then return targets;end if;
 select (v#>>'{}')::int into north from ml_private.arr(targets) v where s#>>array['players',v#>>'{}','character']='character-006';
 if north is null or not exists(select 1 from ml_private.arr(targets) v where (v#>>'{}')::int<>north and s#>>array['players',v#>>'{}','faction']<>'机械猴子') then return targets;end if;
 perform ml_private.need(automatic and branch in ('north','others'),'北帝汶与其他非机械猴子不能同时指定；请选择目标分支');
 select coalesce(jsonb_agg(v order by ord),'[]') into result from jsonb_array_elements(targets) with ordinality q(v,ord)
 where case when branch='north' then (v#>>'{}')::int=north or s#>>array['players',v#>>'{}','faction']='机械猴子' else (v#>>'{}')::int<>north end;
 return result;
end $$;
create or replace function ml_private.playtest_relocation_cell(s jsonb,a integer,origin text,destination text,ignored jsonb default '[]') returns text language plpgsql stable set search_path=pg_catalog,ml_private as $$
declare startcell jsonb:=ml_private.game_data(s,'map')->origin;cell jsonb:=ml_private.game_data(s,'map')->destination;dr integer;dc integer;begin
 if s->>'version'<>'web-v0.1.8' then return destination;end if;
 if startcell is null or cell is null then return null;end if;
 dr:=sign((cell->>'row')::int-(startcell->>'row')::int);dc:=sign((cell->>'col')::int-(startcell->>'col')::int);
 loop
  if not ml_private.stage4_board_entry(s,a,cell->>'id') or exists(select 1 from ml_private.arr(s->'players') p where (p->>'seat')::int<>a and not ignored @> jsonb_build_array(p->'seat') and ml_private.stage4_on_board(s,(p->>'seat')::int) and p->'cell'=cell->'id') then return null;end if;
  if not ml_private.classic_native(s,a) or not ml_private.stage4_board_water(s,cell->>'id',a) then return cell->>'id';end if;
  if dr=0 and dc=0 then return null;end if;
  cell:=ml_private.game_data(s,'map')->('r'||((cell->>'row')::int+dr)||'c'||((cell->>'col')::int+dc));if cell is null then return null;end if;
 end loop;
end $$;
create or replace function ml_private.playtest_nearest_shore(s jsonb,a integer,reserved jsonb default '[]') returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$
 with candidates as (select c->>'id' id,ml_private.distance_for_version(s->>'version',s#>>array['players',a::text,'cell'],c->>'id') dist from ml_private.arr(ml_private.game_data(s,'cells')) c
 where not ml_private.stage4_board_water(s,c->>'id',a) and ml_private.stage4_board_empty(s,a,c->>'id',jsonb_build_array(a)) and not reserved ? (c->>'id'))
 select coalesce(jsonb_agg(id order by id),'[]') from candidates where dist=(select min(dist) from candidates) $$;
create or replace function ml_private.playtest_flood(s jsonb,region text,owner integer,effect jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$
declare prior jsonb:=s#>array['stage4','water',region];reserved jsonb:='[]';plans jsonb:='[]';tasks jsonb:='[]';a integer;cells jsonb;plan jsonb;begin
 s:=jsonb_set(s,array['stage4','water',region],jsonb_build_object('owner',owner,'effect',effect));
 for a in select (v#>>'{}')::int from ml_private.arr(s->'order') v loop
  if ml_private.stage4_on_board(s,a) and ml_private.classic_native(s,a) and ml_private.stage4_board_water(s,s#>>array['players',a::text,'cell'],a) then
   cells:=ml_private.playtest_nearest_shore(s,a,reserved);
   if jsonb_array_length(cells)=0 then
    if prior is null then s:=s#-array['stage4','water',region];else s:=jsonb_set(s,array['stage4','water',region],prior);end if;
    return ml_private.emit(s,'effect','汶泽无合法岸边，地形变化未生效')||jsonb_build_object('_floodFailed',true);
   end if;
   plans:=plans||jsonb_build_array(jsonb_build_object('actor',a,'cells',cells));reserved:=reserved||jsonb_build_array(cells->0);
  end if;
 end loop;
 for plan in select * from ml_private.arr(plans) loop
  select coalesce(jsonb_agg(v order by v),'[]') into cells from ml_private.arr(plan->'cells') v where not exists(select 1 from jsonb_array_elements(reserved) with ordinality r(x,ord) where x=v and plans->(ord::int-1)->'actor'<>plan->'actor');
  tasks:=tasks||jsonb_build_array(ml_private.stage3_task('board-shore',jsonb_build_object('actor',plan->'actor','data',jsonb_build_object('cells',cells))));
 end loop;
 return s||jsonb_build_object('_shoreTasks',tasks);
end $$;
create or replace function ml_private.finish(s jsonb,forced boolean,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare combos jsonb;result_state jsonb;rows jsonb;winners jsonb;last_idx text;result jsonb;tied boolean;begin
 result_state:=ml_private.finish_before_stage3(s,forced,at);if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') or result_state->>'phase'='over' then return result_state;end if;
 combos:=ml_private.stage3_combo_teams(s);if jsonb_array_length(combos)=0 then return s;end if;
 result_state:=ml_private.finish_before_stage3(s,true,at);rows:=result_state#>'{result,ranking}';tied:=jsonb_array_length(combos)>1;
 if not tied then
 select jsonb_agg(r order by winning desc,ord) into rows from (select r,ord,combos ? (s#>>array['players',r#>>'{players,0}','team']) winning from jsonb_array_elements(rows) with ordinality t(r,ord)) q;
 select jsonb_agg(r||jsonb_build_object('rank',ord) order by ord) into rows from jsonb_array_elements(rows) with ordinality t(r,ord);
 select jsonb_agg(p->'seat' order by ord) into winners from jsonb_array_elements(s->'players') with ordinality t(p,ord) where combos ? (p->>'team');else winners:='[]';end if;
 result:=jsonb_build_object('reason',case when tied then 'draw' else 'combo' end,'winners',winners,'ranking',rows);last_idx:=(jsonb_array_length(result_state->'events')-1)::text;
 result_state:=jsonb_set(result_state,'{result}',result);result_state:=jsonb_set(result_state,array['events',last_idx,'data'],result);
 return jsonb_set(result_state,array['events',last_idx,'text'],to_jsonb(case when tied then '对局结束：平局' else '对局结束：'||(rows->0->>'label')||' 获胜' end));
end $$;
create or replace function ml_private.resolve_attack(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare attack jsonb:=s->'attack'; d jsonb:=ml_private.rule_card(s,attack->>'card'); hits jsonb:='[]'; targets jsonb; p jsonb; a integer:=(attack->>'actor')::int; t integer; actor integer; roll integer:=0; paid integer; amount integer; before_hp jsonb; triggers jsonb; healing integer:=0; begin
 select coalesce(jsonb_agg(x),'[]') into targets from ml_private.arr(attack->'targets') x where not (attack->'cancelled' @> jsonb_build_array(x));
 if jsonb_array_length(targets)>0 and d->>'id' in ('basic-006','basic-009') then s:=ml_private.die(s,d->>'name'); roll:=(s->>'_roll')::int; s:=s-'_roll'; end if;
 for t in select ml_private.n(x)::int from ml_private.arr(targets) x loop p:=s->'players'->t;
  if d ? 'power' then amount:=greatest(0,(d->>'power')::int-(p->>'ap')::int); paid:=least((d->>'power')::int,(p->>'ap')::int); p:=p||jsonb_build_object('ap',(p->>'ap')::int-paid); s:=ml_private.put_player(s,t,p); s:=ml_private.emit(s,'ap',ml_private.name(s,t)||' 被扣'||paid||'AP → '||(p->>'ap')); if amount>0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',t,'amount',amount,'source',a,'category','attack')); end if;
  elsif d->>'id'='basic-008' then
   if (p->>'ap')::int=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',t,'amount',1,'source',a,'category','attack'));
   else paid:=case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then (p->>'ap')::int else least(2,(p->>'ap')::int) end; s:=ml_private.put_player(s,t,p||jsonb_build_object('ap',(p->>'ap')::int-paid)); s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('ap',(s->'players'->a->>'ap')::int+paid)); s:=ml_private.emit(s,'ap',case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then ml_private.name(s,a)||' 头锤：从'||ml_private.name(s,t)||'吸收全部'||paid||'AP（目标AP '||paid||'→0）' else ml_private.name(s,a)||' 从'||ml_private.name(s,t)||'吸收'||paid||'AP' end); end if;
  elsif roll>=4 then hits:=hits||jsonb_build_array(jsonb_build_object('target',t,'amount',1,'source',a,'category','attack')); end if;
 end loop;
 for actor in select ml_private.n(x)::int from ml_private.arr(attack->'elbows') x loop p:=s->'players'->a;
  if (p->>'ap')::int=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',actor,'category','response'));
  else paid:=least(2,(p->>'ap')::int); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-paid)); s:=ml_private.put_player(s,actor,(s->'players'->actor)||jsonb_build_object('ap',(s->'players'->actor->>'ap')::int+paid)); s:=ml_private.emit(s,'ap',ml_private.name(s,actor)||' 肘击反吸'||paid||'AP'); end if;
 end loop;
 before_hp:=s->'players'; s:=ml_private.damage(s,hits); triggers:=s->'_triggers'; s:=s-'_triggers';
 if d->>'id'='basic-006' and (s->'players'->a->>'hp')::int>0 then for t in select ml_private.n(x)::int from ml_private.arr(targets) x loop healing:=healing+(before_hp->t->>'hp')::int-(s->'players'->t->>'hp')::int; end loop; s:=ml_private.heal(s,a,healing); end if;
 if roll>0 and roll<4 then s:=ml_private.emit(s,'miss',(d->>'name')||' 未命中'); end if;
 return s||jsonb_build_object('queue',triggers||jsonb_build_array(jsonb_build_object('kind','cleanup'))||(s->'queue'));
end $$;
create or replace function ml_private.start_round(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare cursor integer; a integer; begin
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.start_round_legacy(s,at);end if;
 s:=ml_private.pause(s,at);s:=jsonb_set(s,'{phase}','"resolving"');
 s:=jsonb_set(s,'{queue}',(s->'queue')||(select jsonb_agg(jsonb_build_object('kind','water','actor',x)) from ml_private.arr(s->'order') x)||jsonb_build_array(jsonb_build_object('kind','classic-start')));return ml_private.pump(s,at);
end $$;
create or replace function ml_private.next_turn(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare cursor integer; a integer; begin
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then if coalesce(s#>>'{stage4,interruptSkipEnd}','false')<>'true' then s:=ml_private.stage3_turn_end(s,(s->>'active')::int);end if;if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=jsonb_set(s,'{stage4,interruptSkipEnd}','false');end if;end if;
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.next_turn_legacy(s,at);end if;
 s:=ml_private.pause(s,at);a:=(s->>'active')::int;s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('moved',false,'attacks',0));if s->>'version' in ('web-v0.1.7','web-v0.1.8') and s#>'{stage4,interruptTurn}'<>'null'::jsonb then a:=(s#>>'{stage4,interruptTurn}')::int;s:=jsonb_set(s,'{stage4,interruptTurn}','null');s:=s||jsonb_build_object('order',(select jsonb_agg((a+i)%4 order by i) from generate_series(0,3) i),'round',(s->>'round')::int+1,'cursor',0);return ml_private.start_round(s,at);end if;
 cursor:=(s->>'cursor')::int+1;
 while cursor<4 and (s->'players'->(s->'order'->>cursor)::int->>'hp')::int<=0 loop cursor:=cursor+1;end loop;s:=jsonb_set(s,'{cursor}',to_jsonb(cursor));
 if cursor<4 then return jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor))||(s->'queue'));end if;
 s:=jsonb_set(s,'{phase}','"resolving"');s:=ml_private.classic_environment(s);s:=ml_private.emit(s,'environment','第'||(s->>'round')||'轮末，轰炸：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,bombs}') x));s:=ml_private.damage(s,s->'_hits',true);s:=s-'_hits';
 s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','round-next')));return s-'_triggers';
end $$;
create or replace function ml_private.pump(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare t jsonb;a integer;p jsonb;due jsonb;guard integer:=0;allowed boolean;ap integer;countn integer;cells jsonb;cursor integer;kind text;begin
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.pump_before_stage3(s,at);end if;
 while s->'choice'='null'::jsonb and s->>'phase'<>'over' loop
 due:=ml_private.stage3_overflow(s,s->'order')->0;
 if due is not null then a:=(due->>'actor')::int;s:=ml_private.select_choice(s,'xiao-overflow',a,at,jsonb_build_object('source',due->'collector','count',due->'count','cards',s#>array['players',a::text,'hand']));exit;end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=ml_private.stage4_begin_interrupt(s,at);if s->>'_interruptBegan'='true' then s:=s-'_interruptBegan';continue;end if;s:=s-'_interruptBegan';end if;
 exit when jsonb_array_length(s->'queue')=0;guard:=guard+1;perform ml_private.need(guard<200,'内部流程未收敛');t:=s->'queue'->0;s:=jsonb_set(s,'{queue}',(s->'queue')-0);a:=coalesce((t->>'actor')::int,(s->>'active')::int);p:=s->'players'->a;
 case t->>'kind'
 when 'stage3' then s:=ml_private.stage3_handle_task(s,t,at);if s->>'phase'='action' and s->'choice'='null'::jsonb then s:=ml_private.resume(s,at);end if;
 when 'water' then if ml_private.classic_owes_water(s,a) or (t#>>'{data,entry}'='true' and (p->>'hp')::int>0 and jsonb_array_length(p->'hand')>0) then if s->>'version' in ('web-v0.1.7','web-v0.1.8') and ml_private.stage4_combat_gear(s,a,'basic-069') is not null and coalesce(t#>>'{data,noTang}','false')<>'true' then if ml_private.stage4_ignore_location(s,a) then null;else s:=ml_private.select_choice(s,'gear-terrain',a,at,jsonb_build_object('data',jsonb_build_object('task',t)));end if;else s:=ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;end if;
 when 'classic-start' then
 for a in 0..3 loop p:=s->'players'->a;if (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,a)) then p:=p||jsonb_build_object('skillUsed',false,'rewarded','[]'::jsonb);s:=ml_private.put_player(s,a,p);s:=ml_private.stage3_round_gain_allowed(s,a);allowed:=(s->>'_allowed')::boolean;s:=s-'_allowed';
 if allowed and (p->>'ap')::int<5 and p->>'character'<>'character-031' then s:=ml_private.stage3_gain_ap(s,a,3);s:=s-'_gain';s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 轮开始获得3AP → '||(s#>>array['players',a::text,'ap']));end if;end if;end loop;
 s:=ml_private.classic_refresh(s);s:=ml_private.emit(s,'round','第'||(s->>'round')||'轮开始，毒区：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,poison}') x)||case when s#>>'{classic,farmClosed}'='true' then '；高唐农场已封闭' else '' end);s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','after-env')));
 when 'round-next' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=s||jsonb_build_object('round',(s->>'round')::int+1,'cursor',0);s:=ml_private.start_round(s,at);end if;
 when 'walk' then if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=ml_private.stage4_resume_walk(s,coalesce(t->'path','[]'),at);else s:=ml_private.classic_walk(s,coalesce(t->'path','[]'),at);end if;
 when 'after-env' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then cursor:=0;while not ml_private.stage3_alive(s,(s->'order'->>cursor)::int) loop cursor:=cursor+1;end loop;s:=s||jsonb_build_object('cursor',cursor);s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor)));end if;
 when 'turn-start' then
 if t#>>'{data,resuming}' is distinct from 'true' then
 s:=jsonb_set(s,'{classic,shipUsed}',(select coalesce(jsonb_agg(x),'[]') from ml_private.arr(s#>'{classic,shipUsed}') x where x<>to_jsonb(a)));
 s:=s||jsonb_build_object('active',a,'phase','resolving','clock',jsonb_build_object('remaining',60000,'since',at));s:=ml_private.put_player(s,a,p||jsonb_build_object('moved',false,'attacks',0));s:=ml_private.stage3_turn_start(s,a);if s->>'version' in ('web-v0.1.7','web-v0.1.8') and s#>>array['stage4','offMap',a::text]='true' then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','turn-start','actor',a,'data',jsonb_build_object('resuming',true))));s:=ml_private.stage4_return(s,a,at);continue;end if;end if;
 s:=ml_private.stage3_start_gain_allowed(s,a);allowed:=(s->>'_allowed')::boolean;s:=s-'_allowed';p:=s->'players'->a;
 if allowed and p->>'character'='character-031' and (p->>'ap')::int<6 then p:=p||jsonb_build_object('ap',6);s:=ml_private.put_player(s,a,p);s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 行动开始补至6AP');end if;
 ap:=case when allowed then ml_private.stage4_location_ap(s,a) else (p->>'ap')::int end;
 if ap>(p->>'ap')::int then s:=ml_private.stage3_gain_ap(s,a,ap-(p->>'ap')::int);s:=s-'_gain';s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 尚德荟获得1AP → '||(s#>>array['players',a::text,'ap']));end if;
 s:=ml_private.emit(s,'turn',ml_private.name(s,a)||' 开始行动');if (s->>'round')::int>1 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or s#>>array['stage4','drawBlocked',a::text]<>'true') then s:=ml_private.draw(s,a,ml_private.stage4_location_draw(s,a));end if;
 s:=ml_private.stage3_prepend(s,case when p->>'character'='character-010' then jsonb_build_array(ml_private.stage3_task('east',jsonb_build_object('actor',a))) else '[]'::jsonb end||jsonb_build_array(jsonb_build_object('kind','action')));if p->>'character'='character-027' and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or s#>>array['stage4','drawBlocked',a::text]<>'true') then s:=ml_private.select_choice(s,'draw-start',a,at);end if;
 when 'action' then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);
 when 'end-draw' then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','cave-end')));if p->>'character'='character-027' and (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,a)) and ml_private.budget(s,at)>0 then s:=ml_private.select_choice(s,'draw-end',a,at);end if;
 when 'cave-end' then s:=ml_private.cave_ending(s,a);if jsonb_array_length(s->'_hits')>0 then s:=ml_private.damage(s,s->'_hits',true);s:=ml_private.stage3_prepend(s,(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a)));s:=s-'_triggers';else s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a)));end if;s:=s-'_hits';
 when 'cave-after' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','discard','actor',a)));end if;
 when 'discard' then countn:=jsonb_array_length(p->'hand')-(p->>'hp')::int;s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','next')));if (p->>'hp')::int>0 and countn>0 then s:=ml_private.select_choice(s,'discard',a,at,jsonb_build_object('count',countn,'cards',p->'hand'));end if;
 when 'next' then s:=ml_private.next_turn(s,at);
 when 'trigger' then
 if (p->>'hp')::int<=0 then continue;end if;kind:=t->>'trigger';
 if kind='lemon-reward' then if t ? 'source' and not (s#>array['players',t->>'source','rewarded'] @> jsonb_build_array(a)) then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('source',t->'source'));end if;
 elsif p->>'skillUsed'='false' then
 if (kind='lemon-support' and (p->>'ap')::int>=1) or (kind='runner-roll' and (p->>'ap')::int>=2) then s:=ml_private.select_choice(s,kind,a,at);end if;
 if kind='teleport' then cells:=ml_private.teleport_cells(s,a);if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('cells',cells));end if;end if;end if;
 else raise exception '未知内部任务';end case;end loop;return s;
end $$;
create or replace function ml_private.end_turn(s jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int; begin
 if s->'movement'<>'null'::jsonb then s:=ml_private.settle_movement(s);s:=ml_private.classic_relocated(s,a,s->'players'->a->>'cell',s#>>'{movement,lastEmpty}'); s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('cell',s#>'{movement,lastEmpty}')); s:=jsonb_set(s,'{movement}','null'); s:=ml_private.emit(s,'move','移动结束，落点'||(s->'players'->a->>'cell')||'，剩余额度作废'); end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(ml_private.stage3_task('gear-end',jsonb_build_object('actor',a))));end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') and ml_private.stage4_desert(s,a) is not null then s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(ml_private.stage3_task('board-desert',jsonb_build_object('actor',a))));end if;
 s:=s||jsonb_build_object('phase','resolving','queue',(s->'queue')||jsonb_build_array(jsonb_build_object('kind',case when timeout then case when s->>'version' in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then 'cave-end' else 'discard' end else 'end-draw' end))); return ml_private.pump(s,at);
end $$;
create or replace function ml_private.choose(s jsonb,cmd jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice';a integer:=(c->>'actor')::int;card text:=cmd->>'card';parent jsonb;d jsonb;q jsonb;quoted jsonb;fee jsonb;child jsonb;idx text;begin
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8') or c->>'kind' not in ('card-counter','forced-card','board-path','board-cell','board-guess','board-tax','board-return','native-shore','gear-loss','gear-cloak','gear-reflect','gear-chalk','gear-plant','gear-react','gear-push','gear-terrain') then return ml_private.choose_before_stage4(s,cmd,at,timeout);end if;
 perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期');perform ml_private.need((cmd->>'actor')::int=a,'请交给待选择的座位操作');
 if c->>'kind' in ('gear-react','gear-push','gear-terrain') then s:=ml_private.stage4_movement_choose(s,cmd,at,timeout);
 elsif c->>'kind' in ('gear-cloak','gear-reflect','gear-chalk','gear-plant') then s:=ml_private.stage4_combat_choose(s,cmd,at,timeout);
 elsif c->>'kind'='gear-loss' then s:=ml_private.stage4_gear_loss_choose(s,cmd,at,timeout);
 elsif c->>'kind' in ('board-path','board-cell','board-guess','board-tax','board-return','native-shore') then s:=ml_private.stage4_map_choose(s,cmd,at,timeout);
 elsif c->>'kind'='forced-card' then
  if card is not null and card<>'' then
   perform ml_private.need(c->'cards' ? card and s#>array['players',a::text,'hand'] ? card,'必须交出符合要求的手牌');s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])-card);s:=jsonb_set(s,'{discard}',(s->'discard')||jsonb_build_array(card));s:=ml_private.emit(s,'deliver','S'||(a+1)||' 交出1张牌（不发动牌效）');
  else s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',c->'source','category','attack','directHp',true)));s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';end if;
 elsif card is not null and card<>'' and not timeout then
  parent:=s#>'{cardStack,stack,-1}';perform ml_private.need(ml_private.stage4_counter_cards(s,a,parent) ? card,'此牌不能反制当前效果');d:=ml_private.stage4_content()#>array['cards',split_part(card,'#',1)];q:=s#>array['stage4','costs','locks',card];
  if d#>>'{cost,kind}' in ('die','tiers') then perform ml_private.need(q->'turn'=s#>'{stage3,turn}','请先锁定响应牌费用');end if;
  quoted:=ml_private.stage3_card_cost(s,a,card,(q->>'cost')::int);fee:=ml_private.stage4_fee_plan((s#>>array['players',a::text,'ap'])::int,(quoted->>'cost')::int);
  s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-(fee->>'spend')::int));if (fee->>'gain')::int>0 then s:=ml_private.stage3_gain_ap(s,a,(fee->>'gain')::int);s:=s-'_gain';end if;
  s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])-card);s:=jsonb_set(s,'{resolving}',(s->'resolving')||jsonb_build_array(card));
  s:=ml_private.stage3_begin_card(s,a,card,d->>'id',jsonb_build_array(parent->'actor'),quoted->'effect',at,(parent->>'serial')::int);idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;
  s:=jsonb_set(s,array['cardStack','stack',idx,'stage4'],jsonb_build_object('counter',case when d->>'id'='basic-027' then 'tactic' when d->>'id'='basic-028' then 'jianmin' else 'food' end));child:=s#>'{cardStack,stack,-1}';
  s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',child->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',child->'serial'))));
  s:=ml_private.emit(s,'response','S'||(a+1)||' 使用'||(d->>'name')||'，支付'||(fee->>'spend')||'AP'||case when (fee->>'gain')::int>0 then '，获得'||(fee->>'gain')||'AP' else '' end);
 end if;
 if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||(c->>'kind'));end if;
 s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);
 if s->'choice'='null'::jsonb and jsonb_array_length(s->'queue')=0 and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);end if;return s;
end $$;
create or replace function ml_private.validate(s jsonb) returns void language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare p jsonb; zones jsonb; a integer;b integer;begin
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then perform ml_private.validate_before_stage3(s);return;end if;
 perform ml_private.need(jsonb_array_length(s->'players')=4 and (s->>'round')::int>=1 and (select jsonb_agg(x order by x) from ml_private.arr(s->'order') x)='[0,1,2,3]'::jsonb,'状态版本/轮次/人数无效');
 perform ml_private.need((select count(distinct member->>'character') from ml_private.arr(s->'players') member)=4 and not exists(select 1 from ml_private.arr(s->'players') member where not (ml_private.game_data(s,'characterIds') ? (member->>'character'))),'角色/顺序无效');
 zones:=(s->'deck')||(s->'discard')||(s->'resolving');
 for a in 0..3 loop p:=s->'players'->a;zones:=zones||(p->'hand')||(s#>array['stage3','equipment',a::text]);
 perform ml_private.need((p->>'hp')::numeric=trunc((p->>'hp')::numeric) and (p->>'hp')::int between 0 and (p->>'maxHp')::int and p->'maxHp'=ml_private.game_data(s,'characters')->(p->>'character')->'hp','生命状态无效');
 perform ml_private.need((p->>'ap')::numeric=trunc((p->>'ap')::numeric) and (p->>'ap')::int>=0 and (p->>'shield')::int between 0 and 2,'AP/护盾无效');perform ml_private.need(ml_private.game_data(s,'map') ? (p->>'cell'),'位置无效');
 if (p->>'hp')::int=0 then perform ml_private.need((p->>'ap')::int=0 and (p->>'shield')::int=0 and p->'hand'='[]'::jsonb and p->'eliminated'<>'null'::jsonb and s#>array['stage3','equipment',a::text]='[]'::jsonb,'淘汰清理无效');end if;
 for b in 0..a-1 loop if ml_private.stage3_alive(s,a) and ml_private.stage3_alive(s,b) and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,a) and ml_private.stage4_on_board(s,b)) and p->'cell'=s->'players'->b->'cell' then perform ml_private.need(s->>'version'<>'web-v0.1.8' and (s->>'phase'='moving' or s#>>'{choice,kind}'='water-discard') and s->'movement'<>'null'::jsonb,'稳定落点不能重叠');end if;end loop;end loop;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(zones) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'实体不守恒或实体重复');
 perform ml_private.need(jsonb_array_length(s#>'{classic,caveEnds}')=4 and not exists(select 1 from ml_private.arr(s#>'{classic,caveEnds}') n where (n#>>'{}')::int not between 0 and 2),'山洞计数无效');
 perform ml_private.need((s#>>'{clock,remaining}')::double precision>=0,'计时预算无效');
end $$;
create or replace function ml_private.occupied(s jsonb,cell text,except_actor integer default -1) returns boolean language sql immutable
set search_path=pg_catalog,ml_private as $$ select exists(select 1 from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,(p->>'seat')::int)) and p->>'cell'=cell and (p->>'seat')::int<>except_actor) $$;
create or replace function ml_private.teleport_cells(s jsonb,a integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') and ml_private.stage3_mount_blocked(s,a) then return '[]';end if;return ml_private.teleport_cells_before_stage3(s,a);
end $$;
create or replace function ml_private.legal_steps(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare result jsonb:='[]';c jsonb;a integer:=(s->>'active')::int;p jsonb:=s->'players'->a;cost integer;target integer;valid boolean;begin
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.legal_steps_before_stage3(s);end if;
 if s->>'phase'<>'moving' or s->'movement'='null'::jsonb then return result;end if;
 for c in select * from ml_private.arr(ml_private.game_data(s,'cells')) loop cost:=ml_private.classic_step_cost(s,a,c->>'id');
 if not ml_private.stage3_can_enter(s,a,c->>'id') or (s#>>'{movement,direction}' is not null and not ml_private.stage3_west_step(p->>'cell',c->>'id',s#>>'{movement,direction}')) then continue;end if;
 select (q->>'seat')::int into target from ml_private.arr(s->'players') q where (q->>'hp')::int>0 and (q->>'seat')::int<>a and q->'cell'=c->'id' limit 1;
 if target is not null and (p->>'character'='character-040' or s->>'version'='web-v0.1.8' and p->>'character'<>'character-045') then continue;end if;
 if target is not null and p->>'character'='character-045' then valid:=cost is not null and cost<=(s#>>'{movement,remaining}')::int and not ml_private.stage4_location_stops(s,a,c->>'id') and jsonb_array_length(ml_private.stage3_collision_path(ml_private.stage3_board(s),a,target,ml_private.stage3_direction(s,p->>'cell',c->>'id')))>0;
 else valid:=cost is not null and cost<=(s#>>'{movement,remaining}')::int and ml_private.escape(s,a,c->>'id',(s#>>'{movement,remaining}')::int-cost);end if;
 if valid then result:=result||jsonb_build_array(c->'id');end if;end loop;return result;
end $$;
create or replace function ml_private.targets(s jsonb,a integer,card text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare d jsonb:=ml_private.rule_card(s,card);p jsonb:=s->'players'->a;result jsonb;lemon integer;lmm integer;begin
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.targets_before_stage3(s,a,card);end if;
 if d is null or d->>'type'<>'attack' then return '[]';end if;if d->>'id'='basic-010' then return ml_private.stage3_monkey_targets(s,a);end if;
 select coalesce(jsonb_agg(q->'seat' order by ord),'[]') into result from jsonb_array_elements(s->'players') with ordinality t(q,ord) where (q->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,(q->>'seat')::int) and (d->>'group'='true' or not ml_private.stage4_single_protected(s,a,(q->>'seat')::int))) and (q->>'seat')::int<>a and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or split_part(card,'#',1)<>'basic-006' or not ml_private.stage3_equipped(s,(q->>'seat')::int,'basic-057')) and (s->>'mode'='ffa' or q->'team'<>p->'team') and not (d->>'group'='true' and q->>'character'='character-027' and jsonb_array_length(q->'hand')=1) and ml_private.stage4_location_card(s,a,d->>'id') and (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage4_card_range(s,a,d,q->>'cell') else (d->>'range'='global' or ml_private.game_data(s,'map')#>>array[q->>'cell','region']=ml_private.game_data(s,'map')#>>array[p->>'cell','region'] or (d->>'range'='adjacent' and ml_private.stage3_same_near(p->>'cell',q->>'cell'))) end);
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') and coalesce(d->>'group','false')<>'true' then lmm:=ml_private.stage4_lmm_target(s,a,result);if lmm is not null then return jsonb_build_array(lmm);end if;end if;
 select (q->>'seat')::int into lemon from ml_private.arr(s->'players') q where q->>'character'='character-004' and result @> jsonb_build_array(q->'seat');if coalesce(d->>'group','false')<>'true' and lemon is not null then return jsonb_build_array(lemon);end if;return result;
end $$;
create or replace function ml_private.heal(s jsonb,a integer,amount integer,food boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; old integer:=(p->>'hp')::int; hp integer:=old; begin
 if hp>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,a)) then amount:=case when food then ml_private.stage4_location_food(s,a,amount) else least((p->>'maxHp')::int-hp,amount) end;hp:=hp+case when s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then ml_private.stage3_healing(s,a,amount,food) else amount end;end if;
 s:=ml_private.put_player(s,a,p||jsonb_build_object('hp',hp)); return ml_private.emit(s,'heal',ml_private.name(s,a)||' 回复'||(hp-old)||'生命');
end $$;
create or replace function ml_private.select_choice(s jsonb,kind text,a integer,at double precision,extra jsonb default '{}') returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare paused boolean:=ml_private.playtest_role_choice(s,kind) or kind not in ('draw-start','draw-end'); serial integer:=(s->>'choiceSerial')::int+1; begin
 if paused then s:=ml_private.pause(s,at); else s:=ml_private.resume(s,at); end if;
 s:=s||jsonb_build_object('phase','choice','choiceSerial',serial,'choice',jsonb_build_object('id',serial,'kind',kind,'actor',a,'deadline',at+least(case when ml_private.playtest_role_choice(s,kind) then 30000 when kind='discard' and s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then 20000 else 10000 end,case when paused then (case when ml_private.playtest_role_choice(s,kind) then 30000 when kind='discard' and s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then 20000 else 10000 end) else ml_private.budget(s,at) end),'paused',paused)||extra);
 return ml_private.emit(s,'choice',ml_private.name(s,a)||' 等待选择：'||kind);
end $$;
create or replace function ml_private.damage(s jsonb,hits jsonb,environment boolean default false) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.stage3_damage(s,hits,environment,false);end if;return ml_private.damage_before_stage3(s,hits,environment);
end $$;
create or replace function ml_private.create_game(setup jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare rulev text:=coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end); s jsonb; chars jsonb; pair jsonb; teams jsonb; deck jsonb; firstn integer; a integer; c jsonb; id text; players jsonb:='[]'; randomj jsonb; begin
 perform ml_private.runtime_data(rulev,'characterIds');
 perform ml_private.need(jsonb_typeof(setup)='object' and setup->>'mode' in ('ffa','team') and at>=0,'开局输入无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(setup->'seats') x)='[0,1,2,3]'::jsonb,'必须有四个固定座位');
 perform ml_private.need(jsonb_typeof(setup->'seed')='number' and (setup->>'seed')::numeric=trunc((setup->>'seed')::numeric) and (setup->>'seed')::numeric between 0 and 4294967295,'种子必须为uint32');
 randomj:=jsonb_build_object('seed',setup->'seed','dice',coalesce(setup->'dice','[]'),'bombs',coalesce(setup->'bombs','[]'),'reshuffles',coalesce(setup->'reshuffles','[]'),'sortedReshuffles',coalesce(setup->'sortedReshuffles','false'));
 if coalesce((setup->>'secure')::boolean,false) then randomj:=randomj||jsonb_build_object('secure',true); end if;
 s:=jsonb_build_object('version',rulev,'random',randomj);
 if setup ? 'characters' then chars:=setup->'characters'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'characterIds')); chars:=case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1,s->'_shuffle'->2,s->'_shuffle'->3) else s->'_shuffle' end; s:=s-'_shuffle'; end if;
 perform ml_private.need(case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then jsonb_array_length(chars)=4 and (select count(distinct x) from ml_private.arr(chars) x)=4 and ml_private.game_data(s,'characterIds') @> chars else (select jsonb_agg(x order by x) from ml_private.arr(chars) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x) end,'四角色必须完整且唯一');
 s:=ml_private.shuffle(s,'[0,1,2,3]'); pair:=jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1); s:=s-'_shuffle';
 teams:=setup->'teams'; if teams is null then teams:='[]'; for a in 0..3 loop teams:=teams||to_jsonb(case when pair @> jsonb_build_array(a) then 'A' else 'B' end); end loop; end if;
 if setup->>'mode'='team' then perform ml_private.need(jsonb_array_length(teams)=4 and (select count(*) from ml_private.arr(teams) x where x='"A"')=2 and (select count(*) from ml_private.arr(teams) x where x='"B"')=2,'团战必须2对2'); end if;
 if setup ? 'first' then firstn:=(setup->>'first')::int; else s:=ml_private.int(s,4); firstn:=(s->>'_int')::int; s:=s-'_int'; end if; perform ml_private.need(firstn between 0 and 3,'首位无效');
 if setup ? 'deck' then deck:=setup->'deck'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'allCards')); deck:=s->'_shuffle'; s:=s-'_shuffle'; end if;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(deck) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'牌堆必须64实体完整排列');
 if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=ml_private.allocate_spawns(rulev,chars,s); end if;
 for a in 0..3 loop id:=chars->>a; c:=ml_private.game_data(s,'characters')->id;
  players:=players||jsonb_build_array(jsonb_build_object('seat',a,'character',id,'team',case when setup->>'mode'='team' then teams->>a else 'S'||(a+1) end,'faction',case when rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') and setup->>'mode'='team' then to_jsonb(case when teams->>a='A' then '机械猴子' else '帝汶家族' end) else c->'faction' end,'hp',c->'hp','maxHp',c->'hp','ap',5,'shield',0,'cell',case when rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s->'_spawns'->a else c->'spawn' end,'hand','[]'::jsonb,'moved',false,'attacks',0,'skillUsed',false,'rewarded','[]'::jsonb,'kills',0,'damage',0,'eliminated',null));
 end loop;
 s:=s||jsonb_build_object('version',coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end),'revision',0,'time',at,'mode',setup->'mode','players',players,'order',(select jsonb_agg((firstn+i)%4) from generate_series(0,3) i),'cursor',0,'active',firstn,'round',1,'phase','resolving','deck',deck,'discard','[]'::jsonb,'resolving','[]'::jsonb,'queue','[]'::jsonb,'choice',null,'choiceSerial',0,'attack',null,'movement',null,'safe',ml_private.safe_for_version(s->>'version',1),'bomb',null,'forecast',null,'clock',jsonb_build_object('remaining',60000,'since',null),'events','[]'::jsonb,'eventSerial',0,'batch',0,'reshuffleCount',0,'seen','[]'::jsonb,'result',null);
 s:=s-'_spawns'; if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=s||jsonb_build_object('classic',jsonb_build_object('poison','[]'::jsonb,'bombs','[]'::jsonb,'exposure',(select jsonb_agg(jsonb_build_object('region',null,'streak',0)) from generate_series(0,3)),'shipUsed','[]'::jsonb,'farmClosed',false)); end if;
 if rulev in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=jsonb_set(s,'{classic}',(s->'classic')||jsonb_build_object('bombRound',0,'caveEnds','[0,0,0,0]'::jsonb));end if;
 if rulev in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=s||jsonb_build_object('stage3',ml_private.stage3_initial(),'cardStack',jsonb_build_object('serial',0,'stack','[]'::jsonb));end if;
 if rulev in ('web-v0.1.7','web-v0.1.8') then s:=s||jsonb_build_object('stage4',ml_private.stage4_initial(s->'players'));end if;
 s:=ml_private.emit(s,'setup','四人'||case when setup->>'mode'='ffa' then '各自为战' else '2对2' end||' · '||(s->>'version')); for a in 0..3 loop s:=ml_private.draw(s,a,4); end loop;
 s:=ml_private.start_round(s,at); perform ml_private.validate(s); return s;
end $$;
create or replace function ml_private.dispatch(previous jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare s jsonb:=previous;a integer;typ text:=cmd->>'type';p jsonb;v jsonb;cell text;cost integer;roll integer;steps integer;direction text;deadline double precision;guard integer:=0;changed boolean:=false;begin
 if previous->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.dispatch_before_stage3(previous,cmd,at);end if;
 perform ml_private.need(jsonb_typeof(cmd)='object','命令必须为对象');perform ml_private.need(jsonb_typeof(cmd->'actor')='number' and (cmd->>'actor')::numeric=trunc((cmd->>'actor')::numeric) and (cmd->>'actor')::int between 0 and 3 and jsonb_typeof(cmd->'revision')='number' and (cmd->>'revision')::numeric=trunc((cmd->>'revision')::numeric) and (cmd->>'revision')::bigint>=0,'座位/命令版本必须为有效整数');a:=(cmd->>'actor')::int;
 perform ml_private.need(typ in ('play','move','step','stop','end','choose','tick','location','skill'),'未知命令');
 if typ='play' then perform ml_private.need(jsonb_typeof(cmd->'card')='string' and jsonb_typeof(cmd->'targets')='array' and not exists(select 1 from ml_private.arr(cmd->'targets') x where jsonb_typeof(x)<>'number' or (x#>>'{}')::numeric<>trunc((x#>>'{}')::numeric) or (x#>>'{}')::int not between 0 and 3),'出牌/目标输入无效');perform ml_private.need((not (cmd ? 'as') or cmd->>'as'='elbow') and (not (cmd ? 'replacement') or jsonb_typeof(cmd->'replacement')='string'),'转换或替换输入无效');end if;
 if typ in ('move','play') and cmd ? 'direction' then perform ml_private.need(cmd->>'direction' in ('up','right','down','left'),'方向输入无效');end if;
 if typ='skill' then perform ml_private.need((cmd->>'kind' in ('jj','bread','revival-quote') or previous->>'version' in ('web-v0.1.7','web-v0.1.8') and cmd->>'kind' in ('quote-cost','watch','flight','gift','terrain')) and (not (cmd ? 'target') or jsonb_typeof(cmd->'target')='number' and (cmd->>'target')::numeric=trunc((cmd->>'target')::numeric) and (cmd->>'target')::int between 0 and 3) and (not (cmd ? 'card') or jsonb_typeof(cmd->'card')='string'),'技能输入无效');end if;
 if typ='skill' and s->>'version' in ('web-v0.1.7','web-v0.1.8') then perform ml_private.need((not(cmd ? 'accept') or jsonb_typeof(cmd->'accept')='boolean') and (not(cmd ? 'cell') or jsonb_typeof(cmd->'cell')='string') and (not(cmd ? 'cards') or jsonb_typeof(cmd->'cards')='array' and not exists(select 1 from ml_private.arr(cmd->'cards') input_card where jsonb_typeof(input_card)<>'string')),'技能输入无效');end if;
 if typ='location' then perform ml_private.need(cmd->>'kind' in ('ship','commute') and jsonb_typeof(cmd->'cell')='string','地点动作输入无效');end if;
 if typ='step' then perform ml_private.need(jsonb_typeof(cmd->'path')='array' and not exists(select 1 from ml_private.arr(cmd->'path') x where jsonb_typeof(x)<>'string'),'路径必须为格子数组');end if;
 if typ='choose' then
 perform ml_private.need(jsonb_typeof(cmd->'choice')='number' and (cmd->>'choice')::numeric=trunc((cmd->>'choice')::numeric) and (cmd->>'choice')::bigint>0,'选择编号必须为正整数');
 perform ml_private.need(not (cmd ? 'accept') or jsonb_typeof(cmd->'accept')='boolean','发动选项必须为布尔值');perform ml_private.need(not (cmd ? 'card') or jsonb_typeof(cmd->'card') in ('string','null'),'响应牌输入无效');perform ml_private.need(not (cmd ? 'cell') or jsonb_typeof(cmd->'cell') in ('string','null'),'传送格输入无效');
 perform ml_private.need(not (cmd ? 'cards') or jsonb_typeof(cmd->'cards')='array' and not exists(select 1 from ml_private.arr(cmd->'cards') x where jsonb_typeof(x)<>'string'),'弃牌必须为实体牌数组');
 perform ml_private.need((not (cmd ? 'target') or jsonb_typeof(cmd->'target')='number' and (cmd->>'target')::numeric=trunc((cmd->>'target')::numeric) and (cmd->>'target')::int between 0 and 3) and (not (cmd ? 'action') or (cmd->>'action' in ('draw','steal') or previous->>'version' in ('web-v0.1.7','web-v0.1.8') and cmd->>'action'='ap')),'技能选择输入无效');end if;
 perform ml_private.need(at>=(s->>'time')::double precision and at<'Infinity'::double precision,'时钟必须单调');perform ml_private.need(cmd->'revision'=s->'revision','命令版本过期');perform ml_private.need(jsonb_typeof(cmd->'id')='string' and length(cmd->>'id')>0 and not (s->'seen' ? (cmd->>'id')),'重复命令');perform ml_private.need(s->>'phase'<>'over','对局已经结束');
 if typ='tick' then while s->>'phase'<>'over' loop deadline:=coalesce((s#>>'{choice,deadline}')::double precision,(s#>>'{clock,since}')::double precision+(s#>>'{clock,remaining}')::double precision);exit when deadline is null or deadline>at;exit when guard>=999;guard:=guard+1;s:=ml_private.expire(s,deadline);changed:=true;end loop;if not changed then return jsonb_build_object('state',previous,'ok',true);end if;
 else perform ml_private.need(not (case when s->'choice'<>'null'::jsonb then at>=(s#>>'{choice,deadline}')::double precision else s#>'{clock,since}'<>'null'::jsonb and ml_private.budget(s,at)=0 end),'命令已超时，请先处理时钟事件');
 if typ='choose' then perform ml_private.need(s->'choice'<>'null'::jsonb,'当前没有选择窗口');s:=ml_private.choose(s,cmd,at);
 elsif previous->>'version' in ('web-v0.1.7','web-v0.1.8') and typ='play' and split_part(cmd->>'card','#',1)='basic-017' then s:=ml_private.stage4_reserve_interrupt(s,cmd);
  elsif previous->>'version' in ('web-v0.1.7','web-v0.1.8') and typ='skill' and cmd->>'kind'='terrain' then s:=ml_private.stage3_skill(s,cmd,at);
  elsif previous->>'version' in ('web-v0.1.7','web-v0.1.8') and typ='skill' and cmd->>'kind'='quote-cost' and s#>>'{choice,kind}'='card-counter' and s#>'{choice,actor}'=cmd->'actor' then s:=ml_private.stage4_quote(s,a,cmd->>'card');
  else p:=s->'players'->a;perform ml_private.need(a=(s->>'active')::int and (p->>'hp')::int>0,'只有当前存活行动者可操作');perform ml_private.need(s->'choice'='null'::jsonb,'请先完成当前选择');perform ml_private.need(s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,a) or typ='end','离场期间只能结束行动');
 if typ='step' then perform ml_private.need(s->>'phase'='moving' and s->'movement'<>'null'::jsonb,'尚未开始移动');perform ml_private.need(jsonb_array_length(cmd->'path')>0,'移动路径不能为空');s:=ml_private.classic_walk(s,cmd->'path',at);
 elsif typ='stop' then perform ml_private.need(s->'movement'<>'null'::jsonb,'尚未开始移动');perform ml_private.need(not ml_private.occupied(s,p->>'cell',a),'不能停在占用格');s:=ml_private.settle_movement(s);s:=s||jsonb_build_object('movement',null,'phase','action');s:=ml_private.emit(s,'move','主动结束移动，未用额度作废');
 elsif typ='end' then perform ml_private.need(s->'movement'='null'::jsonb or not ml_private.occupied(s,p->>'cell',a),'不能在占用格结束行动，请先离开');s:=ml_private.end_turn(s,at);
 else perform ml_private.need(s->>'phase'='action','请先完成移动');
 if typ='location' then cell:=cmd->>'cell';perform ml_private.need(ml_private.stage3_locations(s,a,cmd->>'kind') ? cell,'地点传送当前不可用或落点不合法');if cmd->>'kind'='ship' then s:=jsonb_set(s,'{classic,shipUsed}',(s#>'{classic,shipUsed}')||jsonb_build_array(a));else s:=jsonb_set(s,array['players',a::text,'ap'],'0');end if;s:=ml_private.stage3_relocate(s,a,cell,true);s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_relocationTasks'));s:=s-'_relocationTasks';s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' '||case when cmd->>'kind'='ship' then '飞船' else '通校' end||'至'||cell);
 elsif typ='move' then
 perform ml_private.need(p->>'moved'='false','本个人回合已使用基础移动');perform ml_private.need(not ml_private.stage3_mount_blocked(s,a),'小白马：有坐骑者暂时不能主动位移');cost:=case when ml_private.stage3_equipped(s,a,'basic-071') then 0 else ml_private.stage3_fixed_cost(s,a,ml_private.stage4_location_move_cost(s,a)) end;perform ml_private.need((p->>'ap')::int>=cost,'移动需要1AP');
 if p->>'character'='character-040' then perform ml_private.need(cmd ? 'direction','请先声明移动方向');s:=ml_private.die(s,'西帝汶方向');direction:=ml_private.stage3_west_direction(cmd->>'direction',(s->>'_roll')::int);s:=s-'_roll';end if;
 s:=ml_private.die(s,'基础移动');roll:=(s->>'_roll')::int;s:=s-'_roll';steps:=case when s#>>array['stage3','doubleMove',a::text]='true' and ml_private.stage3_equipped(s,a,'basic-066') then roll else ceil(roll::numeric/2)::int end;s:=jsonb_set(s,array['stage3','basicUsed',a::text],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int+1));s:=jsonb_set(s,array['players',a::text,'moved'],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int>=case when s#>>array['stage3','doubleMove',a::text]='true' then 2 else 1 end));
 s:=s||jsonb_build_object('movement',jsonb_build_object('remaining',steps,'lastEmpty',p->'cell','origin',p->'cell','path',jsonb_build_array(p->'cell'),'costDue',cost>0,'carry',ml_private.stage3_carry_candidates(s,a,p->>'cell'))||case when direction is null then '{}'::jsonb else jsonb_build_object('direction',direction) end,'phase','moving');if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=jsonb_set(s,'{movement,gearRoot}',s->'revision');end if;s:=ml_private.emit(s,'cost',ml_private.name(s,a)||case when cost=0 then ' 免费移动' else ' 移动结束扣费' end||'，获得'||steps||'步');
 elsif typ='skill' then s:=ml_private.stage3_skill(s,cmd,at);
 elsif typ='play' then s:=ml_private.stage3_play(s,cmd,at);else raise exception '未知命令';end if;end if;end if;end if;
 s:=ml_private.pump(s,at);s:=s||jsonb_build_object('seen',(s->'seen')||jsonb_build_array(cmd->'id'),'revision',(s->>'revision')::int+1,'time',at);perform ml_private.validate(s);return jsonb_build_object('state',s,'ok',true);
 exception when others then return jsonb_build_object('state',previous,'ok',false,'error',sqlerrm);
end $$;
create or replace function ml_private.public_view(s jsonb,viewer integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare v jsonb:=ml_private.public_view_before_stage4(s,viewer);begin
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8') then return v;end if;
 v:=v||jsonb_build_object('stage4',ml_private.stage4_public_state(s));return jsonb_set(v,'{actions,stage4}',ml_private.stage4_actions(s,viewer));
end $$;
create or replace function ml_private.settle_movement(s jsonb) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare m jsonb:=s->'movement';begin
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') and jsonb_array_length(m->'path')>1 and jsonb_array_length(coalesce(m->'carry','[]'))>0 then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',s->'active','data',m->'carry'))));s:=jsonb_set(s,'{movement,carry}','[]');end if;if s->>'version' in ('web-v0.1.7','web-v0.1.8') and jsonb_array_length(m->'path')>1 and coalesce(m->>'gearQueued','false')<>'true' then s:=jsonb_set(s,'{movement,gearQueued}','true');s:=jsonb_set(s,'{queue}',(s->'queue')||ml_private.stage4_landing_tasks(s,(s->>'active')::int,ml_private.stage3_direction(s,m#>>'{path,-2}',m#>>'{path,-1}')));end if;return ml_private.settle_movement_before_stage3(s);
end $$;
create or replace function ml_private.room_v1(p_request jsonb) returns jsonb
language plpgsql security definer set search_path=pg_catalog,ml_private as $$
declare at bigint:=ml_private.now_ms(); op text:=p_request->>'op'; token text:=p_request->>'token'; hash text; req_id text:=p_request->>'requestId'; payload jsonb:=p_request-'token'-'epoch'; r ml_private.rooms; before_r ml_private.rooms; prior ml_private.intakes; receipt ml_private.receipts; a integer; m jsonb; mid uuid; pname text:=btrim(p_request->>'name'); keyname text; next_code text; attempt integer; found_room boolean:=false; outcome jsonb; reply jsonb; command jsonb; res jsonb; changed boolean:=false;
begin
 perform ml_private.need(jsonb_typeof(p_request)='object' and octet_length(p_request::text)<=16384,'请求格式无效或过大');
 perform ml_private.need(jsonb_typeof(p_request->'op')='string' and jsonb_typeof(p_request->'token')='string' and jsonb_typeof(p_request->'name')='string','身份字段必须为字符串');
 perform ml_private.need(op in ('create','join','resume','view','heartbeat','offline','ready','mode','start','leave','game','draft-pick'),'未知房间操作');
 perform ml_private.need(not exists(select 1 from jsonb_object_keys(p_request) k where k not in ('op','token','requestId','name','code','roomId','epoch','ready','mode','roomRevision','matchId','revision','intent','offer','character')),'请求含不允许的字段');
 perform ml_private.need(token ~ '^[a-f0-9]{64}$','恢复凭据无效'); hash:=ml_private.token_hash(token);
 perform ml_private.need(length(pname) between 1 and 24 and pname !~ '[[:cntrl:]]','玩家名须为1至24个可见字符'); keyname:=lower(pname);
 if op in ('create','join','ready','mode','start','leave','game','draft-pick') then perform ml_private.need(jsonb_typeof(p_request->'requestId')='string' and req_id ~ '^[A-Za-z0-9_-]{1,100}$','请求编号无效'); end if;
 if op in ('create','join') then
  -- Serializes identical uncertain intake retries before assigning any seat/code.
  perform pg_advisory_xact_lock(('x'||substr(hash,1,16))::bit(64)::bigint);
  select * into prior from ml_private.intakes i where i.token_hash=hash and i.request_id=req_id;
  if found then
   perform ml_private.need(prior.payload=payload,'同一请求编号不能更换内容');
   select * into r from ml_private.rooms where id=prior.room_id for update;
   perform ml_private.need(r.status<>'closed','原房间已关闭，凭据已失效');
   for a in 0..3 loop if r.members->a->>'id'=prior.member_id::text then
    r:=ml_private.refresh_room(r,at); perform ml_private.save_room(r);
    perform ml_private.need(r.status<>'closed' and r.members->a->>'id'=prior.member_id::text,'原座位已释放');
    return jsonb_build_object('ok',true,'duplicate',true,'snapshot',ml_private.room_view(r,a,at));
   end if; end loop; raise exception '原座位已释放';
  end if;
  perform ml_private.throttle('intake:'||hash,at,30);
  if op='create' then
   perform ml_private.throttle('create:global',at,120);
   for attempt in 1..200 loop
    next_code:=lpad(ml_private.entropy(10000)::text,4,'0');
    begin
     insert into ml_private.rooms(code,created_at,updated_at,members) values(next_code,at,at,'[null,null,null,null]') returning * into r; found_room:=true;
    exception when unique_violation then null; end;
    exit when found_room;
   end loop; perform ml_private.need(found_room,'可用房间码暂不足，请稍后重试'); a:=0;
  else
   perform ml_private.need(jsonb_typeof(p_request->'code')='string' and p_request->>'code' ~ '^[0-9]{4}$','房间码必须是4位数字');
   select * into r from ml_private.rooms where code=p_request->>'code' and status<>'closed' for update;
   perform ml_private.need(found,'房间不存在或已关闭'); r:=ml_private.refresh_room(r,at); perform ml_private.save_room(r);
   perform ml_private.need(r.status in ('lobby','finished'),'对局进行中，不能加入');
   perform ml_private.need(not exists(select 1 from ml_private.arr(r.members) x where x->>'key'=keyname),'该房间已有同名玩家，请使用原凭据恢复或换名');
   a:=null; for attempt in 0..3 loop if r.members->attempt='null'::jsonb then a:=attempt; exit; end if; end loop; perform ml_private.need(a is not null,'房间已满');
  end if;
  mid:=gen_random_uuid(); m:=jsonb_build_object('id',mid,'seat',a,'name',pname,'key',keyname,'tokenHash',hash,'ready',false,'lastSeen',at,'offlineSince',null,'joinedAt',at,'epoch',1);
  r.members:=jsonb_set(ml_private.clear_ready(r.members),array[a::text],m); r.host:=coalesce(r.host,mid); r.empty_since:=null; r.revision:=r.revision+1; r.updated_at:=at; perform ml_private.save_room(r);
  insert into ml_private.intakes values(hash,req_id,payload,r.id,mid,at);
  return jsonb_build_object('ok',true,'snapshot',ml_private.room_view(r,a,at));
 end if;
 perform ml_private.need(jsonb_typeof(p_request->'roomId')='string' and p_request->>'roomId' ~ '^[a-f0-9-]{36}$','房间身份无效');
 select * into r from ml_private.rooms where id=(p_request->>'roomId')::uuid for update;
 perform ml_private.need(found and r.status<>'closed','房间不存在或已关闭');
 r:=ml_private.refresh_room(r,at);
 a:=null; for attempt in 0..3 loop m:=r.members->attempt; if m->>'tokenHash'=hash and m->>'key'=keyname then a:=attempt; exit; end if; end loop;
 if a is null then
  perform ml_private.save_room(r);
  if op='leave' then
   select q.* into receipt from ml_private.receipts q join ml_private.intakes i on i.room_id=q.room_id and i.member_id=q.member_id where i.token_hash=hash and q.room_id=r.id and q.request_id=req_id limit 1;
   if found and receipt.payload=payload and receipt.outcome->>'left'='true' then return receipt.outcome||jsonb_build_object('duplicate',true); end if;
  end if;
  return jsonb_build_object('ok',false,'error','恢复凭据或玩家名不匹配，座位可能已释放');
 end if;
 m:=r.members->a; mid:=(m->>'id')::uuid;
 perform ml_private.throttle('member:'||mid,at,240);
 if op='resume' then m:=m||jsonb_build_object('epoch',(m->>'epoch')::bigint+1); else perform ml_private.need(jsonb_typeof(p_request->'epoch')='number' and p_request->'epoch'=m->'epoch','连接已被新页面接管，请停止重连'); end if;
 if op='offline' then m:=m||jsonb_build_object('offlineSince',at); if r.status in ('lobby','finished') then m:=m||jsonb_build_object('ready',false); r.revision:=r.revision+1; end if;
 else m:=m||jsonb_build_object('lastSeen',at,'offlineSince',null); end if;
 r.members:=jsonb_set(r.members,array[a::text],m);
 if op in ('resume','view','heartbeat','offline') then perform ml_private.save_room(r); return jsonb_build_object('ok',true,'snapshot',ml_private.room_view(r,a,at)); end if;
 select * into receipt from ml_private.receipts q where q.room_id=r.id and q.member_id=mid and q.request_id=req_id;
 if found then
  perform ml_private.save_room(r); if receipt.payload<>payload then return jsonb_build_object('ok',false,'error','同一请求编号不能更换内容','snapshot',ml_private.room_view(r,a,at)); end if;
  return receipt.outcome||jsonb_build_object('duplicate',true,'snapshot',ml_private.room_view(r,a,at));
 end if;
 -- Subtransaction catches rejected commands while preserving elapsed clock work.
 before_r:=r;
 begin
  if op in ('ready','mode','start','leave') then perform ml_private.need(jsonb_typeof(p_request->'roomRevision')='number' and p_request->'roomRevision'=to_jsonb(r.revision),'房间状态已更新，请查看后重试'); end if;
  if op='game' then
   perform ml_private.need(r.status='playing' and p_request->>'matchId'=r.match_id::text,'对局身份已过期');
   command:=p_request->'intent'; perform ml_private.need(jsonb_typeof(command)='object' and command->>'type' in ('play','move','step','stop','end','choose','location','skill'),'操作意图无效');
   perform ml_private.need(not exists(select 1 from jsonb_object_keys(command) k where k not in ('type','card','targets','path','choice','accept','cell','cards','kind','direction','as','replacement','target','action','x','region','take','item','copy','option','guess','northGroup')),'操作含不允许的字段');
   command:=command||jsonb_build_object('actor',a,'revision',p_request->'revision','id',r.match_id::text||':'||mid::text||':'||req_id);
   res:=ml_private.dispatch(r.game,command,at); perform ml_private.need((res->>'ok')::boolean,res->>'error'); r.game:=res->'state'; changed:=true;
   if r.game->>'phase'='over' then r.status:='finished'; r.members:=ml_private.clear_ready(r.members); insert into ml_private.archives values(r.match_id,r.id,r.game,at+86400000) on conflict do nothing; end if;
  elsif op='draft-pick' then
 perform ml_private.need(r.status='drafting' and p_request->>'matchId'=r.match_id::text,'选角对局身份已过期');
 command:=jsonb_build_object('type','pick','actor',a,'revision',p_request->'revision','offer',p_request->'offer','character',p_request->'character','id',ml_private.token_hash(r.match_id::text||':'||mid::text||':'||req_id));
 res:=ml_private.dispatch_draft(r.draft,command,at);perform ml_private.need(res->>'ok'='true',res->>'error');r.draft:=res->'state';r:=ml_private.stage3_complete_draft(r,at);changed:=true;
 elsif op='ready' then
   perform ml_private.need(r.status in ('lobby','finished'),'对局进行中不能修改准备'); perform ml_private.need(jsonb_typeof(p_request->'ready')='boolean','准备状态无效'); r.members:=jsonb_set(r.members,array[a::text,'ready'],p_request->'ready'); changed:=true;
  elsif op='mode' then
   perform ml_private.need(r.host=mid and r.status in ('lobby','finished'),'只有房主可在开局前选择模式'); perform ml_private.need(p_request->>'mode' in ('ffa','team'),'模式无效'); r.mode:=p_request->>'mode'; r.members:=ml_private.clear_ready(r.members); changed:=true;
  elsif op='start' then
   perform ml_private.need(r.host=mid and r.status in ('lobby','finished'),'只有房主可开始新局');
   perform ml_private.need((select count(*) from ml_private.arr(r.members) x where ml_private.online(x,at) and (x->>'ready')::boolean)=4,'需要四人在线且全部准备');
   r.match_id:=gen_random_uuid();r.game:=null;r.draft:=ml_private.stage4_create_draft(r.mode,jsonb_build_object('seed',0,'dice','[]'::jsonb,'bombs','[]'::jsonb,'reshuffles','[]'::jsonb,'sortedReshuffles',false,'secure',true),at);r.status:='drafting';r.members:=ml_private.clear_ready(r.members);changed:=true;
  elsif op='leave' then
   perform ml_private.need(r.status in ('lobby','finished'),'进行中不释放座位；关闭页面后仍按原时限推进'); r.members:=jsonb_set(ml_private.clear_ready(r.members),array[a::text],'null'); r.revision:=r.revision+1; r.updated_at:=at; r:=ml_private.refresh_room(r,at); perform ml_private.save_room(r); reply:=jsonb_build_object('ok',true,'left',true); insert into ml_private.receipts values(r.id,mid,req_id,payload,reply,at); return reply;
  end if;
  if changed then r.revision:=r.revision+1; r.updated_at:=at; end if;
  outcome:=jsonb_build_object('ok',true,'appliedRevision',case when r.status='drafting' then r.draft->'revision' else r.game->'revision' end,'matchId',r.match_id);
 exception when others then r:=before_r; outcome:=jsonb_build_object('ok',false,'error',case when sqlstate='P0001' then sqlerrm else '操作未提交，服务暂不可用' end);
 end;
 perform ml_private.save_room(r); insert into ml_private.receipts values(r.id,mid,req_id,payload,outcome,at);
 return outcome||jsonb_build_object('snapshot',ml_private.room_view(r,a,at));
exception when others then return jsonb_build_object('ok',false,'error',case when sqlstate='P0001' then sqlerrm else '请求无效或服务暂不可用' end);
end $$;
create or replace function ml_private.runtime_data(v text,k text) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare profile jsonb:=ml_private.version_catalog(v); result jsonb; begin
 perform ml_private.need((profile#>>'{manifest,status}'='playable' or (v in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') and profile#>>'{manifest,status}'='development')),'经典图仅完成数据基础，后续规则未启用');
 result:=profile->'runtimeData'->k; perform ml_private.need(result is not null,'未知版本数据键'); return result;
end $$;
create or replace function ml_private.safe_for_version(v text,r integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$
 select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.runtime_data(v,'cells')) c where v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') or r<=3 or (r<=5 and (c->>'col')::int between 2 and 7) or (r>5 and r<=7 and (c->>'col')::int between 3 and 6) or (r>7 and r<=9 and (c->>'row')::int between 2 and 3 and (c->>'col')::int between 3 and 6) or (r>9 and (c->>'row')::int between 2 and 3 and (c->>'col')::int between 3 and 5) $$;
create or replace function ml_private.allocate_spawns(v text,ids jsonb,s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare profile jsonb:=ml_private.version_catalog(v); id text; region text; groups integer; candidates jsonb; used jsonb:='[]'; cells jsonb:='[]'; cell jsonb; begin
 perform ml_private.need(v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8'),'旧版使用固定坐标出生');
 perform ml_private.need(jsonb_typeof(ids)='array' and jsonb_array_length(ids)=4 and (select count(distinct x) from ml_private.arr(ids) x)=4,'必须有四个不同角色');
 for id in select x#>>'{}' from ml_private.arr(ids) x loop
  candidates:=ml_private.spawn_candidates(v,id); region:=profile#>>array['sourceCatalog','characters',id,'spawnRegion'];
  select count(*) into groups from ml_private.arr(ids) x where profile#>>array['sourceCatalog','characters',x#>>'{}','spawnRegion']=region;
  perform ml_private.need(jsonb_array_length(candidates)>0 and groups<=jsonb_array_length(candidates),'出生地区空格不足');
 end loop;
 for id in select x#>>'{}' from ml_private.arr(ids) x loop
  select jsonb_agg(x) into candidates from ml_private.arr(ml_private.spawn_candidates(v,id)) x where not used @> jsonb_build_array(x);
  s:=ml_private.int(s,jsonb_array_length(candidates)); cell:=candidates->(s->>'_int')::int;
  used:=used||jsonb_build_array(cell); cells:=cells||jsonb_build_array(cell); s:=s-'_int';
 end loop;
 return s||jsonb_build_object('_spawns',cells);
end $$;
create or replace function ml_private.location_basic_cost(v text,cell text) returns integer language sql stable
set search_path=pg_catalog,ml_private as $$ select case when v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and ml_private.region_at(v,cell)='操场' then 0 else 1 end $$;
create or replace function ml_private.location_draw_count(v text,cell text,r integer) returns integer language sql stable
set search_path=pg_catalog,ml_private as $$ select case when r=1 then 0 when v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and ml_private.region_at(v,cell)='高唐农场' then 3 else 2 end $$;
create or replace function ml_private.location_personal_ap(v text,p jsonb,r integer) returns integer language sql stable
set search_path=pg_catalog,ml_private as $$ select case when p->>'character'='character-031' then greatest(6,(p->>'ap')::int) else (p->>'ap')::int end + case when v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and r>1 and ml_private.region_at(v,p->>'cell')='尚德荟' then 1 else 0 end $$;
create or replace function ml_private.location_food_heal(v text,p jsonb,amount integer) returns integer language sql stable
set search_path=pg_catalog,ml_private as $$ select case when (p->>'hp')::int<=0 or p->>'character'='character-027' then 0 else least(greatest(0,(p->>'maxHp')::int-(p->>'hp')::int),amount+case when v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and ml_private.region_at(v,p->>'cell')='XDF' then 1 else 0 end) end $$;
create or replace function ml_private.location_card_allowed(v text,cell text,card text) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select not (v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and ml_private.region_at(v,cell) in ('教学楼','秀松苑') and split_part(card,'#',1) in ('basic-009','basic-010')) $$;
create or replace function ml_private.location_effect_allowed(v text,cell text,card text) returns boolean language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare definition jsonb; begin
 if v not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') or ml_private.region_at(v,cell)<>'办公室' then return true; end if;
 definition:=ml_private.version_catalog(v)#>array['sourceCatalog','cards',split_part(card,'#',1)]; perform ml_private.need(definition is not null,'卡牌未在此版本目录');
 return not (definition->'tags' ? '建民');
end $$;
create or replace function ml_private.location_stops(v text,cell text) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select v in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and ml_private.region_at(v,cell)='山洞' $$;
create or replace function ml_private.location_destinations(s jsonb,a integer,kind text) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; cells jsonb; begin
 perform ml_private.need(kind in ('ship','commute'),'未知地点动作');
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') or s->>'phase'<>'action' or s->'choice'<>'null'::jsonb or (s->>'active')::int<>a or (p->>'hp')::int<=0 or (p->>'ap')::int<1 then return '[]'; end if;
 if kind='ship' and (ml_private.region_at(s->>'version',p->>'cell')<>'飞船' or coalesce(s->'shipUsed','[]') @> jsonb_build_array(a)) then return '[]'; end if;
 cells:=ml_private.version_catalog(s->>'version')#>'{mapDefinition,cells}';
 return (select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(cells) c
 where (kind<>'commute' or c->>'region'='云上学府') and (not coalesce((s->>'farmClosed')::boolean,false) or c->>'region'<>'高唐农场') and not exists (select 1 from ml_private.arr(s->'players') other where (other->>'hp')::int>0 and other->>'cell'=c->>'id'));
end $$;
create or replace function ml_private.classic_relocated(s jsonb,a integer,origin text,cell text) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and ml_private.region_at(s->>'version',origin)<>ml_private.region_at(s->>'version',cell) then s:=jsonb_set(s,array['classic','exposure',a::text],jsonb_build_object('region',null,'streak',0));end if;
 if s->>'version' in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and ml_private.region_at(s->>'version',origin)='山洞' and ml_private.region_at(s->>'version',cell)<>'山洞' then s:=jsonb_set(s,array['classic','caveEnds',a::text],'0');end if;
 return s;
end $$;
create or replace function ml_private.classic_owes_water(s jsonb,a integer,origin text default null) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and not ml_private.stage4_ignore_location(s,a) and not ml_private.classic_native(s,a) and (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage4_board_water(s,s->'players'->a->>'cell',a) else ml_private.classic_water(s,s->'players'->a->>'cell') end) and (origin is null or not (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage4_board_water(s,origin,a) else ml_private.classic_water(s,origin) end)) and (s->'players'->a->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,a)) and jsonb_array_length(s->'players'->a->'hand')>0 $$;
create or replace function ml_private.classic_refresh(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare pool jsonb; safe jsonb; begin
 if s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.classic_refresh_before_patch(s);end if;
 select coalesce(jsonb_agg(r),'[]') into pool from ml_private.arr(ml_private.patch_poison_regions(s->>'version')) r where not (s#>'{classic,poison}' ? (r#>>'{}'));
 s:=ml_private.classic_pick(s,pool,2);s:=jsonb_set(s,'{classic,poison}',(s#>'{classic,poison}')||(s->'_picked'));s:=s-'_picked';
 s:=jsonb_set(s,'{classic,farmClosed}',to_jsonb((s->>'round')::int>=5));
 select coalesce(jsonb_agg(c->'id'),'[]') into safe from ml_private.arr(ml_private.game_data(s,'cells')) c where not (s#>'{classic,poison}' ? (c->>'region'));
 return s||jsonb_build_object('safe',safe,'bomb',null,'forecast',null);
end $$;
create or replace function ml_private.classic_environment(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare hits jsonb:='[]';p jsonb;a integer;region text;old jsonb;danger boolean;streak integer;amount integer;loss integer;begin
 if s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.classic_environment_before_patch(s);end if;
 s:=ml_private.classic_pick(s,ml_private.patch_bomb_regions(s),2,true);s:=jsonb_set(s,'{classic,bombs}',s->'_picked');s:=s-'_picked';s:=jsonb_set(s,'{classic,bombRound}',s->'round');
 for a in 0..3 loop p:=s->'players'->a;if ((p->>'hp')::int<=0 or s->>'version' in ('web-v0.1.7','web-v0.1.8') and not ml_private.stage4_on_board(s,a)) then continue;end if;
  region:=ml_private.region_at(s->>'version',p->>'cell');old:=s#>array['classic','exposure',a::text];danger:=s#>'{classic,poison}' ? region or s#>'{classic,bombs}' ? region;
  streak:=case when not danger then 0 when old->>'region'=region then (old->>'streak')::int+1 else 1 end;
  amount:=case when danger then power(2,least(30,streak-1))::int else 0 end;loss:=least((p->>'hp')::int,greatest(0,amount-(p->>'shield')::int));
  s:=jsonb_set(s,array['classic','exposure',a::text],case when loss>0 then jsonb_build_object('region',region,'streak',streak) else jsonb_build_object('region',null,'streak',0) end);
  hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',amount,'source',null,'category','environment'));
 end loop;return s||jsonb_build_object('_hits',hits);
end $$;
create or replace function ml_private.classic_landings(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare origin jsonb; cell jsonb; nearc jsonb; dr integer; dc integer; r integer; coln integer; result jsonb:='[]'; begin
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') or not ml_private.classic_native(s,a) then return '[]'; end if;
 origin:=ml_private.game_data(s,'map')->(s->'players'->a->>'cell');if (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage4_board_water(s,origin->>'id',a) else origin->>'terrain'<>'land' end) then return '[]'; end if;
 for dr,dc in select * from (values(1,0),(-1,0),(0,1),(0,-1)) d(x,y) loop
  r:=(origin->>'row')::int+dr;coln:=(origin->>'col')::int+dc;cell:=ml_private.game_data(s,'map')->('r'||r||'c'||coln);if (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then cell is null or not ml_private.stage4_board_water(s,cell->>'id',a) else cell->>'terrain' is distinct from 'water' end) then continue; end if;
  while (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then cell is not null and ml_private.stage4_board_water(s,cell->>'id',a) else cell->>'terrain'='water' end) loop if s->>'version'='web-v0.1.8' and ml_private.occupied(s,cell->>'id',a) then cell:=null;exit;end if;r:=r+dr;coln:=coln+dc;cell:=ml_private.game_data(s,'map')->('r'||r||'c'||coln);end loop;
  if cell is null then continue;end if;
  if (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage4_board_entry(s,a,cell->>'id') else ml_private.classic_enter(s,cell->>'id') end) and not ml_private.occupied(s,cell->>'id',-1) then result:=result||jsonb_build_array(cell->'id');
  elsif s->>'version'<>'web-v0.1.8' and ml_private.occupied(s,cell->>'id',-1) then
   for nearc in select * from ml_private.arr(ml_private.game_data(s,'cells')) loop if (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then not ml_private.stage4_board_water(s,nearc->>'id',a) else nearc->>'terrain'='land' end) and ml_private.distance_for_version(s->>'version',cell->>'id',nearc->>'id')=1 and (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage4_board_entry(s,a,nearc->>'id') else ml_private.classic_enter(s,nearc->>'id') end) and not ml_private.occupied(s,nearc->>'id',-1) then result:=result||jsonb_build_array(nearc->'id');end if;end loop;
  end if;
 end loop;
 return (select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.game_data(s,'cells')) c where result ? (c->>'id'));
end $$;
create or replace function ml_private.classic_step_cost(s jsonb,a integer,cell text) returns integer language plpgsql stable
set search_path=pg_catalog,ml_private as $$ begin
 if not ml_private.classic_enter(s,cell) then return null;end if;
 if s->>'version'='web-v0.1.8' and ml_private.classic_native(s,a) and ml_private.stage4_board_water(s,cell,a) then return null;end if;
 if ml_private.classic_landings(s,a) ? cell then return 1;end if;
 if ml_private.distance_for_version(s->>'version',s->'players'->a->>'cell',cell)=1 then return case when (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage4_board_water(s,cell,a) else ml_private.classic_water(s,cell) end) and not ml_private.stage4_ignore_location(s,a) then 2 else 1 end;end if;return null;
end $$;
create or replace function ml_private.classic_walk(s jsonb,path jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int;p jsonb;m jsonb;check_s jsonb;cell text;origin text;cost integer;idx integer:=0;pushed jsonb;tail jsonb;arrival jsonb;water_due boolean;begin
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.classic_walk_before_stage3(s,path,at);end if;
 s:=jsonb_set(s,'{phase}','"moving"');check_s:=s;
 for cell in select x#>>'{}' from ml_private.arr(path) x loop perform ml_private.need(ml_private.legal_steps(check_s) ? cell,'移动路径不合法：检查步数、占用、封闭地区或越水落点');check_s:=ml_private.stage3_collision(check_s,cell);check_s:=check_s-'_pushedTasks';cost:=ml_private.classic_step_cost(check_s,a,cell);check_s:=jsonb_set(check_s,'{movement,remaining}',to_jsonb((check_s#>>'{movement,remaining}')::int-cost));check_s:=jsonb_set(check_s,array['players',a::text,'cell'],to_jsonb(cell));if ml_private.stage4_location_stops(check_s,a,cell) then check_s:=jsonb_set(check_s,'{movement,remaining}','0');end if;end loop;
 for cell in select x#>>'{}' from ml_private.arr(path) x loop perform ml_private.need(ml_private.legal_steps(s) ? cell,'移动路径不合法：检查步数、占用、封闭地区或越水落点');s:=ml_private.stage3_collision(s,cell);pushed:=s->'_pushedTasks';s:=s-'_pushedTasks';p:=s->'players'->a;m:=s->'movement';origin:=p->>'cell';cost:=ml_private.classic_step_cost(s,a,cell);
 m:=m||jsonb_build_object('remaining',(m->>'remaining')::int-cost,'path',(m->'path')||jsonb_build_array(cell));p:=p||jsonb_build_object('cell',cell);s:=ml_private.put_player(s,a,p);s:=ml_private.classic_relocated(s,a,origin,cell);s:=jsonb_set(s,array['stage3','voluntaryMoved',a::text],'true');if not ml_private.occupied(s,cell,a) then m:=m||jsonb_build_object('lastEmpty',cell);end if;if ml_private.stage4_location_stops(s,a,cell) then m:=jsonb_set(m,'{remaining}','0');end if;s:=jsonb_set(s,'{movement}',m);s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell||'，消耗'||cost||'步，余'||(m->>'remaining'));idx:=idx+1;
 select coalesce(jsonb_agg(x order by n),'[]') into tail from jsonb_array_elements(path) with ordinality t(x,n) where n>idx;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then arrival:=ml_private.stage4_arrival_tasks(s,a,origin,cell);water_due:=ml_private.classic_owes_water(s,a,origin);
 if jsonb_array_length(pushed)>0 or water_due or jsonb_array_length(arrival)>0 then s:=ml_private.stage3_prepend(s,pushed||case when water_due then jsonb_build_array(jsonb_build_object('kind','water','actor',a,'data',jsonb_build_object('entry',true))) else '[]'::jsonb end||arrival||jsonb_build_array(jsonb_build_object('kind','walk','path',tail)));return jsonb_set(s,'{phase}','"resolving"');end if;end if;
 if jsonb_array_length(pushed)>0 then s:=ml_private.stage3_prepend(s,pushed||jsonb_build_array(jsonb_build_object('kind','walk','path',tail)));return jsonb_set(s,'{phase}','"resolving"');end if;
 if ml_private.classic_owes_water(s,a,origin) then s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','walk','path',tail)));return ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;end loop;
 if (s#>>'{movement,remaining}')::int=0 then s:=ml_private.settle_movement(s);s:=s||jsonb_build_object('movement',null,'phase','action');end if;return ml_private.resume(s,at);
end $$;
create or replace function ml_private.validate_draft(s jsonb) returns void language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare chosen jsonb; a integer; i integer; o jsonb:=s->'offer'; pool jsonb; begin
 perform ml_private.need(s->>'status' in ('choosing','complete') and s->>'version'='draft-v1' and s->>'catalogVersion' in ('web-v0.1.4','web-v0.1.6','web-v0.1.7','web-v0.1.8') and jsonb_array_length(s->'selected')=4 and (select jsonb_agg(x order by x) from ml_private.arr(s->'order') x)='[0,1,2,3]'::jsonb,'选角状态版本或座位无效');
 select coalesce(jsonb_agg(x),'[]') into chosen from ml_private.arr(s->'selected') x where x<>'null'::jsonb;
 perform ml_private.need(jsonb_array_length(chosen)=(s->>'cursor')::int and (select count(distinct x) from ml_private.arr(chosen) x)=jsonb_array_length(chosen) and not exists(select 1 from ml_private.arr(chosen) x where not ((ml_private.version_catalog(s->>'catalogVersion')#>'{sourceCatalog,characters}') ? (x#>>'{}'))),'已选角色无效或重复');
 for i in 0..3 loop a:=(s->'order'->>i)::int;perform ml_private.need((s->'selected'->a<>'null'::jsonb)=(i<(s->>'cursor')::int),'选角顺序不一致');end loop;
 for pool in select value from jsonb_each(s->'pools') loop perform ml_private.need(not exists(select 1 from ml_private.arr(pool) x where chosen @> jsonb_build_array(x)),'已选角色没有移出牌池');end loop;
 if s->>'status'='complete' then perform ml_private.need((s->>'cursor')::int=4 and o='null'::jsonb,'选角结束状态无效');
 else
  perform ml_private.need((s->>'cursor')::int between 0 and 3 and o<>'null'::jsonb and o->'actor'=s->'order'->(s->>'cursor')::int and o->'id'=s->'offerSerial' and jsonb_array_length(o->'candidates')=3 and (select count(distinct x) from ml_private.arr(o->'candidates') x)=3 and s->'pools'->(s->'teams'->>(o->>'actor')::int) @> (o->'candidates') and (o->>'deadline')::double precision<'Infinity'::double precision,'当前候选或选择期限无效');
 end if;
end $$;
create or replace function ml_private.create_draft(setup jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare catalogv text:=coalesce(setup->>'catalogVersion','web-v0.1.4');s jsonb; pool jsonb; i integer; a integer; overlap_count integer; key text; begin
 perform ml_private.need(jsonb_typeof(setup)='object','选角输入必须为对象');perform ml_private.need(catalogv in ('web-v0.1.4','web-v0.1.6','web-v0.1.7','web-v0.1.8'),'选角目录版本无效');
 perform ml_private.need(at>=0 and at<'Infinity'::double precision,'选角时钟无效');
 perform ml_private.need(jsonb_typeof(setup->'order')='array' and (select jsonb_agg(x order by x) from ml_private.arr(setup->'order') x)='[0,1,2,3]'::jsonb,'选角需要四个固定座位的行动顺序');
 perform ml_private.need(setup->>'mode' in ('ffa','team'),'选角模式无效');perform ml_private.need(jsonb_typeof(setup->'teams')='array' and jsonb_array_length(setup->'teams')=4,'选角阵营需要四个座位');
 if setup->>'mode'='team' then perform ml_private.need((select count(*) from ml_private.arr(setup->'teams') x where x='"机械猴子"')=2 and (select count(*) from ml_private.arr(setup->'teams') x where x='"帝汶家族"')=2,'选角须先分配两名机械猴子和两名帝汶家族');
 else perform ml_private.need(setup->'teams'='["S1","S2","S3","S4"]'::jsonb,'各自为战的选角身份无效');end if;
 perform ml_private.need(jsonb_typeof(setup->'pools')='object','角色阵营池尚未完整配置');
 perform ml_private.need((select jsonb_agg(k order by k) from jsonb_object_keys(setup->'pools') k)=(select jsonb_agg(x order by x) from (select distinct x from ml_private.arr(setup->'teams') x) t),'角色阵营池尚未完整配置');
 for pool in select value from jsonb_each(setup->'pools') loop
  perform ml_private.need(jsonb_typeof(pool)='array' and jsonb_array_length(pool)>=3 and (select count(distinct x) from ml_private.arr(pool) x)=jsonb_array_length(pool) and not exists(select 1 from ml_private.arr(pool) x where not ((ml_private.version_catalog(catalogv)#>'{sourceCatalog,characters}') ? (x#>>'{}'))),'角色池必须包含至少三个不同的已登记角色');
 end loop;
 for i in 0..3 loop
  a:=(setup->'order'->>i)::int;pool:=setup->'pools'->(setup->'teams'->>a);
  select count(*) into overlap_count from jsonb_array_elements(setup->'order') with ordinality t(other,n) where n<=i and exists(select 1 from ml_private.arr(setup->'pools'->(setup->'teams'->>(other#>>'{}')::int)) x where pool @> jsonb_build_array(x));
  perform ml_private.need(jsonb_array_length(pool)>=3+overlap_count,'角色池可能不足三个候选，请补齐阵营或中立分配');
 end loop;
 perform ml_private.need(jsonb_typeof(setup->'random'->'seed')='number' and (setup#>>'{random,seed}')::numeric=trunc((setup#>>'{random,seed}')::numeric) and (setup#>>'{random,seed}')::numeric between 0 and 4294967295,'选角随机源无效');
 s:=jsonb_build_object('mode',setup->'mode','order',setup->'order','teams',setup->'teams','pools',setup->'pools','random',setup->'random','version','draft-v1','catalogVersion',catalogv,'revision',0,'time',at,'status','choosing','cursor',0,'offerSerial',0,'offer',null,'selected','[null,null,null,null]'::jsonb,'events','[]'::jsonb,'requests','[]'::jsonb);
 s:=ml_private.draft_offer(s,at);perform ml_private.validate_draft(s);return s;
end $$;
create or replace function ml_private.cave_ending(s jsonb,a integer) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a;countn integer;paid integer;begin
 s:=s||jsonb_build_object('_hits','[]'::jsonb);
 if s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') or ((p->>'hp')::int<=0 or s->>'version' in ('web-v0.1.7','web-v0.1.8') and not ml_private.stage4_on_board(s,a)) then return s;end if;
 countn:=case when ml_private.region_at(s->>'version',p->>'cell')='山洞' then (s#>>array['classic','caveEnds',a::text])::int+1 else 0 end;
 s:=jsonb_set(s,array['classic','caveEnds',a::text],to_jsonb(case when countn>=3 then 0 else countn end));
 if countn<3 or ml_private.stage4_ignore_location(s,a) then return s;end if;
 paid:=least(2,(p->>'ap')::int);s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-paid));
 s:=ml_private.emit(s,'cave','S'||(a+1)||' 山洞连续停留3个个人回合，野人扣'||paid||'AP并造成1伤害',jsonb_build_object('actor',a,'ap',paid,'amount',1));
 return s||jsonb_build_object('_hits',jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',null,'category','environment')));
end $$;
create or replace function ml_private.stage3_equipped(s jsonb,a integer,definition text) returns boolean language sql immutable
set search_path=pg_catalog,ml_private as $$ select exists(select 1 from ml_private.arr(s#>array['stage3','equipment',a::text]) c where ml_private.stage4_equipment_definition(s,c#>>'{}')=definition and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.character_effect_allowed((s#>array['stage3','equipmentSources',c#>>'{}'])||jsonb_build_object('origin','equipment'),a,s#>>array['players',a::text,'character']))) $$;
create or replace function ml_private.stage3_mount_blocked(s jsonb,a integer) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select (s->>'version' in ('web-v0.1.7','web-v0.1.8') and s#>array['stage4','tongBlocked',a::text] is not null and ml_private.stage4_board_effect(s,a,s#>array['stage4','tongBlocked',a::text])) or
 exists(select 1 from ml_private.arr(s#>array['stage3','equipment',a::text]) c where (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>>array['cards',split_part(c#>>'{}','#',1),'slot']='mount')
 and exists(select 1 from ml_private.arr(s#>'{stage3,horseLocks}') c where (c#>>'{}')::int<>a and (s#>>array['players',c#>>'{}','hp'])::int>0 and ml_private.character_effect_allowed(s#>array['stage3','horseSources',c#>>'{}'],a,s#>>array['players',a::text,'character']) and (s#>>array['players',a::text,'character']<>'character-006' or s#>array['stage3','horseSources',c#>>'{}','actor']=to_jsonb(a) or s#>>array['stage3','horseSources',c#>>'{}','faction']='机械猴子')) $$;
create or replace function ml_private.stage3_can_enter(s jsonb,a integer,cell text) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage4_board_entry(s,a,cell) else (
 (ml_private.runtime_data('web-v0.1.5','map') ? cell) and not (ml_private.stage3_equipped(s,a,'basic-063') and ml_private.runtime_data('web-v0.1.5','map')#>>array[cell,'terrain']='water')) end $$;
create or replace function ml_private.stage3_turn_start(s jsonb,a integer) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare gear text;prior jsonb;begin
 s:=ml_private.stage3_turn_start_before_stage4(s,a);
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then
  for gear in select v#>>'{}' from ml_private.arr(s#>array['stage3','equipment',a::text]) v loop if ml_private.stage4_equipment_definition(s,gear)='basic-060' then prior:=s#>array['stage4','watches',gear];s:=jsonb_set(s,array['stage4','watches',gear],jsonb_build_object('current',s#>array['players',a::text,'cell'],'previous',prior->'current','usedTurn',null));end if;end loop;
  s:=jsonb_set(s,'{stage4,gearMarks}','{}');s:=jsonb_set(s,'{stage4,tongBlocked}',(s#>'{stage4,tongBlocked}')-a::text);if s#>array['stage4','tongPending',a::text] is not null then s:=jsonb_set(s,array['stage4','tongBlocked',a::text],s#>array['stage4','tongPending',a::text]);end if;s:=jsonb_set(s,'{stage4,tongPending}',(s#>'{stage4,tongPending}')-a::text);
  s:=jsonb_set(s,'{stage4,costs}',ml_private.stage4_cost_turn(s#>'{stage4,costs}',(s#>>'{stage3,turn}')::bigint));
  s:=jsonb_set(s,array['stage4','drawBlocked',a::text],s#>array['stage4','downPending',a::text]);
  s:=jsonb_set(s,array['stage4','downPending',a::text],'false');s:=ml_private.stage4_expire_board(s,a);
 end if;return s;
end $$;
create or replace function ml_private.stage3_card_cost(s jsonb,a integer,card text,random_cost integer default null) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; d jsonb:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>array['cards',split_part(card,'#',1)]; n integer; effect jsonb; begin
 perform ml_private.need(d is not null,'卡牌不在阶段三牌池');n:=case when d->>'randomCost'='true' then random_cost else (d->>'cost')::int end;
 perform ml_private.need(n is not null and (n>=0 or s->>'version' in ('web-v0.1.7','web-v0.1.8') and n>=-1),'请先锁定该实体牌的随机费用');
 effect:=jsonb_build_object('origin','card','actor',a,'faction',p->'faction','roleModifiers','[]'::jsonb);
 if n>0 and ((p->>'character'='character-006' and ml_private.version_catalog('web-v0.1.5')#>array['sourceCatalog','cards',d->>'id','tags'] ? '帝汶') or (p->>'character'='character-048' and d->>'id' in ('basic-054','basic-063','basic-066','basic-067','basic-071','basic-072')) or s#>>array['stage3','jjFree',a::text]='true') then
 n:=0;effect:=jsonb_set(effect,'{roleModifiers}',jsonb_build_array(jsonb_build_object('actor',a,'kind','cost')));end if;
 return jsonb_build_object('cost',n,'effect',effect);
end $$;
create or replace function ml_private.stage3_gain_ap(s jsonb,a integer,amount integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; collector integer; taken integer:=0; result jsonb; begin
 perform ml_private.need(amount>=0,'新增AP必须为非负整数');
 if (p->>'hp')::int<=0 then return s||jsonb_build_object('_gain',jsonb_build_object('gained',0,'collector',null,'taken',0));end if;
 select (q->>'seat')::int into collector from ml_private.arr(s->'players') q where (q->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,(q->>'seat')::int) and not ml_private.stage3_equipped(s,a,'basic-065')) and q->>'character'='character-043' and (q->>'seat')::int<>a and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',q->'seat','roleModifiers','[]'::jsonb),a,p->>'character') limit 1;
 if collector is not null then taken:=least(amount,greatest(0,(p->>'ap')::int+amount-7));end if;
 s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((p->>'ap')::int+amount-taken));
 if collector is not null then s:=jsonb_set(s,array['players',collector::text,'ap'],to_jsonb((s#>>array['players',collector::text,'ap'])::int+taken));end if;
 return s||jsonb_build_object('_gain',jsonb_build_object('gained',amount-taken,'collector',case when taken>0 then collector else null end,'taken',taken));
end $$;
create or replace function ml_private.stage3_death(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare r jsonb:=s->'stage3'; c jsonb; locks jsonb; begin
 r:=jsonb_set(r,array['deathTurns',a::text],r->'turn');r:=jsonb_set(r,array['jjFree',a::text],'false');r:=jsonb_set(r,array['jjExposed',a::text],'false');
 for c in select * from ml_private.arr(r#>array['equipment',a::text]) loop s:=jsonb_set(s,'{discard}',(s->'discard')||jsonb_build_array(c));if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=jsonb_set(s,array['stage4','terrainIgnore',a::text],'false');s:=jsonb_set(s,'{stage4,watches}',(s#>'{stage4,watches}')-(c#>>'{}'));s:=jsonb_set(s,'{stage4,copies}',(s#>'{stage4,copies}')-(c#>>'{}'));s:=jsonb_set(s,'{stage4,durability}',(s#>'{stage4,durability}')-(c#>>'{}'));end if;r:=jsonb_set(r,'{equipmentSources}',(r->'equipmentSources')-(c#>>'{}'));end loop;
 r:=jsonb_set(r,array['equipment',a::text],'[]');select coalesce(jsonb_agg(x),'[]') into locks from ml_private.arr(r->'horseLocks') x where (x#>>'{}')::int<>a;
 r:=jsonb_set(r,'{horseLocks}',locks);r:=jsonb_set(r,'{horseSources}',(r->'horseSources')-a::text);return jsonb_set(s,'{stage3}',r);
end $$;
create or replace function ml_private.stage3_revival_cells(s jsonb,a integer,farm_closed boolean) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; region text; result jsonb; begin
 if (p->>'hp')::int>0 or s#>array['stage3','deathTurns',a::text]='null'::jsonb or (s#>>'{stage3,completedTurn}')::int>(s#>>array['stage3','deathTurns',a::text])::int then return '[]';end if;
 region:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>>array['characters',p->>'character','spawnRegion'];
 select coalesce(jsonb_agg(c->'id' order by ord),'[]') into result from jsonb_array_elements(ml_private.runtime_data('web-v0.1.5','cells')) with ordinality t(c,ord) where (s->>'version'<>'web-v0.1.8' or not ml_private.classic_native(s,a) or not ml_private.stage4_board_water(s,c->>'id',a) or jsonb_array_length(ml_private.playtest_nearest_shore(jsonb_set(jsonb_set(s,array['players',a::text,'hp'],'1'),array['players',a::text,'cell'],c->'id'),a))>0) and c->>'region'=region and not (farm_closed and region='高唐农场') and not exists(select 1 from ml_private.arr(s->'players') q where (q->>'hp')::int>0 and q->>'cell'=c->>'id');return result;
end $$;
create or replace function ml_private.stage3_equipment_options(s jsonb,a integer,card text) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare definition text:=split_part(card,'#',1); d jsonb:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>array['cards',definition]; cards jsonb; begin
 if d is null or d->>'type'<>'equipment' or (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then exists(select 1 from ml_private.arr(s#>array['stage3','equipment',a::text]) item where split_part(item#>>'{}','#',1)=definition) else ml_private.stage3_equipped(s,a,definition) end) then return '{"allowed":false,"required":false,"cards":[]}'::jsonb;end if;
 select coalesce(jsonb_agg(c),'[]') into cards from ml_private.arr(s#>array['stage3','equipment',a::text]) c where (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>>array['cards',split_part(c#>>'{}','#',1),'slot']=d->>'slot';
 return jsonb_build_object('allowed',true,'required',jsonb_array_length(cards)>=case when d->>'slot'='hand' then 2 else 1 end,'cards',cards);
end $$;
create or replace function ml_private.stage3_card_allowed(s jsonb,target integer,card text,effect jsonb) returns boolean language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->target; tags jsonb; begin
 if (s->>'version' in ('web-v0.1.7','web-v0.1.8') and s#>>array['stage4','offMap',target::text]='true') or p is null or not ml_private.character_effect_allowed(effect,target,p->>'character') then return false;end if;
 if s->>'version'<>'web-v0.1.8' and p->>'character'='character-006' and (effect->>'actor')::int<>target and effect->>'faction'<>'机械猴子' then return false;end if;
 tags:=ml_private.version_catalog('web-v0.1.5')#>array['sourceCatalog','cards',split_part(card,'#',1),'tags'];
 if p->>'character'='character-005' and tags ? '建民' then return false;end if;return true;
end $$;
create or replace function ml_private.stage3_role_targets(s jsonb,a integer,origin text) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(p->'seat' order by ord),'[]') from jsonb_array_elements(s->'players') with ordinality t(p,ord) where (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,(p->>'seat')::int)) and (p->>'seat')::int<>a and ml_private.character_effect_allowed(jsonb_build_object('origin',origin,'actor',a,'roleModifiers','[]'::jsonb),(p->>'seat')::int,p->>'character') $$;
create or replace function ml_private.stage3_jj_targets(s jsonb,a integer,card text,targets jsonb,effect jsonb) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare d jsonb:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>array['cards',split_part(card,'#',1)]; jj integer; begin
 if d is null or d->>'type'='equipment' or (d->>'type'='response' and not (d->>'id'='basic-002' and s#>>array['players',a::text,'character']='character-023')) or d->>'id'='basic-037' then return jsonb_build_object('targets',targets,'effect',effect);end if;
 select (p->>'seat')::int into jj from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and p->>'character'='character-003' and (p->>'seat')::int<>a and s#>>array['stage3','jjExposed',p->>'seat']='true' limit 1;
 if jj is null or (s->>'version' in ('web-v0.1.7','web-v0.1.8') and (not ml_private.stage4_on_board(s,jj) or d->>'type'='attack' and coalesce(d->>'group','false')<>'true' and (ml_private.stage4_single_protected(s,a,jj) or ml_private.stage4_lmm_target(s,a,targets) is not null))) or targets @> jsonb_build_array(jj) then return jsonb_build_object('targets',targets,'effect',effect);end if;
 effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',jj,'kind','target')));return jsonb_build_object('targets',targets||jsonb_build_array(jj),'effect',effect);
end $$;
create or replace function ml_private.stage3_monkey_targets(s jsonb,a integer) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb:=s->'players'->a; boost boolean:=p->>'character'='character-045'; result jsonb; begin
 if not boost and ml_private.runtime_data('web-v0.1.5','map')#>>array[p->>'cell','region'] in ('教学楼','秀松苑') then return '[]';end if;
 select coalesce(jsonb_agg(q->'seat' order by ord),'[]') into result from jsonb_array_elements(s->'players') with ordinality t(q,ord) where (q->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,(q->>'seat')::int)) and (q->>'seat')::int<>a and (s->>'mode'='ffa' or q->'team'<>p->'team') and not (q->>'character'='character-027' and jsonb_array_length(q->'hand')=1) and (boost or ml_private.stage3_same_near(p->>'cell',q->>'cell'));return result;
end $$;
create or replace function ml_private.stage3_empty_entry(s jsonb,a integer,cell text,ignored jsonb default '[]') returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select (s->>'version'<>'web-v0.1.8' or ml_private.playtest_relocation_cell(s,a,s#>>array['players',a::text,'cell'],cell,ignored) is not null) and coalesce(ml_private.runtime_data('web-v0.1.5','map') ? cell and not (coalesce((s->>'farmClosed')::boolean,false) and ml_private.runtime_data('web-v0.1.5','map')#>>array[cell,'region']='高唐农场') and ml_private.stage3_can_enter(s,a,cell) and not exists(select 1 from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or ml_private.stage4_on_board(s,(p->>'seat')::int)) and p->>'cell'=cell and not (ignored @> jsonb_build_array(p->'seat'))),false) $$;
create or replace function ml_private.stage3_elbow_targets(s jsonb,a integer,converted boolean) returns jsonb language sql stable
set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(t order by ord),'[]') from jsonb_array_elements(ml_private.stage3_role_targets(s,a,case when converted then 'role-active' else 'role-locked' end)) with ordinality x(t,ord) where (s->>'version' not in ('web-v0.1.7','web-v0.1.8') or not ml_private.stage4_single_protected(s,a,(t#>>'{}')::int)) and s#>>array['players',a::text,'character']='character-023' and ml_private.runtime_data('web-v0.1.5','map')#>>array[s#>>array['players',a::text,'cell'],'region']=ml_private.runtime_data('web-v0.1.5','map')#>>array[s#>>array['players',t#>>'{}','cell'],'region'] $$;
create or replace function ml_private.stage3_begin_card(s jsonb,a integer,card text,definition text,targets jsonb,effect jsonb,at double precision,response_to integer default null) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare flow jsonb:=s->'cardStack'; parent jsonb:=(flow->'stack')->-1; easy integer; pending jsonb;begin
 perform ml_private.need(at>=0 and at<'Infinity'::double precision,'卡牌窗口时钟无效');
 perform ml_private.need(s->'resolving' ? card and not exists(select 1 from ml_private.arr(flow->'stack') c where c->>'card'=card),'待结算实体牌无效');
 if response_to is not null then perform ml_private.need((parent->>'serial')::int=response_to and parent->'counter'='null'::jsonb,'父牌尚不可响应');end if;
 select (p->>'seat')::int into easy from ml_private.arr(s->'players') p where (p->>'hp')::int>0 and p->>'character'='character-002' and (p->>'ap')::int>=1 limit 1;
 pending:=jsonb_build_object('serial',(flow->>'serial')::int+1,'actor',a,'card',card,'definition',definition,'targets',targets,'effect',effect,'cancelled','[]'::jsonb,'elbows','[]'::jsonb,'countered',false,'counter',case when easy is null then null else jsonb_build_object('actor',easy,'deadline',at+case when s->>'version'='web-v0.1.8' then 30000 else 10000 end) end,'responseTo',response_to,'responseActor',case when response_to is null then null else a end);
 return jsonb_set(s,'{cardStack}',jsonb_build_object('serial',pending->'serial','stack',(flow->'stack')||jsonb_build_array(pending)));
end $$;
create or replace function ml_private.stage3_close_card(s jsonb) returns jsonb language plpgsql immutable
set search_path=pg_catalog,ml_private as $$ declare cards jsonb:=s#>'{cardStack,stack}';c jsonb:=cards->-1;parent jsonb:=cards->-2;begin
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8') or c#>'{stage4,counter}' is null then return ml_private.stage3_close_card_before_stage4(s);end if;
 perform ml_private.need(c->'counter'='null'::jsonb,'反制尚未结束');perform ml_private.need(parent->'serial'=c->'responseTo','响应父牌已过期');
 if c->>'countered'<>'true' and c#>>'{stage4,counterEffective}'='true' then cards:=jsonb_set(cards,array[(jsonb_array_length(cards)-2)::text,'countered'],'true');end if;
 s:=jsonb_set(s,'{cardStack,stack}',cards-(jsonb_array_length(cards)-1));s:=jsonb_set(s,'{resolving}',(s->'resolving')-(c->>'card'));
 return jsonb_set(s,'{discard}',(s->'discard')||jsonb_build_array(c->'card'))||jsonb_build_object('_closed',c);
end $$;
create or replace function ml_private.create_game_before_stage3(setup jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare rulev text:=coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end); s jsonb; chars jsonb; pair jsonb; teams jsonb; deck jsonb; firstn integer; a integer; c jsonb; id text; players jsonb:='[]'; randomj jsonb; begin
 perform ml_private.runtime_data(rulev,'characterIds');
 perform ml_private.need(jsonb_typeof(setup)='object' and setup->>'mode' in ('ffa','team') and at>=0,'开局输入无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(setup->'seats') x)='[0,1,2,3]'::jsonb,'必须有四个固定座位');
 perform ml_private.need(jsonb_typeof(setup->'seed')='number' and (setup->>'seed')::numeric=trunc((setup->>'seed')::numeric) and (setup->>'seed')::numeric between 0 and 4294967295,'种子必须为uint32');
 randomj:=jsonb_build_object('seed',setup->'seed','dice',coalesce(setup->'dice','[]'),'bombs',coalesce(setup->'bombs','[]'),'reshuffles',coalesce(setup->'reshuffles','[]'),'sortedReshuffles',coalesce(setup->'sortedReshuffles','false'));
 if coalesce((setup->>'secure')::boolean,false) then randomj:=randomj||jsonb_build_object('secure',true); end if;
 s:=jsonb_build_object('version',rulev,'random',randomj);
 if setup ? 'characters' then chars:=setup->'characters'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'characterIds')); chars:=s->'_shuffle'; s:=s-'_shuffle'; end if;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(chars) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x),'四角色必须完整且唯一');
 s:=ml_private.shuffle(s,'[0,1,2,3]'); pair:=jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1); s:=s-'_shuffle';
 teams:=setup->'teams'; if teams is null then teams:='[]'; for a in 0..3 loop teams:=teams||to_jsonb(case when pair @> jsonb_build_array(a) then 'A' else 'B' end); end loop; end if;
 if setup->>'mode'='team' then perform ml_private.need(jsonb_array_length(teams)=4 and (select count(*) from ml_private.arr(teams) x where x='"A"')=2 and (select count(*) from ml_private.arr(teams) x where x='"B"')=2,'团战必须2对2'); end if;
 if setup ? 'first' then firstn:=(setup->>'first')::int; else s:=ml_private.int(s,4); firstn:=(s->>'_int')::int; s:=s-'_int'; end if; perform ml_private.need(firstn between 0 and 3,'首位无效');
 if setup ? 'deck' then deck:=setup->'deck'; else s:=ml_private.shuffle(s,ml_private.game_data(s,'allCards')); deck:=s->'_shuffle'; s:=s-'_shuffle'; end if;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(deck) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'牌堆必须64实体完整排列');
 if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=ml_private.allocate_spawns(rulev,chars,s); end if;
 for a in 0..3 loop id:=chars->>a; c:=ml_private.game_data(s,'characters')->id;
  players:=players||jsonb_build_array(jsonb_build_object('seat',a,'character',id,'team',case when setup->>'mode'='team' then teams->>a else 'S'||(a+1) end,'faction',c->'faction','hp',c->'hp','maxHp',c->'hp','ap',5,'shield',0,'cell',case when rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s->'_spawns'->a else c->'spawn' end,'hand','[]'::jsonb,'moved',false,'attacks',0,'skillUsed',false,'rewarded','[]'::jsonb,'kills',0,'damage',0,'eliminated',null));
 end loop;
 s:=s||jsonb_build_object('version',coalesce(setup->>'ruleVersion',case when coalesce((setup->>'secure')::boolean,false) then 'web-v0.1.5' else 'web-v0.1.1' end),'revision',0,'time',at,'mode',setup->'mode','players',players,'order',(select jsonb_agg((firstn+i)%4) from generate_series(0,3) i),'cursor',0,'active',firstn,'round',1,'phase','resolving','deck',deck,'discard','[]'::jsonb,'resolving','[]'::jsonb,'queue','[]'::jsonb,'choice',null,'choiceSerial',0,'attack',null,'movement',null,'safe',ml_private.safe_for_version(s->>'version',1),'bomb',null,'forecast',null,'clock',jsonb_build_object('remaining',60000,'since',null),'events','[]'::jsonb,'eventSerial',0,'batch',0,'reshuffleCount',0,'seen','[]'::jsonb,'result',null);
 s:=s-'_spawns'; if rulev in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=s||jsonb_build_object('classic',jsonb_build_object('poison','[]'::jsonb,'bombs','[]'::jsonb,'exposure',(select jsonb_agg(jsonb_build_object('region',null,'streak',0)) from generate_series(0,3)),'shipUsed','[]'::jsonb,'farmClosed',false)); end if;
 if rulev in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=jsonb_set(s,'{classic}',(s->'classic')||jsonb_build_object('bombRound',0,'caveEnds','[0,0,0,0]'::jsonb));end if;
 s:=ml_private.emit(s,'setup','四人'||case when setup->>'mode'='ffa' then '各自为战' else '2对2' end||' · '||(s->>'version')); for a in 0..3 loop s:=ml_private.draw(s,a,4); end loop;
 s:=ml_private.start_round(s,at); perform ml_private.validate(s); return s;
end $$;
create or replace function ml_private.pump_before_stage3(s jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare task jsonb; a integer; p jsonb; countn integer; cards jsonb; kind text; cells jsonb; cursor integer; guard integer:=0; begin
 while s->'choice'='null'::jsonb and s->>'phase'<>'over' and jsonb_array_length(s->'queue')>0 loop
  guard:=guard+1; perform ml_private.need(guard<200,'内部流程未收敛'); task:=s->'queue'->0; s:=jsonb_set(s,'{queue}',(s->'queue')-0); a:=coalesce((task->>'actor')::int,(s->>'active')::int); p:=s->'players'->a;
  case task->>'kind'
   when 'water' then if ml_private.classic_owes_water(s,a) then s:=ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;
   when 'classic-start' then
    for a in 0..3 loop p:=s->'players'->a;if (p->>'hp')::int>0 then p:=p||jsonb_build_object('skillUsed',false,'rewarded','[]'::jsonb);if (p->>'ap')::int<5 and (s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') or p->>'character'<>'character-031') then p:=p||jsonb_build_object('ap',(p->>'ap')::int+3);s:=ml_private.put_player(s,a,p);s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 轮开始获得3AP → '||(p->>'ap'));end if;s:=ml_private.put_player(s,a,p);end if;end loop;
    s:=ml_private.classic_refresh(s);s:=ml_private.emit(s,'round','第'||(s->>'round')||'轮开始，毒区：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,poison}') x)||case when (s#>>'{classic,farmClosed}')::boolean then '；高唐农场已封闭' else '' end);s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','after-env'))||(s->'queue'));
   when 'round-next' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=s||jsonb_build_object('round',(s->>'round')::int+1,'cursor',0);s:=ml_private.start_round(s,at);end if;
   when 'walk' then s:=ml_private.classic_walk(s,coalesce(task->'path','[]'),at);
   when 'after-env' then s:=ml_private.finish(s,false,at); if s->>'phase'<>'over' then cursor:=0; while (s->'players'->(s->'order'->>cursor)::int->>'hp')::int<=0 loop cursor:=cursor+1; end loop; s:=s||jsonb_build_object('cursor',cursor,'queue',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor))||(s->'queue')); end if;
   when 'turn-start' then
    if s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=jsonb_set(s,'{classic,shipUsed}',(select coalesce(jsonb_agg(x),'[]') from ml_private.arr(s#>'{classic,shipUsed}') x where x<>to_jsonb(a)));end if;
    s:=s||jsonb_build_object('active',a,'phase','resolving','clock',jsonb_build_object('remaining',60000,'since',at)); p:=p||jsonb_build_object('moved',false,'attacks',0); s:=ml_private.put_player(s,a,p);
    if p->>'character'='character-031' and (p->>'ap')::int<6 then p:=p||jsonb_build_object('ap',6); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 行动开始补至6AP'); end if;
    if ml_private.stage4_location_ap(s,a)>(p->>'ap')::int then p:=p||jsonb_build_object('ap',ml_private.stage4_location_ap(s,a)); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'ap',ml_private.name(s,a)||' 尚德荟获得1AP → '||(p->>'ap')); end if;
    s:=ml_private.emit(s,'turn',ml_private.name(s,a)||' 开始行动'); if (s->>'round')::int>1 then s:=ml_private.draw(s,a,ml_private.stage4_location_draw(s,a)); end if;
    s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','action'))||(s->'queue')); if p->>'character'='character-027' then s:=ml_private.select_choice(s,'draw-start',a,at); end if;
   when 'action' then s:=jsonb_set(s,'{phase}','"action"'); s:=ml_private.resume(s,at);
   when 'end-draw' then s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind',case when s->>'version' in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then 'cave-end' else 'discard' end))||(s->'queue')); if p->>'character'='character-027' and (p->>'hp')::int>0 and ml_private.budget(s,at)>0 then s:=ml_private.select_choice(s,'draw-end',a,at); end if;
   when 'cave-end' then s:=ml_private.cave_ending(s,a);if jsonb_array_length(s->'_hits')>0 then s:=ml_private.damage(s,s->'_hits',true);s:=jsonb_set(s,'{queue}',(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a))||(s->'queue'));s:=s-'_triggers';else s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','cave-after','actor',a))||(s->'queue'));end if;s:=s-'_hits';
   when 'cave-after' then s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','discard','actor',a))||(s->'queue'));end if;
   when 'discard' then countn:=jsonb_array_length(p->'hand')-greatest(0,floor((p->>'hp')::numeric)::int); s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','next'))||(s->'queue')); if (p->>'hp')::int>0 and countn>0 then s:=ml_private.select_choice(s,'discard',a,at,jsonb_build_object('count',countn,'cards',p->'hand')); end if;
   when 'next' then s:=ml_private.next_turn(s,at);
   when 'response' then if not (s#>'{attack,cancelled}' @> jsonb_build_array(a)) and s->'attack'<>'null'::jsonb and (p->>'hp')::int>0 then
    select coalesce(jsonb_agg(c),'[]') into cards from ml_private.arr(p->'hand') c where ((ml_private.rule_card(s,c#>>'{}')->>'id'='basic-001' and (s->>'version' not in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') or ml_private.rule_card(s,s#>>'{attack,card}')->>'id'<>'basic-009')) or (ml_private.rule_card(s,c#>>'{}')->>'id'='basic-002' and ml_private.rule_card(s,s#>>'{attack,card}')->>'id'='basic-008')) and (p->>'ap')::int>=(ml_private.rule_card(s,c#>>'{}')->>'cost')::int;
    if jsonb_array_length(cards)>0 then s:=ml_private.select_choice(s,'response',a,at,jsonb_build_object('cards',cards)); end if; end if;
   when 'resolve' then s:=ml_private.resolve_attack(s);
   when 'cleanup' then s:=s||jsonb_build_object('discard',(s->'discard')||(s->'resolving'),'resolving','[]'::jsonb,'attack',null); s:=ml_private.finish(s,false,at);
    if s->>'phase'<>'over' then if (s->'players'->(s->>'active')::int->>'hp')::int>0 then s:=jsonb_set(s,'{phase}','"action"'); s:=ml_private.resume(s,at); else s:=jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','next'))||(s->'queue')); end if; end if;
   when 'trigger' then
    if (p->>'hp')::int<=0 then continue; end if; kind:=task->>'trigger';
    if kind='lemon-reward' then if task ? 'source' and not (s->'players'->(task->>'source')::int->'rewarded' @> jsonb_build_array(a)) then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('source',task->'source')); end if;
    elsif not (p->>'skillUsed')::boolean then
     if (kind='lemon-support' and (p->>'ap')::int>=1) or (kind='runner-roll' and (p->>'ap')::int>=2) then s:=ml_private.select_choice(s,kind,a,at); end if;
     if kind='teleport' then cells:=ml_private.teleport_cells(s,a); if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,kind,a,at,jsonb_build_object('cells',cells)); end if; end if;
    end if;
   else raise exception '未知内部任务';
  end case;
 end loop; return s;
end $$;
create or replace function ml_private.damage_before_stage3(s jsonb,hits jsonb,environment boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare h jsonb; p jsonb; a integer; src integer; blocked integer; loss integer; injured jsonb:='[]'; triggers jsonb:='[]'; begin
 s:=jsonb_set(s,'{batch}',to_jsonb((s->>'batch')::int+1));
 for h in select * from ml_private.arr(hits) loop
  a:=(h->>'target')::int; p:=s->'players'->a; if (p->>'hp')::int<=0 or (h->>'amount')::int<=0 then continue; end if;
  blocked:=case when environment and s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then 0 else least((p->>'shield')::int,(h->>'amount')::int) end; loss:=least((p->>'hp')::int,(h->>'amount')::int-blocked);
  p:=p||jsonb_build_object('shield',(p->>'shield')::int-blocked,'hp',(p->>'hp')::int-loss); s:=ml_private.put_player(s,a,p); src:=(h->>'source')::int;
  if src is not null and ml_private.enemy(s,src,a) then s:=ml_private.put_player(s,src,(s->'players'->src)||jsonb_build_object('damage',(s->'players'->src->>'damage')::int+loss,'kills',(s->'players'->src->>'kills')::int+case when (p->>'hp')::int=0 and loss>0 then 1 else 0 end)); end if;
  s:=ml_private.emit(s,'damage',ml_private.name(s,a)||' '||case when environment then '环境' else '普通' end||'伤害'||(h->>'amount')||'，护盾抵挡'||blocked||'，实际失血'||loss,h||jsonb_build_object('blocked',blocked,'loss',loss,'batch',s->'batch'));
  if loss>0 then injured:=injured||jsonb_build_array(h||jsonb_build_object('loss',loss)); end if;
 end loop;
 for a in 0..3 loop p:=s->'players'->a; if (p->>'hp')::int=0 and p->'eliminated'='null'::jsonb then
  s:=s||jsonb_build_object('discard',(s->'discard')||(p->'hand')); p:=p||jsonb_build_object('eliminated',s->'batch','ap',0,'shield',0,'hand','[]'::jsonb); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'eliminate',ml_private.name(s,a)||' 淘汰（批次'||(s->>'batch')||'）'); end if; end loop;
 for a in select ml_private.n(x)::int from ml_private.arr(s->'order') x loop
  p:=s->'players'->a; select x into h from ml_private.arr(injured) x where (x->>'target')::int=a limit 1;
  if h is null or (p->>'hp')::int<=0 then continue; end if; src:=(h->>'source')::int;
  if p->>'character'='character-004' then
   if src is not null and h->>'category'='attack' and ml_private.enemy(s,src,a) and (s->'players'->src->>'hp')::int>0 and not (p->'rewarded' @> jsonb_build_array(src)) then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',src,'trigger','lemon-reward','source',a)); end if;
   triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','lemon-support'));
  elsif p->>'character'='character-031' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','runner-roll'));
  elsif p->>'character'='character-037' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','teleport')); end if;
 end loop; return s||jsonb_build_object('_triggers',triggers);
end $$;
create or replace function ml_private.finish_before_stage3(s jsonb,forced boolean,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare groups jsonb:='[]'; rows jsonb:='[]'; ids jsonb; p jsonb; rowj jsonb; a integer; alive_count integer; hp integer; max_hp integer; kills integer; dmg integer; elim bigint; survivors integer:=0; i integer; j integer; cmp bigint; leftj jsonb; rightj jsonb; winners jsonb:='[]'; rankn integer; tied boolean; begin
 if s->>'mode'='ffa' then for a in 0..3 loop groups:=groups||jsonb_build_array(jsonb_build_array(a)); end loop;
 else groups:=jsonb_build_array((select jsonb_agg(member->'seat') from ml_private.arr(s->'players') member where member->>'team'='A'),(select jsonb_agg(member->'seat') from ml_private.arr(s->'players') member where member->>'team'='B')); end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then select coalesce(jsonb_agg(g),'[]') into groups from ml_private.arr(groups) g where g<>'null'::jsonb and g<>'[]'::jsonb;end if;
 for ids in select * from ml_private.arr(groups) loop
  alive_count:=0; hp:=0; max_hp:=0; kills:=0; dmg:=0; elim:=0;
  for a in select ml_private.n(x)::int from ml_private.arr(ids) x loop p:=s->'players'->a;
   alive_count:=alive_count+case when (p->>'hp')::int>0 then 1 else 0 end; hp:=hp+(p->>'hp')::int; max_hp:=max_hp+(p->>'maxHp')::int; kills:=kills+(p->>'kills')::int; dmg:=dmg+(p->>'damage')::int; elim:=greatest(elim,coalesce((p->>'eliminated')::bigint,1000000000000000)); end loop;
  if alive_count>0 then survivors:=survivors+1; end if;
  rows:=rows||jsonb_build_array(jsonb_build_object('label',case when s->>'mode'='ffa' then ml_private.name(s,(ids->>0)::int) else (s->'players'->(ids->>0)::int->>'team')||'队' end,'players',ids,'rank',0,'alive',alive_count,'hp',hp,'maxHp',max_hp,'kills',kills,'damage',dmg,'_elim',elim));
 end loop;
 if not forced and survivors>1 then return s; end if;
 -- Stable insertion sort, using exact integer cross multiplication for HP ratios.
 for i in 1..jsonb_array_length(rows)-1 loop j:=i;
  while j>0 loop leftj:=rows->(j-1); rightj:=rows->j;
   if (leftj->>'alive')::int>0 and (rightj->>'alive')::int>0 then
    cmp:=(rightj->>'alive')::bigint-(leftj->>'alive')::bigint;
    if cmp=0 then cmp:=(rightj->>'hp')::bigint*(leftj->>'maxHp')::bigint-(leftj->>'hp')::bigint*(rightj->>'maxHp')::bigint; end if;
    if cmp=0 then cmp:=(rightj->>'kills')::bigint-(leftj->>'kills')::bigint; end if;
    if cmp=0 then cmp:=(rightj->>'damage')::bigint-(leftj->>'damage')::bigint; end if;
   elsif (leftj->>'alive')::int>0 then cmp:=-1; elsif (rightj->>'alive')::int>0 then cmp:=1; else cmp:=(rightj->>'_elim')::bigint-(leftj->>'_elim')::bigint; end if;
   exit when cmp<=0;
   rows:=jsonb_set(rows,array[(j-1)::text],rightj); rows:=jsonb_set(rows,array[j::text],leftj); j:=j-1;
  end loop;
 end loop;
 for i in 0..jsonb_array_length(rows)-1 loop
  rowj:=rows->i; rankn:=i+1;
  if i>0 then leftj:=rows->(i-1);
   if ((leftj->>'alive')::int=0 and (rowj->>'alive')::int=0 and leftj->'_elim'=rowj->'_elim') or
   ((leftj->>'alive')::int>0 and (rowj->>'alive')::int>0 and leftj->'alive'=rowj->'alive' and (leftj->>'hp')::bigint*(rowj->>'maxHp')::bigint=(rowj->>'hp')::bigint*(leftj->>'maxHp')::bigint and leftj->'kills'=rowj->'kills' and leftj->'damage'=rowj->'damage') then rankn:=(leftj->>'rank')::int; end if;
  end if;
  rows:=jsonb_set(rows,array[i::text],rowj||jsonb_build_object('rank',rankn));
 end loop;
 tied:=survivors=0 or (select count(*) from ml_private.arr(rows) r where (r->>'rank')::int=1)>1;
 if not tied then for rowj in select * from ml_private.arr(rows) loop if (rowj->>'rank')::int=1 then winners:=winners||(rowj->'players'); end if; end loop; end if;
 select jsonb_agg(r-'_elim') into rows from ml_private.arr(rows) r;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=ml_private.stage4_discard_interrupts(s);end if;
 s:=s||jsonb_build_object('result',jsonb_build_object('reason',case when tied then 'draw' when forced then 'round-limit' else 'natural' end,'winners',winners,'ranking',rows),'phase','over','choice',null,'queue','[]'::jsonb,'movement',null);
 s:=ml_private.pause(s,at); return ml_private.emit(s,'result',case when tied then '对局结束：平局' else '对局结束：'||(rows->0->>'label')||' 获胜' end,s->'result');
end $$;
create or replace function ml_private.validate_before_stage3(s jsonb) returns void language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare p jsonb; zones jsonb; a integer; b integer; begin
 perform ml_private.need(s->>'version' in ('web-v0.1.1','web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and jsonb_array_length(s->'players')=4 and (s->>'round')::int>=1 and (s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') or (s->>'round')::int<=12),'状态版本/轮次/人数无效');
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(s->'order') x)='[0,1,2,3]'::jsonb and (select jsonb_agg(member->'character' order by member->'character') from ml_private.arr(s->'players') member)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'characterIds')) x),'角色/顺序无效');
 zones:=(s->'deck')||(s->'discard')||(s->'resolving');
 for a in 0..3 loop p:=s->'players'->a; zones:=zones||(p->'hand');
  perform ml_private.need((p->>'hp')::numeric=trunc((p->>'hp')::numeric) and (p->>'hp')::int between 0 and (p->>'maxHp')::int and p->'maxHp'=ml_private.game_data(s,'characters')->(p->>'character')->'hp','生命状态无效');
  perform ml_private.need((p->>'ap')::numeric=trunc((p->>'ap')::numeric) and (p->>'ap')::int>=0 and (p->>'shield')::numeric=trunc((p->>'shield')::numeric) and (p->>'shield')::int between 0 and 2,'AP/护盾无效');
  perform ml_private.need(ml_private.game_data(s,'map') ? (p->>'cell'),'位置无效');
  if (p->>'hp')::int=0 then perform ml_private.need((p->>'ap')::int=0 and (p->>'shield')::int=0 and p->'hand'='[]'::jsonb and p->'eliminated'<>'null'::jsonb,'淘汰清理无效'); end if;
  for b in 0..a-1 loop if (p->>'hp')::int>0 and (s->'players'->b->>'hp')::int>0 and p->'cell'=s->'players'->b->'cell' then perform ml_private.need((s->>'phase'='moving' or s#>>'{choice,kind}'='water-discard') and s->'movement'<>'null'::jsonb,'稳定落点不能重叠'); end if; end loop;
 end loop;
 perform ml_private.need((select jsonb_agg(x order by x) from ml_private.arr(zones) x)=(select jsonb_agg(x order by x) from ml_private.arr(ml_private.game_data(s,'allCards')) x),'64张实体不守恒或实体重复');
 if s->>'version' in ('web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then perform ml_private.need(jsonb_array_length(s#>'{classic,caveEnds}')=4 and not exists(select 1 from ml_private.arr(s#>'{classic,caveEnds}') n where jsonb_typeof(n)<>'number' or (n#>>'{}')::numeric<>trunc((n#>>'{}')::numeric) or (n#>>'{}')::int not between 0 and 2),'山洞计数无效');end if;
 perform ml_private.need((s#>>'{clock,remaining}')::double precision>=0,'计时预算无效');
end $$;
create or replace function ml_private.dispatch_before_stage3(previous jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare s jsonb:=previous; a integer; p jsonb; d jsonb; c jsonb; m jsonb; v jsonb; typ text:=cmd->>'type'; card text:=cmd->>'card'; cells jsonb; cell text; cost integer; left_steps integer; deadline double precision; guard integer:=0; changed boolean:=false; targets jsonb; txt text; begin
 perform ml_private.need(jsonb_typeof(cmd)='object','命令必须为对象');
 perform ml_private.need(jsonb_typeof(cmd->'actor')='number' and (cmd->>'actor')::numeric=trunc((cmd->>'actor')::numeric) and (cmd->>'actor')::int between 0 and 3 and jsonb_typeof(cmd->'revision')='number' and (cmd->>'revision')::numeric=trunc((cmd->>'revision')::numeric) and (cmd->>'revision')::bigint>=0,'座位/命令版本必须为有效整数');
 perform ml_private.need(typ in ('play','move','step','stop','end','choose','tick','location'),'未知命令');
 if typ='play' then perform ml_private.need(jsonb_typeof(cmd->'card')='string' and jsonb_typeof(cmd->'targets')='array','出牌/目标输入无效'); for v in select * from ml_private.arr(cmd->'targets') loop perform ml_private.need(jsonb_typeof(v)='number' and (v#>>'{}')::numeric=trunc((v#>>'{}')::numeric) and ml_private.n(v) between 0 and 3,'目标输入无效'); end loop; end if;
 if typ='location' then perform ml_private.need(cmd->>'kind' in ('ship','commute') and jsonb_typeof(cmd->'cell')='string','地点动作输入无效');end if;
 if typ='step' then perform ml_private.need(jsonb_typeof(cmd->'path')='array','路径必须为数组'); for v in select * from ml_private.arr(cmd->'path') loop perform ml_private.need(jsonb_typeof(v)='string','路径格无效'); end loop; end if;
 if typ='choose' then
  perform ml_private.need(jsonb_typeof(cmd->'choice')='number' and (cmd->>'choice')::numeric=trunc((cmd->>'choice')::numeric) and (cmd->>'choice')::bigint>0,'选择编号无效');
  if cmd ? 'accept' then perform ml_private.need(jsonb_typeof(cmd->'accept')='boolean','发动选项必须为布尔值'); end if;
  if cmd ? 'card' then perform ml_private.need(jsonb_typeof(cmd->'card') in ('string','null'),'响应牌输入无效'); end if;
  if cmd ? 'cell' then perform ml_private.need(jsonb_typeof(cmd->'cell') in ('string','null'),'传送格输入无效'); end if;
  if cmd ? 'cards' then perform ml_private.need(jsonb_typeof(cmd->'cards')='array','弃牌必须为数组'); for v in select * from ml_private.arr(cmd->'cards') loop perform ml_private.need(jsonb_typeof(v)='string','弃牌输入无效'); end loop; end if;
 end if;
 perform ml_private.need(at>=(s->>'time')::double precision,'时钟必须单调'); perform ml_private.need(cmd->'revision'=s->'revision','命令版本过期'); perform ml_private.need(jsonb_typeof(cmd->'id')='string' and length(cmd->>'id')>0 and not (s->'seen' ? (cmd->>'id')),'重复命令'); perform ml_private.need(s->>'phase'<>'over','对局已经结束');
 a:=(cmd->>'actor')::int;
 if typ='tick' then
  while s->>'phase'<>'over' loop deadline:=coalesce((s#>>'{choice,deadline}')::double precision,(s#>>'{clock,since}')::double precision+(s#>>'{clock,remaining}')::double precision); exit when deadline is null or deadline>at;
   exit when s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and guard>=999;guard:=guard+1; perform ml_private.need(guard<1000,'超时流程未收敛'); s:=ml_private.expire(s,deadline); changed:=true;
  end loop;
  if not changed then return jsonb_build_object('state',previous,'ok',true); end if;
 else
  perform ml_private.need(not (case when s->'choice'<>'null'::jsonb then at>=(s#>>'{choice,deadline}')::double precision else s#>'{clock,since}'<>'null'::jsonb and ml_private.budget(s,at)=0 end),'命令已超时');
  if typ='choose' then perform ml_private.need(s->'choice'<>'null'::jsonb,'当前没有选择窗口'); s:=ml_private.choose(s,cmd,at);
  else
   p:=s->'players'->a; perform ml_private.need(a=(s->>'active')::int and (p->>'hp')::int>0,'只有当前存活行动者可操作'); perform ml_private.need(s->'choice'='null'::jsonb,'请先完成当前选择');
   case typ
    when 'step' then if s->>'version' in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then perform ml_private.need(s->>'phase'='moving' and s->'movement'<>'null'::jsonb and jsonb_array_length(cmd->'path')>0,'尚未开始移动或路径为空');s:=ml_private.classic_walk(s,cmd->'path',at);else
     perform ml_private.need(s->>'phase'='moving' and s->'movement'<>'null'::jsonb,'尚未开始移动'); perform ml_private.need(jsonb_array_length(cmd->'path')>0,'移动路径不能为空'); m:=s->'movement';
     for cell in select x#>>'{}' from ml_private.arr(cmd->'path') x loop
      perform ml_private.need(ml_private.game_data(s,'map') ? cell and ml_private.distance_for_version(s->>'version',p->>'cell',cell)=1,'只能正交移动到棋盘内相邻格'); cost:=case when ml_private.game_data(s,'map')->cell->>'terrain'='water' then 2 else 1 end; left_steps:=(m->>'remaining')::int-cost;
      perform ml_private.need(left_steps>=0,'移动步数不足'); perform ml_private.need(ml_private.escape(s,a,cell,left_steps),'此路径会困在占用格');
      p:=p||jsonb_build_object('cell',cell); m:=m||jsonb_build_object('remaining',left_steps,'path',(m->'path')||to_jsonb(cell)); if not ml_private.occupied(s,cell,a) then m:=m||jsonb_build_object('lastEmpty',cell); end if;
      s:=ml_private.put_player(s,a,p); if ml_private.stage4_location_stops(s,a,cell) then left_steps:=0; m:=jsonb_set(m,'{remaining}','0'); end if;
      s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell||'，消耗'||cost||'步，余'||left_steps);
     end loop;
     s:=jsonb_set(s,'{movement}',m); if (m->>'remaining')::int=0 then s:=ml_private.settle_movement(s); s:=s||jsonb_build_object('movement',null,'phase','action'); end if;
    end if;
    when 'stop' then perform ml_private.need(s->'movement'<>'null'::jsonb,'尚未开始移动'); perform ml_private.need(not ml_private.occupied(s,p->>'cell',a),'不能停在占用格'); s:=ml_private.settle_movement(s); s:=s||jsonb_build_object('movement',null,'phase','action'); s:=ml_private.emit(s,'move','主动结束移动，未用额度作废');
    when 'end' then perform ml_private.need(s->'movement'='null'::jsonb or not ml_private.occupied(s,p->>'cell',a),'不能在占用格结束行动'); s:=ml_private.end_turn(s,at);
    else
     perform ml_private.need(s->>'phase'='action','请先完成移动');
     if typ='location' then
      v:=s||jsonb_build_object('shipUsed',coalesce(s#>'{classic,shipUsed}','[]'),'farmClosed',coalesce(s#>'{classic,farmClosed}','false'));cell:=cmd->>'cell';
      perform ml_private.need(ml_private.location_destinations(v,a,cmd->>'kind') ? cell,'地点传送当前不可用或落点不合法');
      if cmd->>'kind'='ship' then s:=jsonb_set(s,'{classic,shipUsed}',(s#>'{classic,shipUsed}')||to_jsonb(a));else s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',0));end if;
      s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('cell',cell));s:=ml_private.classic_relocated(s,a,p->>'cell',cell);
      s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' '||case when cmd->>'kind'='ship' then '飞船' else '通校' end||'至'||cell);
      if ml_private.classic_owes_water(s,a,p->>'cell') then s:=jsonb_set(s,'{queue}',(s->'queue')||jsonb_build_array(jsonb_build_object('kind','action')));s:=ml_private.select_choice(s,'water-discard',a,at,jsonb_build_object('count',1,'cards',p->'hand'));end if;
     elsif typ='move' then perform ml_private.need(not (p->>'moved')::boolean,'本个人回合已使用基础移动'); perform ml_private.need((p->>'ap')::int>=ml_private.stage4_location_move_cost(s,a),'移动需要1AP'); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',(p->>'ap')::int-case when s->>'version'='web-v0.1.1' then 1 else 0 end,'moved',true)); s:=ml_private.die(s,'基础移动'); left_steps:=ceil((s->>'_roll')::numeric/2)::int; s:=s-'_roll'; s:=s||jsonb_build_object('movement',jsonb_build_object('remaining',left_steps,'lastEmpty',p->'cell','origin',p->'cell','path',jsonb_build_array(p->'cell'))||case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then jsonb_build_object('costDue',ml_private.stage4_location_move_cost(s,a)>0) else '{}'::jsonb end,'phase','moving'); s:=ml_private.emit(s,'cost',ml_private.name(s,a)||case when ml_private.stage4_location_move_cost(s,a)=0 then ' 操场免费移动，获得' when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then ' 移动结束扣费，获得' else ' 移动支付1AP，获得' end||left_steps||'步');
     elsif typ='play' then
      d:=ml_private.rule_card(s,card); perform ml_private.need(ml_private.location_card_allowed(s->>'version',p->>'cell',card),'当前位置禁止使用此牌'); targets:=cmd->'targets'; perform ml_private.need(p->'hand' ? card,'手中没有该实体牌'); perform ml_private.need(d is not null and d->>'type'<>'response','响应牌只能在对应窗口使用'); cost:=(d->>'cost')::int; perform ml_private.need((p->>'ap')::int>=cost,'行动点不足');
      if d->>'type'='attack' then perform ml_private.need(s->>'version' in ('web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') or (p->>'attacks')::int<2,'本回合最多两张攻击'); perform ml_private.need(jsonb_array_length(targets) between 1 and case when coalesce((d->>'group')::boolean,false) then case when s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then 3 else 2 end else 1 end and (select count(distinct x) from ml_private.arr(targets) x)=jsonb_array_length(targets),'目标数量无效'); perform ml_private.need(ml_private.targets(s,a,card) @> targets,'目标不合法：检查范围、队伍、lemon嘲讽或群体免疫');
      else perform ml_private.need(targets='[]'::jsonb,'补给只能对自己'); end if;
      if s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=jsonb_set(s,'{clock}',jsonb_build_object('remaining',60000,'since',at)); end if;
      p:=p||jsonb_build_object('ap',(p->>'ap')::int-cost,'hand',(p->'hand')-card); s:=ml_private.put_player(s,a,p); s:=jsonb_set(s,'{resolving}',(s->'resolving')||to_jsonb(card)); txt:=ml_private.name(s,a)||' 使用'||(d->>'name')||'，支付'||cost||'AP'; if d->>'type'='attack' then txt:=txt||'，目标'||(select string_agg(ml_private.name(s,ml_private.n(x)::int),'、') from ml_private.arr(targets) x); end if; s:=ml_private.emit(s,'play',txt,jsonb_build_object('actor',a,'card',card,'targets',targets));
      if d->>'type'='attack' then
       s:=ml_private.put_player(s,a,p||jsonb_build_object('attacks',(p->>'attacks')::int+1));
       select coalesce(jsonb_agg(jsonb_build_object('kind','response','actor',x)),'[]') into cells from ml_private.arr(s->'order') x where targets @> jsonb_build_array(x);
       s:=s||jsonb_build_object('attack',jsonb_build_object('actor',a,'card',card,'targets',targets,'cancelled',(select coalesce(jsonb_agg(x),'[]') from ml_private.arr(targets) x where not ml_private.location_effect_allowed(s->>'version',s->'players'->(x#>>'{}')::int->>'cell',card)),'elbows','[]'::jsonb),'phase','resolving','queue',(s->'queue')||cells||jsonb_build_array(jsonb_build_object('kind','resolve'))); s:=ml_private.pump(s,at);
      else s:=ml_private.heal(s,a,case when d->>'id'='basic-046' then 2 else 1 end,true);
       if d->>'id'='basic-045' then p:=s->'players'->a; cost:=least(1,2-(p->>'shield')::int); p:=p||jsonb_build_object('shield',(p->>'shield')::int+cost); s:=ml_private.put_player(s,a,p); s:=ml_private.emit(s,'shield',ml_private.name(s,a)||' 获得'||cost||'护盾 → '||(p->>'shield')); end if;
       if d->>'id'='basic-047' then s:=ml_private.draw(s,a,2); end if; s:=s||jsonb_build_object('discard',(s->'discard')||(s->'resolving'),'resolving','[]'::jsonb); s:=ml_private.finish(s,false,at);
      end if;
     else raise exception '未知命令'; end if;
   end case;
  end if;
 end if;
 s:=s||jsonb_build_object('seen',(s->'seen')||to_jsonb(cmd->>'id'),'revision',(s->>'revision')::bigint+1,'time',at); perform ml_private.validate(s); return jsonb_build_object('state',s,'ok',true);
exception when others then return jsonb_build_object('state',previous,'ok',false,'error',sqlerrm);
end $$;
create or replace function ml_private.legal_steps_before_stage3(s jsonb) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.legal_steps_legacy(s);end if;
 if s->>'phase'<>'moving' or s->'movement'='null'::jsonb then return '[]';end if;
 return (select coalesce(jsonb_agg(c->'id'),'[]') from ml_private.arr(ml_private.game_data(s,'cells')) c where ml_private.classic_step_cost(s,(s->>'active')::int,c->>'id')<=(s#>>'{movement,remaining}')::int and ml_private.escape(s,(s->>'active')::int,c->>'id',(s#>>'{movement,remaining}')::int-ml_private.classic_step_cost(s,(s->>'active')::int,c->>'id')));
end $$;
create or replace function ml_private.settle_movement_before_stage3(s jsonb) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare a integer:=(s->>'active')::int; m jsonb:=s->'movement'; p jsonb; begin
 if s->>'version' in ('web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') and coalesce((m->>'costDue')::boolean,false) then
  if jsonb_array_length(m->'path')>1 then p:=s->'players'->a; perform ml_private.need((s->>'version' in ('web-v0.1.7','web-v0.1.8') or (p->>'ap')::int>=1),'移动结算需要1AP'); s:=ml_private.put_player(s,a,p||jsonb_build_object('ap',greatest(0,(p->>'ap')::int-1))); s:=ml_private.emit(s,'cost',ml_private.name(s,a)||' 移动结束支付'||least(1,(p->>'ap')::int)||'AP'); end if;
  s:=jsonb_set(s,'{movement,costDue}','false');
 end if; return s;
end $$;
create or replace function ml_private.next_turn_before_stage3(s jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare cursor integer; a integer; begin
 if s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.next_turn_legacy(s,at);end if;
 s:=ml_private.pause(s,at);a:=(s->>'active')::int;s:=ml_private.put_player(s,a,(s->'players'->a)||jsonb_build_object('moved',false,'attacks',0));cursor:=(s->>'cursor')::int+1;
 while cursor<4 and (s->'players'->(s->'order'->>cursor)::int->>'hp')::int<=0 loop cursor:=cursor+1;end loop;s:=jsonb_set(s,'{cursor}',to_jsonb(cursor));
 if cursor<4 then return jsonb_set(s,'{queue}',jsonb_build_array(jsonb_build_object('kind','turn-start','actor',s->'order'->cursor))||(s->'queue'));end if;
 s:=jsonb_set(s,'{phase}','"resolving"');s:=ml_private.classic_environment(s);s:=ml_private.emit(s,'environment','第'||(s->>'round')||'轮末，轰炸：'||(select string_agg(x#>>'{}','、') from ml_private.arr(s#>'{classic,bombs}') x));s:=ml_private.damage(s,s->'_hits',true);s:=s-'_hits';
 s:=jsonb_set(s,'{queue}',(s->'queue')||(s->'_triggers')||jsonb_build_array(jsonb_build_object('kind','round-next')));return s-'_triggers';
end $$;
create or replace function ml_private.stage3_damage(s jsonb,hits jsonb,environment boolean default false,skip_pursuit boolean default false)
returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then
  select coalesce(jsonb_agg(case when (not environment and s#>>array['players',h->>'target','character']='character-037') or ml_private.stage3_equipped(s,(h->>'target')::int,'basic-059') then h||jsonb_build_object('amount',least(1,(h->>'amount')::int)) else h end order by ord),'[]') into hits
  from jsonb_array_elements(hits) with ordinality q(h,ord) where ml_private.stage4_on_board(s,(h->>'target')::int);
 end if;return ml_private.stage3_damage_before_stage4(s,hits,environment,skip_pursuit);
end $$;
create or replace function ml_private.stage3_skill(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ begin
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') and cmd->>'kind' in ('watch','flight','gift','terrain') then s:=ml_private.stage4_equipment_skill(s,cmd,at);return s-'_equipmentSkill';end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') and cmd->>'kind'='quote-cost' then return ml_private.stage4_quote(s,(cmd->>'actor')::int,cmd->>'card');end if;
 return ml_private.stage3_skill_before_stage4(s,cmd,at);
end $$;
create or replace function ml_private.stage3_available_targets(s jsonb,pending jsonb) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$ select coalesce(jsonb_agg(t order by ord),'[]') from jsonb_array_elements(pending->'targets') with ordinality x(t,ord) where ml_private.stage3_alive(s,(t#>>'{}')::int) and not (pending->'cancelled' @> jsonb_build_array(t)) and ml_private.stage3_card_allowed(s,(t#>>'{}')::int,pending->>'definition',pending->'effect') and (case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then not(coalesce(pending#>'{stage4,officeExempt}','[]') @> jsonb_build_array(t)) else ml_private.location_effect_allowed('web-v0.1.5',s#>>array['players',t#>>'{}','cell'],pending->>'definition') end) $$;
create or replace function ml_private.stage3_handle_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s#>'{cardStack,stack,-1}';definition text:=c->>'definition';d jsonb;targets jsonb;exercise boolean;target integer;paid integer;power integer;amount integer;hits jsonb:='[]';after_tasks jsonb:='[]';begin
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=ml_private.stage4_movement_task(s,t,at);if s->>'_movementHandled'='true' then return s-'_movementHandled';end if;s:=s-'_movementHandled';s:=ml_private.stage4_combat_task(s,t,at);if s->>'_combatHandled'='true' then return s-'_combatHandled';end if;s:=s-'_combatHandled';s:=ml_private.stage4_equipment_task(s,t,at);if s->>'_gearHandled'='true' then return s-'_gearHandled';end if;s:=s-'_gearHandled';s:=ml_private.stage4_counter_task(s,t,at);if s->>'_stage4Handled'='true' then return s-'_stage4Handled';end if;s:=s-'_stage4Handled';s:=ml_private.stage4_interrupt_task(s,t,at);if s->>'_interruptHandled'='true' then return s-'_interruptHandled';end if;s:=s-'_interruptHandled';s:=ml_private.stage4_map_task(s,t,at);if s->>'_boardHandled'='true' then return s-'_boardHandled';end if;s:=s-'_boardHandled';end if;
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8') or t->>'action'<>'effect' then return ml_private.stage3_handle_task_before_stage4(s,t,at);end if;
 exercise:=definition in ('basic-003','basic-004','basic-005') and exists(select 1 from ml_private.arr(c->'targets') v where s#>>array['stage4','exerciseGuard',v#>>'{}']='true');
 if definition not in ('basic-007','basic-011','basic-012','basic-014','basic-018','basic-019','basic-022','basic-025','basic-029','basic-030','basic-035','basic-036','basic-040','basic-042','basic-043','basic-044','basic-048','basic-013','basic-020','basic-021','basic-023','basic-026','basic-031','basic-032','basic-033','basic-034') and not(definition='basic-009' and c#>>'{stage4,dodge}'='true') and not exercise then return ml_private.stage3_handle_task_before_stage4(s,t,at);end if;
 d:=ml_private.stage4_content()#>array['cards',definition];s:=ml_private.stage3_record_combo(s,(c->>'actor')::int,definition);targets:=ml_private.stage3_available_targets(s,c);
 for target in select (v#>>'{}')::int from ml_private.arr(targets) v loop
  if definition in ('basic-011','basic-012','basic-014') then null;
  elsif definition='basic-007' then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',case when s#>>array['players',target::text,'character']='character-037' then 3 else 2 end,'source',c->'actor','category','attack'));
  elsif definition='basic-009' then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',2,'source',c->'actor','category','attack'));
  elsif exercise then
   if s#>>array['stage4','exerciseGuard',target::text]='true' then s:=jsonb_set(s,array['stage4','exerciseGuard',target::text],'false');s:=ml_private.emit(s,'buff','S'||(target+1)||' 农夫三拳免本次搏击操AP扣减');
   else power:=(ml_private.rule_card(s,c->>'card')->>'power')::int;paid:=least((s#>>array['players',target::text,'ap'])::int,power);s:=jsonb_set(s,array['players',target::text,'ap'],to_jsonb((s#>>array['players',target::text,'ap'])::int-paid));
    if paid<power then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',power-paid,'source',c->'actor','category','attack'));end if;end if;
  elsif definition='basic-018' then s:=jsonb_set(s,array['stage4','downPending',target::text],'true');s:=jsonb_set(s,array['stage3','coffeeRound',target::text],'true');s:=jsonb_set(s,array['stage3','coffeeUntilStart',target::text],to_jsonb((s#>>array['stage3','starts',target::text])::int+1));
  elsif definition='basic-019' then amount:=least(2,(s#>>array['players',target::text,'ap'])::int);s:=jsonb_set(s,array['players',target::text,'ap'],to_jsonb((s#>>array['players',target::text,'ap'])::int-amount));s:=ml_private.stage3_gain_ap(s,(c->>'actor')::int,amount);s:=ml_private.emit(s-'_gain','ap','借我张纸拿取'||amount||'AP');
  elsif definition='basic-022' then s:=jsonb_set(s,array['stage3','breadPending',target::text],'true');
  elsif definition='basic-025' then s:=ml_private.draw(s,target,coalesce((c#>>'{stage4,x}')::int,0));
  elsif definition in ('basic-029','basic-030','basic-035','basic-036') then s:=ml_private.stage4_change_faction(s,target,case when definition='basic-029' then 'monkey' when definition='basic-030' then 'dimon' else null end);s:=ml_private.emit(s,'faction','S'||(target+1)||' 当前归属：'||(s#>>array['players',target::text,'faction'])||case when s->>'mode'='team' then '／'||(s#>>array['players',target::text,'team'])||'队' else '' end);
  elsif definition='basic-048' then s:=ml_private.die(s,'油泼');amount:=(s->>'_roll')::int;s:=s-'_roll';
   if amount=6 then s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',c->'actor','category','attack')));after_tasks:=after_tasks||(s->'_triggers');s:=s-'_triggers';
   else s:=ml_private.heal(s,target,(s#>>array['players',target::text,'maxHp'])::int-(s#>>array['players',target::text,'hp'])::int,true);end if;
  else s:=ml_private.heal(s,target,case when definition='basic-040' and s#>>array['players',target::text,'character']='character-040' then (s#>>array['players',target::text,'maxHp'])::int-(s#>>array['players',target::text,'hp'])::int else 1 end,true);
   if definition='basic-042' then s:=jsonb_set(s,array['stage4','buffSources',target||':tea'],c->'effect');s:=jsonb_set(s,array['stage4','tea',target::text],'true');end if;
   if definition='basic-043' then s:=jsonb_set(s,array['stage4','buffSources',target||':dodge'],c->'effect');s:=jsonb_set(s,array['stage4','dodge',target::text],'true');end if;
   if definition='basic-044' then s:=jsonb_set(s,array['stage4','buffSources',target||':exerciseFree'],c->'effect');s:=jsonb_set(s,array['stage4','exerciseFree',target::text],'true');s:=jsonb_set(s,array['stage4','exerciseGuard',target::text],'true');end if;
  end if;
 end loop;
 if definition in ('basic-007','basic-009') or exercise then s:=ml_private.damage(s,hits);after_tasks:=after_tasks||(s->'_triggers');s:=s-'_triggers';end if;
 if definition in ('basic-011','basic-012','basic-014') then for target in select (x#>>'{}')::int from ml_private.arr(s->'order') x where targets @> jsonb_build_array(x) loop after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('stage4-deliver',jsonb_build_object('actor',target,'serial',c->'serial')));end loop;end if;
 s:=ml_private.emit(s,'effect',(d->>'name')||'结算');return ml_private.stage3_prepend(s,after_tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))));
end $$;
create or replace function ml_private.stage3_locations(s jsonb,a integer,kind text) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare input jsonb;result jsonb;begin
 if ml_private.stage4_ignore_location(s,a) or ml_private.stage3_mount_blocked(s,a) then return '[]';end if;
 input:=ml_private.stage3_board(s)||jsonb_build_object('shipUsed',s#>'{classic,shipUsed}');if kind='ship' and s#>>array['stage3','jjFree',a::text]='true' then input:=jsonb_set(input,array['players',a::text,'ap'],to_jsonb(greatest(1,(s#>>array['players',a::text,'ap'])::int)));end if;
 select coalesce(jsonb_agg(c order by ord),'[]') into result from jsonb_array_elements(ml_private.location_destinations(input,a,kind)) with ordinality t(c,ord) where ml_private.stage3_can_enter(s,a,c#>>'{}') and (s->>'version'<>'web-v0.1.8' or ml_private.playtest_relocation_cell(s,a,s#>>array['players',a::text,'cell'],c#>>'{}') is not null);return result;
end $$;
create or replace function ml_private.stage3_play(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$
declare a integer:=(cmd->>'actor')::int;p jsonb:=s->'players'->a;card text:=cmd->>'card';definition text:=split_part(card,'#',1);
 d jsonb;tea boolean;free boolean;targets jsonb:=cmd->'targets';cells jsonb;raw integer;quoted jsonb;effect jsonb;exposed jsonb;fee jsonb;pending jsonb;idx text;begin
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8') then return ml_private.stage3_play_before_stage4(s,cmd,at);end if;
 d:=ml_private.stage4_content()#>array['cards',definition];
 perform ml_private.need(d is not null and p->'hand' ? card,'手中没有该实体牌');
 perform ml_private.need(s#>>array['stage3','breadBlocked',a::text]<>'true','本回合不能主动出牌');
 tea:=definition='basic-002' and not(cmd ? 'as') and s#>>array['stage4','tea',a::text]='true';
 if not(cmd ? 'as') and d->>'type'='equipment' then perform ml_private.stage4_validate_equipment(s,cmd);end if;
 if d->>'inherited'='true' and not tea or cmd->>'as'='elbow' then
  free:=not(cmd ? 'as') and definition in ('basic-003','basic-004','basic-005') and s#>>array['stage4','exerciseFree',a::text]='true';
  -- Cost override is an internal flag consumed by the generated frozen delegate.
  if free then s:=s||jsonb_build_object('_stage4Free',true);end if;
  s:=ml_private.stage3_play_before_stage4(s,cmd,at);s:=s-'_stage4Free';
  if free then s:=jsonb_set(s,array['stage4','exerciseFree',a::text],'false');end if;
  if not(cmd ? 'as') and definition='basic-009' and s#>>array['stage4','dodge',a::text]='true' then
   idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx,'stage4'],jsonb_build_object('dodge',true));s:=jsonb_set(s,array['cardStack','stack',idx,'effect','roleModifiers'],(s#>array['cardStack','stack',idx,'effect','roleModifiers'])||coalesce(s#>array['stage4','buffSources',a||':dodge','roleModifiers'],'[]'));s:=jsonb_set(s,array['stage4','dodge',a::text],'false');
  end if;idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx,'stage4'],coalesce(s#>array['cardStack','stack',idx,'stage4'],'{}')||jsonb_build_object('officeExempt',(select coalesce(jsonb_agg(v->'seat' order by ord),'[]') from jsonb_array_elements(s->'players') with ordinality q(v,ord) where not ml_private.stage4_location_effect(s,(v->>'seat')::int,s#>>array['cardStack','stack',idx,'definition']))));return s;
 end if;
 perform ml_private.need(tea or d->>'type'='equipment' or definition in ('basic-024','basic-007','basic-011','basic-012','basic-014','basic-018','basic-019','basic-022','basic-025','basic-029','basic-030','basic-035','basic-036','basic-040','basic-042','basic-043','basic-044','basic-048','basic-013','basic-020','basic-021','basic-023','basic-026','basic-031','basic-032','basic-033','basic-034'),'该牌的阶段四里程碑尚未接通');
 perform ml_private.need(not(cmd ? 'as'),'转换请按牢大肘击流程');
 perform ml_private.need(p->>'character'<>'character-005' or not(d->'tags' ? '建民'),'QB不能使用建民牌');
 perform ml_private.need(ml_private.stage4_location_card(s,a,definition),'当前位置禁止使用此牌');
 perform ml_private.need((select count(distinct x) from ml_private.arr(targets) x)=jsonb_array_length(targets),'目标不能重复');
 if tea then
  perform ml_private.need(jsonb_array_length(targets)=1 and exists(select 1 from ml_private.arr(s->'players') v where v->'seat'=targets->0 and (v->>'seat')::int<>a and ml_private.stage4_on_board(s,(v->>'seat')::int) and not ml_private.stage4_single_protected(s,a,(v->>'seat')::int) and ml_private.game_data(s,'map')#>>array[v->>'cell','region']=ml_private.game_data(s,'map')#>>array[p->>'cell','region']),'冰红茶肘击须指定同地区其他角色');
  cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,(targets->>0)::int);
  perform ml_private.need(jsonb_array_length(cells)=0 or (cmd ? 'direction') and cells ? ml_private.stage3_direction_cell(s#>>array['players',targets->>0,'cell'],cmd->>'direction'),'请先指定合法撞飞方向');
 elsif definition in ('basic-007','basic-018','basic-019','basic-022','basic-029','basic-030','basic-035','basic-036','basic-021','basic-024') then
  perform ml_private.need(jsonb_array_length(targets)=1 and ml_private.stage4_targets(s,a,card) @> targets,'目标不合法');
 else
  perform ml_private.need(targets='[]'::jsonb,'此牌不接受外部目标');
  if definition in ('basic-011','basic-012','basic-014','basic-013','basic-031','basic-026') then select coalesce(jsonb_agg(v->'seat' order by ord),'[]') into targets from jsonb_array_elements(s->'players') with ordinality q(v,ord) where ml_private.stage4_on_board(s,(v->>'seat')::int) and (definition not in ('basic-013','basic-031','basic-026') and (s->>'version'<>'web-v0.1.8' or definition not in ('basic-012','basic-014')) or (v->>'seat')::int<>a) and (definition<>'basic-026' or s->>'mode'='ffa' or v->'team'<>p->'team') and not(v->>'character'='character-027' and jsonb_array_length(v->'hand')=1);elsif definition='basic-040' then select coalesce(jsonb_agg(v->'seat' order by ord),'[]') into targets from jsonb_array_elements(s->'players') with ordinality q(v,ord) where (v->>'hp')::int>0 and v->>'faction'='帝汶家族';else targets:=jsonb_build_array(a);end if;
 end if;
 targets:=ml_private.playtest_north_targets(s,targets,cmd->>'northGroup',not tea and definition not in ('basic-007','basic-018','basic-019','basic-022','basic-029','basic-030','basic-035','basic-036','basic-021','basic-024'));
 if definition='basic-024' then perform ml_private.stage4_validate_steal(s,cmd);end if;
 if definition in ('basic-023','basic-032','basic-033') then perform ml_private.need(jsonb_typeof(cmd->'region')='string' and ml_private.version_catalog(s->>'version')#>'{mapDefinition,regions}' ? (cmd->>'region'),'请选择合法地区');end if;
 if tea then raw:=0;
 elsif d#>>'{cost,kind}'='variable' then
  perform ml_private.need(jsonb_typeof(cmd->'x')='number' and (cmd->>'x')::numeric=trunc((cmd->>'x')::numeric),'X必须为正整数');
  raw:=(ml_private.stage4_cost_quote(s#>'{stage4,costs}',a,card,p->'hand',null,(cmd->>'x')::bigint)#>>'{quote,cost}')::int;
 elsif d#>>'{cost,kind}'='fixed' then raw:=(d#>>'{cost,value}')::int;
 else raw:=(s#>>array['stage4','costs','locks',card,'cost'])::int;end if;
 perform ml_private.need(raw is not null,'请先锁定随机费用');
 if tea or d#>>'{cost,kind}'='variable' then quoted:=jsonb_build_object('cost',raw,'effect',jsonb_build_object('origin','card','actor',a,'faction',p->'faction','roleModifiers',case when tea then coalesce(s#>array['stage4','buffSources',a||':tea','roleModifiers'],'[]')||case when p->>'character'='character-023' then jsonb_build_array(jsonb_build_object('actor',a,'kind','other')) else '[]'::jsonb end else '[]'::jsonb end));
 else quoted:=ml_private.stage3_card_cost(s,a,card,raw);end if;
 fee:=ml_private.stage4_fee_plan((p->>'ap')::int,(quoted->>'cost')::int,false,d#>>'{cost,kind}'='variable');
 exposed:=ml_private.stage3_jj_targets(s,a,card,targets,ml_private.stage4_attack_effect(s,a,card,quoted->'effect'));
 perform ml_private.playtest_north_targets(s,exposed->'targets');
 p:=p||jsonb_build_object('ap',(p->>'ap')::int-(fee->>'spend')::int,'hand',(p->'hand')-card);if d->>'type'='attack' or tea then p:=p||jsonb_build_object('attacks',(p->>'attacks')::int+1);end if;s:=ml_private.put_player(s,a,p);
 if (fee->>'gain')::int>0 then s:=ml_private.stage3_gain_ap(s,a,(fee->>'gain')::int);s:=s-'_gain';end if;
 s:=s||jsonb_build_object('resolving',(s->'resolving')||jsonb_build_array(card),'clock',jsonb_build_object('remaining',60000,'since',at));
 s:=ml_private.stage3_begin_card(s,a,card,definition,exposed->'targets',exposed->'effect',at);idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;pending:=s#>array['cardStack','stack',idx];
 pending:=pending||jsonb_build_object('stage4',jsonb_build_object('officeExempt',(select coalesce(jsonb_agg(v->'seat' order by ord),'[]') from jsonb_array_elements(s->'players') with ordinality q(v,ord) where not ml_private.stage4_location_effect(s,(v->>'seat')::int,definition)))||case when d#>>'{cost,kind}'='variable' then jsonb_build_object('x',raw) else '{}'::jsonb end||case when cmd ? 'region' then jsonb_build_object('region',cmd->'region') else '{}'::jsonb end);
 if cmd ? 'replacement' then pending:=pending||jsonb_build_object('replacement',cmd->'replacement');end if;
 if definition='basic-024' then pending:=jsonb_set(pending,'{stage4}',(pending->'stage4')||jsonb_build_object('take',cmd->'take')||case when cmd ? 'item' then jsonb_build_object('item',cmd->'item') else '{}'::jsonb end);end if;
 if definition='basic-073' then pending:=jsonb_set(pending,'{stage4,copy}',to_jsonb(split_part(cmd->>'copy','#',1)));pending:=jsonb_set(pending,'{effect,roleModifiers}',(pending#>'{effect,roleModifiers}')||(s#>array['stage3','equipmentSources',cmd->>'copy','roleModifiers']));end if;
 if tea then if cmd ? 'direction' then pending:=pending||jsonb_build_object('pushDirection',cmd->'direction');end if;s:=jsonb_set(s,array['stage4','tea',a::text],'false');end if;
 s:=jsonb_set(s,array['cardStack','stack',idx],pending);
 s:=ml_private.emit(s,'play','S'||(a+1)||' 使用'||(d->>'name')||'，支付'||(fee->>'spend')||'AP'||case when (fee->>'gain')::int>0 then '，获得'||(fee->>'gain')||'AP' else '' end,jsonb_build_object('actor',a,'card',card,'targets',exposed->'targets'));
 s:=jsonb_set(s,'{phase}','"resolving"');return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',pending->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',pending->'serial'))));
end $$;
create or replace function ml_private.stage3_relocate(s jsonb,a integer,cell text,voluntary boolean,carry boolean default true) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare origin text:=s#>>array['players',a::text,'cell']; snapshots jsonb; tasks jsonb:='[]';begin
 if s->>'version'='web-v0.1.8' then cell:=ml_private.playtest_relocation_cell(s,a,origin,cell);if cell is null then return s||jsonb_build_object('_relocationTasks',tasks);end if;end if;
 if origin=cell or voluntary and ml_private.stage3_mount_blocked(s,a) then return s||jsonb_build_object('_relocationTasks',tasks);end if;
 snapshots:=case when carry then ml_private.stage3_carry_candidates(s,a,origin) else '[]'::jsonb end;
 s:=ml_private.classic_relocated(s,a,origin,cell);s:=jsonb_set(s,array['players',a::text,'cell'],to_jsonb(cell));if voluntary then s:=jsonb_set(s,array['stage3','voluntaryMoved',a::text],'true');end if;s:=ml_private.emit(s,'move',ml_private.name(s,a)||' → '||cell);
 if ml_private.classic_owes_water(s,a,origin) then tasks:=tasks||jsonb_build_array(jsonb_build_object('kind','water','actor',a,'data',jsonb_build_object('entry',true)));end if;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then tasks:=tasks||ml_private.stage4_arrival_tasks(s,a,origin,cell);if voluntary and coalesce(s->>'_gearReactiveSkip','false')<>'true' then tasks:=tasks||ml_private.stage4_landing_tasks(s,a);end if;end if;
 if jsonb_array_length(snapshots)>0 then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',a,'data',snapshots)));end if;
 return s||jsonb_build_object('_relocationTasks',tasks);
end $$;
create or replace function ml_private.stage3_complete_draft(r ml_private.rooms,at bigint) returns ml_private.rooms language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare setup jsonb;start_at double precision;teams jsonb;begin
 if r.status<>'drafting' or r.draft->>'status'<>'complete' then return r;end if;
 start_at:=(r.draft#>>'{events,-1,at}')::double precision;
 select jsonb_agg(to_jsonb(case when x#>>'{}'='机械猴子' then 'A' else 'B' end) order by ord) into teams from jsonb_array_elements(r.draft->'teams') with ordinality q(x,ord);
 setup:=jsonb_build_object('mode',r.mode,'ruleVersion',case when r.draft->>'catalogVersion' in ('web-v0.1.7','web-v0.1.8') then r.draft->>'catalogVersion' else 'web-v0.1.6' end,'seed',r.draft#>'{random,seed}','seats','[0,1,2,3]'::jsonb,'characters',r.draft->'selected','first',r.draft#>'{order,0}','secure',coalesce(r.draft#>'{random,secure}','false'),'dice',r.draft#>'{random,dice}','bombs',r.draft#>'{random,bombs}','reshuffles',r.draft#>'{random,reshuffles}','sortedReshuffles',r.draft#>'{random,sortedReshuffles}');
 if r.mode='team' then setup:=setup||jsonb_build_object('teams',teams);end if;
 r.game:=ml_private.create_game(setup,start_at);r.status:='playing';r.revision:=r.revision+1;r.updated_at:=at;return r;
end $$;
create or replace function ml_private.stage4_board_effect(s jsonb,a integer,effect jsonb,tag text default null) returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select s->'players'->a is not null and ml_private.character_effect_allowed(effect,a,s#>>array['players',a::text,'character'])
 and not(s->>'version'<>'web-v0.1.8' and s#>>array['players',a::text,'character']='character-006' and (effect->>'actor')::int<>a and effect->>'faction'<>'机械猴子')
 and not(s#>>array['players',a::text,'character']='character-005' and coalesce(tag,'')='建民') $$;
create or replace function ml_private.stage4_board_empty(s jsonb,a integer,cell text,ignored jsonb default '[]') returns boolean language sql stable
set search_path=pg_catalog,ml_private as $$ select (s->>'version'<>'web-v0.1.8' or ml_private.playtest_relocation_cell(s,a,s#>>array['players',a::text,'cell'],cell,ignored) is not null) and ml_private.stage4_board_entry(s,a,cell) and not exists(select 1 from ml_private.arr(s->'players') p where ml_private.stage4_on_board(s,(p->>'seat')::int) and p->>'cell'=cell and not(ignored @> jsonb_build_array(p->'seat'))) $$;
create or replace function ml_private.choose_before_stage4(s jsonb,cmd jsonb,at double precision,timeout boolean default false) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s->'choice';kind text:=c->>'kind';a integer:=(c->>'actor')::int;target integer:=(cmd->>'target')::int;card text:=cmd->>'card';cell text:=cmd->>'cell';pending jsonb;quoted jsonb;result jsonb;cards jsonb;cells jsonb;amount integer;snapshot jsonb;tasks jsonb:='[]';old text;begin
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then return ml_private.choose_before_stage3(s,cmd,at,timeout);end if;perform ml_private.need(cmd->'choice'=c->'id','选择窗口已过期');perform ml_private.need((cmd->>'actor')::int=a,'请交给待选择的座位操作');
 case kind
 when 'easy' then
 amount:=1;if cmd->>'accept'='true' and not timeout and at<(c->>'deadline')::double precision then s:=ml_private.die(s,'easy 太简单了');amount:=(s->>'_roll')::int;s:=s-'_roll';end if;s:=ml_private.stage3_counter_card(s,a,cmd->>'accept'='true' and not timeout,at,amount);result:=s->'_counterResult';s:=s-'_counterResult';s:=ml_private.emit(s,'skill',case when result->>'attempted'='true' then 'S'||(a+1)||' 反制支付1AP，'||case when result->>'cancelled'='true' then '整牌失效' else '判定失败' end else 'S'||(a+1)||' 结束反制' end);if result->>'done'<>'true' then return s;end if;
 when 'response' then if card is not null and card<>'' then perform ml_private.need(c->'cards' ? card,'响应牌不可用');pending:=s#>'{cardStack,stack,-1}';quoted:=ml_private.stage3_card_cost(s,a,card);s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-(quoted->>'cost')::int));s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])-card);s:=jsonb_set(s,'{resolving}',(s->'resolving')||jsonb_build_array(card));s:=ml_private.stage3_begin_card(s,a,card,split_part(card,'#',1),'[]',quoted->'effect',at,(pending->>'serial')::int);pending:=s#>'{cardStack,stack,-1}';s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',pending->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',pending->'serial'))));s:=ml_private.emit(s,'response','S'||(a+1)||' 使用'||(ml_private.rule_card(s,card)->>'name')||'，支付'||(quoted->>'cost')||'AP');end if;
 when 'xiao-overflow' then
 if timeout then select coalesce(jsonb_agg(x order by x),'[]') into cards from (select x from ml_private.arr(s#>array['players',a::text,'hand']) x order by x limit (c->>'count')::int) q;else cards:=coalesce(cmd->'cards','[]');end if;s:=ml_private.stage3_transfer_overflow(s,a,(c->>'source')::int,cards);s:=ml_private.emit(s,'transfer','S'||(a+1)||' 超限'||jsonb_array_length(cards)||'张交给S'||((c->>'source')::int+1));
 when 'qb-pursuit' then if cmd->>'accept'='true' and ml_private.stage3_alive(s,(c->>'source')::int) then s:=ml_private.die(s,'QB 纯菜');target:=case when (s->>'_roll')::int>=3 then (c->>'source')::int else a end;s:=s-'_roll';s:=ml_private.stage3_damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response')),false,true);s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';end if;
 when 'east-start' then if cmd ? 'action' then perform ml_private.need(ml_private.stage3_east_targets(s,a,cmd->>'action') @> jsonb_build_array(target),'领袖风范目标不合法');if cmd->>'action'='draw' then s:=ml_private.draw(s,a,1);s:=ml_private.draw(s,target,1);else cards:=s#>array['players',target::text,'hand'];s:=ml_private.int(s,jsonb_array_length(cards));amount:=(s->>'_int')::int;s:=s-'_int';s:=jsonb_set(s,array['players',a::text,'hand'],(s#>array['players',a::text,'hand'])||jsonb_build_array(cards->amount));s:=jsonb_set(s,array['players',target::text,'hand'],cards-amount);s:=ml_private.emit(s,'transfer','S'||(a+1)||' 从S'||(target+1)||' 随机拿1张');end if;end if;
 when 'xie-ledger' then if target is not null then perform ml_private.need(c->'targets' @> jsonb_build_array(target) and ml_private.stage3_alive(s,target),'阎王薄目标不合法');s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','response')));s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';end if;
 when 'elbow-push' then target:=(c->>'source')::int;cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,target);if timeout then cell:=cells->>0;end if;if cell is null then perform ml_private.need(jsonb_array_length(cells)=0,'请选择一个撞飞方向');else perform ml_private.need(cells ? cell,'撞飞落点已失效');s:=ml_private.stage3_relocate(s,target,cell,false);tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=ml_private.stage3_relocate(s,a,c#>>'{data,origin}',true);tasks:=tasks||(s->'_relocationTasks');s:=ml_private.stage3_prepend(s-'_relocationTasks',tasks);end if;
 when 'west-carry' then if target is not null then select x into snapshot from ml_private.arr(c->'data') x where (x->>'actor')::int=target;perform ml_private.need(snapshot is not null and cell is not null and ml_private.stage3_carry_destinations(ml_private.stage3_board(s),a,target,snapshot->>'origin') ? cell,'同行对象或落点不合法');s:=ml_private.stage3_relocate(s,target,cell,false,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;
 when 'equipment-loss' then old:=split_part(c#>>'{data,card}','#',1);if old='basic-054' and cmd->>'accept'='true' then s:=ml_private.heal(s,a,2);elsif old='basic-063' and cell is not null then perform ml_private.need(c->'cells' ? cell,'山洞落点不合法');s:=ml_private.stage3_relocate(s,a,cell,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;
 when 'revival-confirm' then if cmd->>'accept'='true' then s:=ml_private.stage3_play(s,jsonb_build_object('type','play','id',cmd->'id','revision',cmd->'revision','actor',a,'card',c#>'{data,card}','targets',jsonb_build_array(c->'source')),at);end if;
 when 'teleport' then if cell is not null then perform ml_private.need(c->'cells' ? cell and ml_private.teleport_cells(s,a) ? cell,'传送须为距离≤3的空陆地');s:=ml_private.stage3_relocate(s,a,cell,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';s:=jsonb_set(s,array['players',a::text,'skillUsed'],'true');s:=ml_private.emit(s,'teleport',ml_private.name(s,a)||' 传送至'||cell||case when s->'safe' ? cell then '' else '（毒圈外）' end);end if;
 when 'lemon-support' then if cmd->>'accept'='true' then perform ml_private.need((s#>>array['players',a::text,'ap'])::int>=1 and s#>>array['players',a::text,'skillUsed']='false','支援不可用');s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-1));s:=jsonb_set(s,array['players',a::text,'skillUsed'],'true');for target in 0..3 loop if ml_private.stage3_alive(s,target) and (target=a or (s->>'mode'='team' and s#>array['players',target::text,'team']=s#>array['players',a::text,'team'])) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then s:=ml_private.draw(s,target,1);end if;end loop;s:=ml_private.emit(s,'skill',ml_private.name(s,a)||' 支援，支付1AP');end if;
 else s:=ml_private.choose_before_stage3(s,cmd,at,timeout);if s->'choice'='null'::jsonb and jsonb_array_length(s->'queue')=0 and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);end if;return s;
 end case;
 if timeout then s:=ml_private.emit(s,'timeout',ml_private.name(s,a)||' 选择超时：'||kind);end if;s:=s||jsonb_build_object('choice',null,'phase','resolving');s:=ml_private.pump(s,at);if s->'choice'='null'::jsonb and jsonb_array_length(s->'queue')=0 and s->>'phase'='resolving' and s->'movement'='null'::jsonb and ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');s:=ml_private.resume(s,at);end if;return s;
end $$;
create or replace function ml_private.public_view_before_stage4(s jsonb,viewer integer) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$ declare v jsonb:=ml_private.public_view_before_stage3(s,viewer);r jsonb:=s->'stage3';safe jsonb;begin
 if s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then return v;end if;select jsonb_object_agg(key,value) into safe from jsonb_each(r) where key in ('turn','equipment','basicUsed','breadBlocked','breadReadyAt','jjFree','jjExposed','horseLocks','combos');
 v:=(v-'cardStack'-'stage3')||jsonb_build_object('stage3',safe);return jsonb_set(v,'{actions,stage3}',ml_private.stage3_actions(s,viewer));
end $$;
create or replace function ml_private.stage3_damage_before_stage4(s jsonb,hits jsonb,environment boolean default false,skip_pursuit boolean default false) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare h jsonb; p jsonb; a integer; src integer; blocked integer; loss integer; injured jsonb:='[]'; triggers jsonb:='[]'; begin
 s:=jsonb_set(s,'{batch}',to_jsonb((s->>'batch')::int+1));
 for h in select * from ml_private.arr(hits) loop
  a:=(h->>'target')::int; p:=s->'players'->a; if (p->>'hp')::int<=0 or (h->>'amount')::int<=0 then continue; end if;
  if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=ml_private.stage4_prepare_hit(s,h,environment);h:=s->'_hit';s:=s-'_hit';if h='null'::jsonb then continue;end if;end if;
 blocked:=case when h->>'trueDamage'='true' then 0 when environment and s->>'version' not in ('web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7','web-v0.1.8') then 0 else least((p->>'shield')::int,(h->>'amount')::int) end; loss:=least((p->>'hp')::int,(h->>'amount')::int-blocked);
  p:=p||jsonb_build_object('shield',(p->>'shield')::int-blocked,'hp',(p->>'hp')::int-loss); s:=ml_private.put_player(s,a,p); src:=(h->>'source')::int;
  if src is not null and ml_private.enemy(s,src,a) then s:=ml_private.put_player(s,src,(s->'players'->src)||jsonb_build_object('damage',(s->'players'->src->>'damage')::int+loss,'kills',(s->'players'->src->>'kills')::int+case when (p->>'hp')::int=0 and loss>0 then 1 else 0 end)); end if;
  s:=ml_private.emit(s,'damage',ml_private.name(s,a)||' '||case when environment then '环境' else '普通' end||'伤害'||(h->>'amount')||'，护盾抵挡'||blocked||'，实际失血'||loss,h||jsonb_build_object('blocked',blocked,'loss',loss,'batch',s->'batch'));
  if loss>0 then injured:=injured||jsonb_build_array(h||jsonb_build_object('loss',loss)); end if;
 end loop;
 for a in 0..3 loop p:=s->'players'->a; if (p->>'hp')::int=0 and p->'eliminated'='null'::jsonb then
  s:=s||jsonb_build_object('discard',(s->'discard')||(p->'hand')); p:=p||jsonb_build_object('eliminated',s->'batch','ap',0,'shield',0,'hand','[]'::jsonb); s:=ml_private.put_player(s,a,p); if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') then s:=ml_private.stage3_death(s,a);end if;s:=ml_private.emit(s,'eliminate',ml_private.name(s,a)||' 淘汰（批次'||(s->>'batch')||'）'); end if; end loop;
 if s->>'version' in ('web-v0.1.7','web-v0.1.8') then s:=ml_private.stage4_after_damage(s,injured,environment);triggers:=s->'_gearTriggers';s:=s-'_gearTriggers';end if;
 for a in select ml_private.n(x)::int from ml_private.arr(s->'order') x loop
  p:=s->'players'->a; select x into h from ml_private.arr(injured) x where (x->>'target')::int=a limit 1;
  if h is null or (p->>'hp')::int<=0 then continue; end if; src:=(h->>'source')::int;
  if p->>'character'='character-004' then
   if src is not null and h->>'category'='attack' and ml_private.enemy(s,src,a) and (s->'players'->src->>'hp')::int>0 and not (p->'rewarded' @> jsonb_build_array(src)) and (s->>'version' not in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') or ml_private.character_effect_allowed(jsonb_build_object('origin','role-locked','actor',a,'roleModifiers','[]'::jsonb),src,s#>>array['players',src::text,'character'])) then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',src,'trigger','lemon-reward','source',a)); end if;
   triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','lemon-support'));
  elsif p->>'character'='character-031' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','runner-roll'));
  elsif p->>'character'='character-037' then triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','trigger','actor',a,'trigger','teleport')); end if;
 end loop;
 if s->>'version' in ('web-v0.1.6','web-v0.1.7','web-v0.1.8') and not skip_pursuit then
 for h in select * from ml_private.arr(injured) loop src:=(h->>'source')::int;a:=(h->>'target')::int;
 if src is null or src=a or (s#>>array['players',src::text,'hp'])::int<=0 or (s#>>array['players',a::text,'hp'])::int<=0 or s#>>array['players',src::text,'character']<>'character-005' or not ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',src,'roleModifiers','[]'::jsonb),a,s#>>array['players',a::text,'character']) then continue;end if;
 if jsonb_array_length(s#>'{cardStack,stack}')>0 then
 if coalesce(s#>'{cardStack,stack,0,pursuits}','[]') @> jsonb_build_array(a) then continue;end if;
 s:=jsonb_set(s,'{cardStack,stack,0,pursuits}',coalesce(s#>'{cardStack,stack,0,pursuits}','[]')||jsonb_build_array(a));end if;
 triggers:=triggers||jsonb_build_array(jsonb_build_object('kind','stage3','action','qb','actor',src,'target',a));end loop;end if;
 return s||jsonb_build_object('_triggers',triggers);
end $$;
create or replace function ml_private.stage3_handle_task_before_stage4(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare action text:=t->>'action';a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);target integer;origin text;targets jsonb;cells jsonb;valid jsonb;pending jsonb;d jsonb;after_tasks jsonb:='[]';cards jsonb;hits jsonb:='[]';roll integer:=0;paid integer;amount integer;before_hp jsonb;xie integer;ledger jsonb:='[]';old text;old_source jsonb;closed jsonb;idx text;gained integer;begin
 if action='east' then targets:=ml_private.stage3_east_targets(s,a,'draw');if jsonb_array_length(targets)>0 then s:=ml_private.select_choice(s,'east-start',a,at,jsonb_build_object('targets',targets));end if;return s;end if;
 if action='elbow-hit' then target:=(t->>'target')::int;if not ml_private.stage3_alive(s,a) or not ml_private.stage3_alive(s,target) then return s;end if;origin:=s#>>array['players',target::text,'cell'];s:=ml_private.damage(s,jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','attack')));s:=ml_private.stage3_prepend(s,(s->'_triggers')||jsonb_build_array(ml_private.stage3_task('elbow-push',jsonb_build_object('actor',a,'target',target,'data',jsonb_strip_nulls(jsonb_build_object('origin',origin,'direction',s#>'{cardStack,stack,-1,pushDirection}'))))));return s-'_triggers';end if;
 if action='qb' then target:=(t->>'target')::int;if ml_private.stage3_alive(s,a) and ml_private.stage3_alive(s,target) and ml_private.character_effect_allowed(jsonb_build_object('origin','role-active','actor',a,'roleModifiers','[]'::jsonb),target,s#>>array['players',target::text,'character']) then s:=ml_private.select_choice(s,'qb-pursuit',a,at,jsonb_build_object('source',target));end if;return s;end if;
 if action='ledger' then select coalesce(jsonb_agg(x order by ord),'[]') into targets from jsonb_array_elements(t->'data') with ordinality q(x,ord) where ml_private.stage3_alive(s,(x#>>'{}')::int);if ml_private.stage3_alive(s,a) and jsonb_array_length(targets)>0 then s:=ml_private.select_choice(s,'xie-ledger',a,at,jsonb_build_object('targets',targets));end if;return s;end if;
 if action='carry' then select coalesce(jsonb_agg(x order by ord),'[]') into valid from jsonb_array_elements(t->'data') with ordinality q(x,ord) where jsonb_array_length(ml_private.stage3_carry_destinations(ml_private.stage3_board(s),a,(x->>'actor')::int,x->>'origin'))>0;if ml_private.stage3_alive(s,a) and jsonb_array_length(valid)>0 then select jsonb_agg(x->'actor' order by ord) into targets from jsonb_array_elements(valid) with ordinality q(x,ord);s:=ml_private.select_choice(s,'west-carry',a,at,jsonb_build_object('targets',targets,'data',valid,'options',(select jsonb_object_agg(x->>'actor',ml_private.stage3_carry_destinations(ml_private.stage3_board(s),a,(x->>'actor')::int,x->>'origin')) from ml_private.arr(valid) x)));end if;return s;end if;
 if action='elbow-push' then target:=(t->>'target')::int;origin:=t#>>'{data,origin}';if not ml_private.stage3_alive(s,a) then return s;end if;if not ml_private.stage3_alive(s,target) then if ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,origin) then s:=ml_private.stage3_relocate(s,a,origin,true);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;end if;cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,target);if jsonb_array_length(cells)>0 and t#>>'{data,direction}' is not null and cells ? ml_private.stage3_direction_cell(s#>>array['players',target::text,'cell'],t#>>'{data,direction}') then origin:=s#>>array['players',target::text,'cell'];s:=ml_private.stage3_relocate(s,target,ml_private.stage3_direction_cell(origin,t#>>'{data,direction}'),false);after_tasks:=s->'_relocationTasks';s:=s-'_relocationTasks';s:=ml_private.stage3_relocate(s,a,origin,true);s:=ml_private.stage3_prepend(s,after_tasks||(s->'_relocationTasks'));return s-'_relocationTasks';end if;if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,'elbow-push',a,at,jsonb_build_object('source',target,'cells',cells,'data',jsonb_build_object('origin',s#>array['players',target::text,'cell'])));end if;return s;end if;
 pending:=s#>'{cardStack,stack,-1}';perform ml_private.need(pending is not null,'没有待结算卡牌');perform ml_private.need(not (t ? 'serial') or t->'serial'=pending->'serial','卡牌结算编号过期');a:=(pending->>'actor')::int;idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;d:=(case when s->>'version' in ('web-v0.1.7','web-v0.1.8') then ml_private.stage3_content()||jsonb_build_object('cards',ml_private.game_data(s,'cards')) else ml_private.stage3_content() end)#>array['cards',pending->>'definition'];
 if action='equip-install' then if ml_private.stage3_alive(s,a) then s:=jsonb_set(s,array['stage3','equipment',a::text],(s#>array['stage3','equipment',a::text])||jsonb_build_array(pending->'card'));s:=jsonb_set(s,array['stage3','equipmentSources',pending->>'card'],pending->'effect');s:=jsonb_set(s,'{resolving}',(s->'resolving')-(pending->>'card'));s:=jsonb_set(s,array['cardStack','stack',idx,'installed'],'true');valid:=to_jsonb(coalesce(ml_private.stage3_equipped(s,a,'basic-066') and s#>array['stage3','previousBasic',a::text]='false'::jsonb,false));s:=jsonb_set(s,array['stage3','doubleMove',a::text],valid);s:=jsonb_set(s,array['players',a::text,'moved'],to_jsonb((s#>>array['stage3','basicUsed',a::text])::int>=case when valid='true'::jsonb then 2 else 1 end));s:=ml_private.emit(s,'equip','S'||(a+1)||' 装备'||(d->>'name'));end if;return s;end if;
 if action='counter' then if pending->'counter'<>'null'::jsonb then s:=ml_private.select_choice(s,'easy',(pending#>>'{counter,actor}')::int,at,jsonb_build_object('deadline',pending#>'{counter,deadline}','data',jsonb_build_object('serial',pending->'serial')));end if;return s;end if;
 if action='continue' then
 if pending->>'countered'='true' or pending->'responseTo'<>'null'::jsonb then return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',pending->'serial'))));end if;
 if d->>'type'='attack' or pending->>'definition'='basic-002' then s:=jsonb_set(s,'{attack}',jsonb_build_object('actor',pending->'actor','card',pending->'card','targets',pending->'targets','cancelled',pending->'cancelled','elbows',pending->'elbows'));targets:=ml_private.stage3_available_targets(s,pending);select coalesce(jsonb_agg(ml_private.stage3_task('response',jsonb_build_object('actor',x,'serial',pending->'serial')) order by ord),'[]') into after_tasks from jsonb_array_elements(s->'order') with ordinality q(x,ord) where targets @> jsonb_build_array(x);end if;return ml_private.stage3_prepend(s,after_tasks||jsonb_build_array(ml_private.stage3_task('effect',jsonb_build_object('serial',pending->'serial'))));end if;
 if action='response' then target:=(t->>'actor')::int;if ml_private.stage3_available_targets(s,pending) @> jsonb_build_array(target) then cards:=ml_private.stage3_responses(s,target,pending);if jsonb_array_length(cards)>0 then s:=ml_private.select_choice(s,'response',target,at,jsonb_build_object('cards',cards,'data',jsonb_build_object('serial',pending->'serial')));end if;end if;return s;end if;
 if action='cleanup' then s:=ml_private.stage3_close_card(s);closed:=s->'_closed';s:=s-'_closed';if closed->>'installed'='true' then s:=jsonb_set(s,'{discard}',(s->'discard')-(closed->>'card'));end if;
 if jsonb_array_length(s#>'{cardStack,stack}')>0 then pending:=s#>'{cardStack,stack,-1}';return jsonb_set(s,'{attack}',jsonb_build_object('actor',pending->'actor','card',pending->'card','targets',pending->'targets','cancelled',pending->'cancelled','elbows',pending->'elbows'));end if;s:=jsonb_set(s,'{attack}','null');s:=ml_private.finish(s,false,at);if s->>'phase'<>'over' then if ml_private.stage3_alive(s,(s->>'active')::int) then s:=jsonb_set(s,'{phase}','"action"');else s:=ml_private.stage3_prepend(s,jsonb_build_array(jsonb_build_object('kind','next')));end if;end if;return s;end if;
 perform ml_private.need(action='effect','未知阶段三结算任务');s:=ml_private.stage3_record_combo(s,a,pending->>'definition');targets:=ml_private.stage3_available_targets(s,pending);
 if pending->>'definition'='basic-002' then select coalesce(jsonb_agg(ml_private.stage3_task('elbow-hit',jsonb_build_object('actor',a,'target',x)) order by ord),'[]') into after_tasks from jsonb_array_elements(targets) with ordinality q(x,ord);
 elsif d->>'type'='attack' then
 select jsonb_agg(member->'hp' order by ord) into before_hp from jsonb_array_elements(s->'players') with ordinality q(member,ord);select (member->>'seat')::int into xie from ml_private.arr(s->'players') member where (member->>'hp')::int>0 and member->>'character'='character-044' limit 1;if xie is not null and pending->>'definition'='basic-010' then ledger:=ml_private.stage3_ledger_candidates(s,xie,a,targets);end if;
 if jsonb_array_length(targets)>0 and pending->>'definition' in ('basic-006','basic-009') then s:=ml_private.die(s,d->>'name');roll:=(s->>'_roll')::int;s:=s-'_roll';end if;
 for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop
 if d ? 'power' then paid:=least((s#>>array['players',target::text,'ap'])::int,(d->>'power')::int);s:=jsonb_set(s,array['players',target::text,'ap'],to_jsonb((s#>>array['players',target::text,'ap'])::int-paid));s:=ml_private.emit(s,'ap','S'||(target+1)||' 被扣'||paid||'AP → '||(s#>>array['players',target::text,'ap']));if paid<(d->>'power')::int then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',(d->>'power')::int-paid,'source',a,'category','attack'));end if;
 elsif pending->>'definition'='basic-008' then amount:=(s#>>array['players',target::text,'ap'])::int;if amount=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','attack'));else s:=jsonb_set(s,array['players',target::text,'ap'],'0');s:=ml_private.stage3_gain_ap(s,a,amount);s:=ml_private.emit(s,'ap','S'||(a+1)||' 头锤吸收全部'||amount||'AP，晓虫收取'||(s#>>'{_gain,taken}')||'AP');s:=s-'_gain';end if;
 else
 if pending->>'definition'='basic-010' then s:=ml_private.die(s,'S'||(target+1)||' 猴子游戏');valid:=to_jsonb((s->>'_roll')::int%2=1);s:=s-'_roll';else valid:=to_jsonb(roll>=4);end if;if valid='true'::jsonb then hits:=hits||jsonb_build_array(jsonb_build_object('target',target,'amount',1,'source',a,'category','attack'));end if;end if;end loop;
 for target in select (x#>>'{}')::int from ml_private.arr(pending->'elbows') x loop if not ml_private.stage3_alive(s,target) then continue;end if;amount:=(s#>>array['players',a::text,'ap'])::int;if amount=0 then hits:=hits||jsonb_build_array(jsonb_build_object('target',a,'amount',1,'source',target,'category','response'));else amount:=least(2,amount);s:=jsonb_set(s,array['players',a::text,'ap'],to_jsonb((s#>>array['players',a::text,'ap'])::int-amount));s:=ml_private.stage3_gain_ap(s,target,amount);s:=s-'_gain';end if;end loop;
 s:=ml_private.damage(s,hits);after_tasks:=s->'_triggers';s:=s-'_triggers';if pending->>'definition'='basic-006' and ml_private.stage3_alive(s,a) then select coalesce(sum((before_hp->>(x#>>'{}')::int)::int-(s#>>array['players',x#>>'{}','hp'])::int),0)::int into amount from ml_private.arr(targets) x;s:=ml_private.heal(s,a,amount);end if;
 if jsonb_array_length(ledger)>0 and xie is not null then after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('ledger',jsonb_build_object('actor',xie,'data',ledger)));end if;
 elsif d->>'type'='food' then for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop s:=ml_private.heal(s,target,case when pending->>'definition'='basic-046' then 2 else 1 end,true);if pending->>'definition'='basic-045' then s:=jsonb_set(s,array['players',target::text,'shield'],to_jsonb(least(2,(s#>>array['players',target::text,'shield'])::int+1)));end if;if pending->>'definition'='basic-047' then s:=ml_private.draw(s,target,2);end if;end loop;
 elsif pending->>'definition'='basic-015' then for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop s:=ml_private.stage3_coffee(s,target);s:=ml_private.emit(s,'ap','S'||(target+1)||' 咖啡获得'||(s#>>'{_gain,gained}')||'AP，晓虫收取'||(s#>>'{_gain,taken}')||'AP');s:=s-'_gain';end loop;
 elsif pending->>'definition'='basic-016' then for target in select (x#>>'{}')::int from ml_private.arr(targets) x loop if not ml_private.stage3_card_allowed(s,a,pending->>'definition',pending->'effect') or not ml_private.stage3_can_enter(s,a,s#>>array['players',target::text,'cell']) or not ml_private.stage3_can_enter(s,target,s#>>array['players',a::text,'cell']) then continue;end if;origin:=s#>>array['players',a::text,'cell'];old:=s#>>array['players',target::text,'cell'];if s->>'version'='web-v0.1.8' then cells:=jsonb_build_array(ml_private.playtest_relocation_cell(s,a,origin,old,jsonb_build_array(target)),ml_private.playtest_relocation_cell(s,target,old,origin,jsonb_build_array(a)));if cells->0='null'::jsonb or cells->1='null'::jsonb or cells->0=cells->1 then continue;end if;old:=cells->>0;origin:=cells->>1;s:=jsonb_set(s,array['stage4','offMap',target::text],'true');end if;s:=ml_private.stage3_relocate(s,a,old,true);after_tasks:=after_tasks||(s->'_relocationTasks');s:=s-'_relocationTasks';if s->>'version'='web-v0.1.8' then s:=jsonb_set(s,array['stage4','offMap',target::text],'false');end if;s:=ml_private.stage3_relocate(s,target,origin,false);after_tasks:=after_tasks||(s->'_relocationTasks');s:=s-'_relocationTasks';end loop;
 elsif pending->>'definition'='basic-037' then for target in select (x#>>'{}')::int from ml_private.arr(pending->'targets') x loop if not ml_private.stage3_card_allowed(s,target,pending->>'definition',pending->'effect') then continue;end if;cells:=ml_private.stage3_revival_cells(s,target,(s#>>'{classic,farmClosed}')::boolean);if jsonb_array_length(cells)=0 then continue;end if;s:=ml_private.int(s,jsonb_array_length(cells));old:=cells->>(s->>'_int')::int;s:=s-'_int';s:=ml_private.stage3_revive(s,target,old,(s#>>'{classic,farmClosed}')::boolean);if s->>'version'='web-v0.1.8' and ml_private.classic_native(s,target) and ml_private.stage4_board_water(s,old,target) then after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('board-shore',jsonb_build_object('actor',target,'data',jsonb_build_object('cells',ml_private.playtest_nearest_shore(s,target)))));end if;s:=jsonb_set(s,array['classic','exposure',target::text],jsonb_build_object('region',null,'streak',0));s:=jsonb_set(s,array['classic','caveEnds',target::text],'0');s:=ml_private.emit(s,'revive','S'||(target+1)||' 紫檀木复活于'||old||'：1HP、0AP、空手');end loop;
 elsif d->>'type'='equipment' then
 if pending ? 'replacement' then old:=pending->>'replacement';old_source:=s#>array['stage3','equipmentSources',old];s:=jsonb_set(s,array['stage3','equipment',a::text],(s#>array['stage3','equipment',a::text])-old);s:=jsonb_set(s,'{stage3,equipmentSources}',(s#>'{stage3,equipmentSources}')-old);s:=jsonb_set(s,'{discard}',(s->'discard')||jsonb_build_array(old));if old_source is not null and ml_private.stage3_card_allowed(s,a,old,old_source||jsonb_build_object('origin','equipment')) then cells:=null;if split_part(old,'#',1)='basic-063' then select coalesce(jsonb_agg(cell->'id' order by ord),'[]') into cells from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(cell,ord) where cell->>'region'='山洞' and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,cell->>'id');end if;if split_part(old,'#',1)='basic-054' or jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,'equipment-loss',a,at,jsonb_build_object('data',jsonb_build_object('card',old))||case when cells is null then '{}'::jsonb else jsonb_build_object('cells',cells) end);end if;end if;end if;after_tasks:=after_tasks||jsonb_build_array(ml_private.stage3_task('equip-install',jsonb_build_object('serial',pending->'serial')));
 end if;return ml_private.stage3_prepend(s,after_tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',pending->'serial'))));
end $$;
create or replace function ml_private.stage3_play_before_stage4(s jsonb,cmd jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare a integer:=(cmd->>'actor')::int;p jsonb:=s->'players'->a;card text:=cmd->>'card';d jsonb:=ml_private.rule_card(s,card);converted boolean:=coalesce(cmd->>'as','')='elbow';elbow boolean;boost boolean;quoted jsonb;effect jsonb;targets jsonb:=cmd->'targets';legal jsonb;cells jsonb;options jsonb;exposed jsonb;pending jsonb;idx text;cost integer;begin
 perform ml_private.need(p->'hand' ? card and d is not null,'手中没有该实体牌');perform ml_private.need(s#>>array['stage3','breadBlocked',a::text]<>'true','面包：本个人回合不能主动出牌');elbow:=p->>'character'='character-023' and (converted or d->>'id'='basic-002');perform ml_private.need(not converted or p->>'character'='character-023','只有牢大可以转换肘击');perform ml_private.need(d->>'type'<>'response' or elbow,'响应牌只能在相应窗口使用');
 perform ml_private.need(p->>'character'<>'character-005' or converted or not (ml_private.version_catalog('web-v0.1.5')#>array['sourceCatalog','cards',d->>'id','tags'] ? '建民'),'QB不能使用建民牌');boost:=p->>'character'='character-045' and d->>'id'='basic-010';perform ml_private.need(boost or converted or ml_private.stage4_location_card(s,a,d->>'id'),'当前位置禁止使用此牌');
 if converted then quoted:=jsonb_build_object('cost',ml_private.stage3_fixed_cost(s,a,2),'effect',jsonb_build_object('origin','role-active','actor',a,'faction',p->'faction','roleModifiers',jsonb_build_array(jsonb_build_object('actor',a,'kind','conversion'))));
 else quoted:=ml_private.stage3_card_cost(s,a,card,case when s#>array['stage3','costLocks',card,'turn']=s#>'{stage3,turn}' then (s#>>array['stage3','costLocks',card,'cost'])::int else null end);end if;if s->>'version' in ('web-v0.1.7','web-v0.1.8') and s->>'_stage4Free'='true' then quoted:=jsonb_build_object('cost',0,'effect',jsonb_build_object('origin','card','actor',a,'faction',p->'faction','roleModifiers',coalesce(s#>array['stage4','buffSources',a||':exerciseFree','roleModifiers'],'[]')));end if;effect:=quoted->'effect';if s->>'version' in ('web-v0.1.7','web-v0.1.8') and coalesce(cmd->>'as','')<>'elbow' then effect:=ml_private.stage4_attack_effect(s,a,card,effect);end if;
 if elbow and not converted then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','other')));end if;if boost then effect:=jsonb_set(effect,'{roleModifiers}',(effect->'roleModifiers')||jsonb_build_array(jsonb_build_object('actor',a,'kind','target')));end if;cost:=(quoted->>'cost')::int;
 perform ml_private.need((p->>'ap')::int>=cost,'需要'||cost||'AP');perform ml_private.need((select count(distinct x) from ml_private.arr(targets) x)=jsonb_array_length(targets),'目标不能重复');
 if elbow then perform ml_private.need(jsonb_array_length(targets)=1 and ml_private.stage3_elbow_targets(s,a,converted) @> targets,'主动肘击目标不合法');
 elsif d->>'type'='attack' then legal:=ml_private.targets(s,a,card);perform ml_private.need(jsonb_array_length(targets) between 1 and case when d->>'group'='true' then 3 else 1 end and legal @> targets,'攻击目标不合法');
 elsif d->>'id'='basic-016' then perform ml_private.need(jsonb_array_length(targets)=1 and (targets->>0)::int<>a and ml_private.stage3_alive(s,(targets->>0)::int) and not ml_private.stage3_mount_blocked(s,a) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),a,s#>>array['players',targets->>0,'cell'],jsonb_build_array(a,targets->0)) and ml_private.stage3_empty_entry(ml_private.stage3_board(s),(targets->>0)::int,p->>'cell',jsonb_build_array(a,targets->0)),'交换目标或坐骑位移限制不合法');
 elsif d->>'id'='basic-037' then perform ml_private.need(jsonb_array_length(targets)=1 and jsonb_array_length(ml_private.stage3_revival_cells(s,(targets->>0)::int,(s#>>'{classic,farmClosed}')::boolean))>0,'当前没有合法复活目标');
 else perform ml_private.need(targets='[]'::jsonb,'此牌不接受外部目标');targets:=case when d->>'id'='basic-041' then ml_private.stage3_assam_targets(s,a) else jsonb_build_array(a) end;end if;
 targets:=ml_private.playtest_north_targets(s,targets,cmd->>'northGroup',d->>'type'<>'attack' and not elbow and d->>'id' not in ('basic-016','basic-037'));
 if not converted and d->>'type'='equipment' then options:=ml_private.stage3_equipment_options(s,a,card);perform ml_private.need(options->>'allowed'='true' and (options->>'required'<>'true' or cmd ? 'replacement') and (not (cmd ? 'replacement') or options->'cards' ? (cmd->>'replacement')),'请先选择合法装备替换对象');perform ml_private.need(d->>'id'<>'basic-063' or ml_private.game_data(s,'map')#>>array[p->>'cell','terrain']<>'water','水中不能装备禁水的哈基米');end if;
 if elbow then cells:=ml_private.stage3_elbow_cells(ml_private.stage3_board(s),a,(targets->>0)::int);perform ml_private.need(jsonb_array_length(cells)=0 or (cmd ? 'direction') and cells ? ml_private.stage3_direction_cell(s#>>array['players',targets->>0,'cell'],cmd->>'direction'),'请先选择合法撞飞方向');end if;exposed:=ml_private.stage3_jj_targets(s,a,case when elbow then 'basic-002' else card end,targets,effect);targets:=ml_private.playtest_north_targets(s,exposed->'targets');effect:=exposed->'effect';p:=p||jsonb_build_object('ap',(p->>'ap')::int-cost,'hand',(p->'hand')-card);if d->>'type'='attack' or elbow then p:=p||jsonb_build_object('attacks',(p->>'attacks')::int+1);end if;s:=ml_private.put_player(s,a,p);s:=s||jsonb_build_object('resolving',(s->'resolving')||jsonb_build_array(card),'clock',jsonb_build_object('remaining',60000,'since',at));
 s:=ml_private.stage3_begin_card(s,a,card,case when elbow then 'basic-002' else d->>'id' end,targets,effect,at);pending:=s#>'{cardStack,stack,-1}';if elbow then pending:=pending||jsonb_build_object('converted',converted);if cmd ? 'direction' then pending:=pending||jsonb_build_object('pushDirection',cmd->'direction');end if;end if;if cmd ? 'replacement' then pending:=pending||jsonb_build_object('replacement',cmd->'replacement');end if;idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx],pending);
 s:=ml_private.emit(s,'play','S'||(a+1)||' 使用'||case when elbow then '肘击' else d->>'name' end||'，支付'||cost||'AP',jsonb_build_object('actor',a,'card',card,'targets',targets));s:=jsonb_set(s,'{phase}','"resolving"');return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('counter',jsonb_build_object('serial',pending->'serial')),ml_private.stage3_task('continue',jsonb_build_object('serial',pending->'serial'))));
end $$;
create or replace function ml_private.stage4_attack_effect(s jsonb,a integer,card text,effect jsonb) returns jsonb language plpgsql stable
set search_path=pg_catalog,ml_private as $$ declare gear text;definition text;mods jsonb:=effect->'roleModifiers';begin
 if s->>'version' not in ('web-v0.1.7','web-v0.1.8') then return effect;end if;
 for gear in select v#>>'{}' from ml_private.arr(s#>array['stage3','equipment',a::text]) v loop definition:=ml_private.stage4_equipment_definition(s,gear);
  if (ml_private.rule_card(s,card)->>'type'='attack' and (definition in ('basic-053','basic-058') or definition='basic-056' and split_part(card,'#',1)='basic-009')) or ml_private.stage4_ignore_location(s,a) and definition='basic-069' then mods:=mods||coalesce(s#>array['stage3','equipmentSources',gear,'roleModifiers'],'[]');end if;
 end loop;return jsonb_set(effect,'{roleModifiers}',mods);
end $$;
create or replace function ml_private.stage4_map_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare c jsonb:=s#>'{cardStack,stack,-1}';action text:=t->>'action';a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);target integer;definition text:=c->>'definition';targets jsonb;tasks jsonb:='[]';cards jsonb;cells jsonb;paths jsonb;options jsonb;desert jsonb;region text;cell text;roll integer;max_distance integer;effect jsonb;idx text;begin
 if action='board-shore' then select coalesce(jsonb_agg(v order by ord),'[]') into cells from jsonb_array_elements(t#>'{data,cells}') with ordinality q(v,ord) where ml_private.stage4_board_empty(s,a,v#>>'{}',jsonb_build_array(a));perform ml_private.need(jsonb_array_length(cells)>0,'上岸预留格失效');return ml_private.select_choice(s,'native-shore',a,at,jsonb_build_object('cells',cells))||jsonb_build_object('_boardHandled',true);end if;
 if action='board-desert' then desert:=ml_private.stage4_desert(s,a);if desert is not null then
  if jsonb_array_length(s#>array['players',a::text,'hand'])>0 or (s#>>array['players',a::text,'ap'])::int>0 then s:=ml_private.select_choice(s,'board-tax',a,at,jsonb_build_object('cards',s#>array['players',a::text,'hand'],'source',desert->'owner','data',jsonb_build_object('mode','desert')));
  else s:=ml_private.stage4_pay(s,a,(desert->>'owner')::int,'desert',null,false);end if;end if;return s||jsonb_build_object('_boardHandled',true);
 elsif action='board-pay' then if ml_private.stage4_on_board(s,a) then
  if jsonb_array_length(s#>array['players',a::text,'hand'])>0 then s:=ml_private.select_choice(s,'board-tax',a,at,jsonb_build_object('cards',s#>array['players',a::text,'hand'],'source',t->'source','data',jsonb_build_object('mode',t#>'{data,mode}')));
  else s:=ml_private.stage4_pay(s,a,(t->>'source')::int,t#>>'{data,mode}',null,false);end if;end if;return s||jsonb_build_object('_boardHandled',true);
 end if;
 if action like 'board-%' then
  if c is null or t ? 'serial' and t->'serial'<>c->'serial' then return s||jsonb_build_object('_boardHandled',true);end if;
  if action='board-force' then
   paths:=ml_private.stage4_forced_paths(s,a,t#>>'{data,region}',(t#>>'{data,steps}')::int);
   if jsonb_array_length(paths)>1 then select jsonb_object_agg((ord-1)::text,v) into options from jsonb_array_elements(paths) with ordinality q(v,ord);s:=ml_private.select_choice(s,'board-path',a,at,jsonb_build_object('options',options,'data',jsonb_build_object('serial',c->'serial')));
   elsif jsonb_array_length(coalesce(paths->0,'[]'))>0 then s:=ml_private.stage4_queue_path(s,a,paths->0,(c->>'serial')::int);end if;
  elsif action='board-step' then
   cell:=t#>>'{data,cell}';
   if not ml_private.stage4_on_board(s,a) or ml_private.distance_for_version(s->>'version',s#>>array['players',a::text,'cell'],cell)<>1 or not ml_private.stage4_board_empty(s,a,cell,jsonb_build_array(a)) then
    s:=jsonb_set(s,'{queue}',(select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(s->'queue') with ordinality q(v,ord) where not(coalesce(v->>'action','')='board-step' and (v->>'actor')::int=a and v->'serial'=c->'serial')));
   else s:=ml_private.stage3_relocate(s,a,cell,false,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';
    if ml_private.game_data(s,'map')#>>array[cell,'region']='山洞' then s:=jsonb_set(s,'{queue}',(select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(s->'queue') with ordinality q(v,ord) where not(coalesce(v->>'action','')='board-step' and (v->>'actor')::int=a and v->'serial'=c->'serial')));end if;
   end if;
  elsif action='board-force-carry' then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('carry',jsonb_build_object('actor',a,'data',t->'data'))));
  elsif action='board-force-after' then
   targets:=ml_private.stage4_map_targets(s,c);
   if definition='basic-013' then
    select max(ml_private.stage4_region_distance(s,(v#>>'{}')::int,'操场')) into max_distance from ml_private.arr(targets) v where v<>c->'actor';
    select coalesce(jsonb_agg(jsonb_build_object('target',v,'amount',1,'source',c->'actor','category','attack','directHp',true)),'[]') into tasks from ml_private.arr(targets) v where v<>c->'actor' and ml_private.stage4_region_distance(s,(v#>>'{}')::int,'操场')=max_distance;
    s:=ml_private.damage(s,tasks);s:=ml_private.stage3_prepend(s,s->'_triggers');s:=s-'_triggers';
   else
    select coalesce(jsonb_agg(ml_private.stage3_task('board-pay',jsonb_build_object('actor',v,'source',c->'actor','data',jsonb_build_object('mode','tribute'))) order by ord),'[]') into tasks
    from jsonb_array_elements(s->'order') with ordinality q(v,ord) where targets @> jsonb_build_array(v) and v<>c->'actor' and s#>array['players',v#>>'{}','team']<>s#>array['players',c->>'actor','team'] and ml_private.game_data(s,'map')#>>array[s#>>array['players',v#>>'{}','cell'],'region']='教学楼';s:=ml_private.stage3_prepend(s,tasks);
   end if;
  elsif action='board-teleport' then
   target:=(t->>'target')::int;if ml_private.stage4_on_board(s,target) and ml_private.stage4_on_board(s,(c->>'actor')::int) then
    select coalesce(jsonb_agg(candidate->'id' order by ord),'[]') into cells from jsonb_array_elements(ml_private.game_data(s,'cells')) with ordinality q(candidate,ord) where ml_private.stage4_board_empty(s,target,candidate->>'id',jsonb_build_array(target));
    if jsonb_array_length(cells)>0 then s:=ml_private.select_choice(s,'board-cell',(c->>'actor')::int,at,jsonb_build_object('cells',cells,'source',target,'data',jsonb_build_object('serial',c->'serial')));end if;end if;
  else raise exception '未知阶段四地图任务';end if;return s||jsonb_build_object('_boardHandled',true);
 end if;
 if action<>'effect' or definition not in ('basic-013','basic-020','basic-021','basic-023','basic-026','basic-031','basic-032','basic-033','basic-034') then return s||jsonb_build_object('_boardHandled',false);end if;
 a:=(c->>'actor')::int;targets:=ml_private.stage4_map_targets(s,c);s:=ml_private.stage3_record_combo(s,a,definition);
 if definition='basic-020' then for target in select (v#>>'{}')::int from ml_private.arr(targets) v loop s:=jsonb_set(s,array['stage4','toiletUntil',target::text],to_jsonb((s#>>array['stage3','starts',target::text])::int+1));s:=jsonb_set(s,array['stage4','toiletEffects',target::text],c->'effect');end loop;end if;
 if definition='basic-026' then
  s:=jsonb_set(s,array['stage4','lmmUntil',a::text],to_jsonb((s#>>array['stage3','starts',a::text])::int+1));s:=jsonb_set(s,array['stage4','lmmEffects',a::text],c->'effect');s:=jsonb_set(s,array['stage4','lmmSerial',a::text],c->'serial');
  select coalesce(jsonb_agg(ml_private.stage3_task('board-pay',jsonb_build_object('actor',v,'source',a,'data',jsonb_build_object('mode','lmm'))) order by ord),'[]') into tasks from jsonb_array_elements(s->'order') with ordinality q(v,ord) where targets @> jsonb_build_array(v);
 end if;
 if definition='basic-034' then for target in select (v#>>'{}')::int from ml_private.arr(targets) v loop
  s:=jsonb_set(s,array['stage4','offMap',target::text],'true');s:=jsonb_set(s,array['classic','exposure',target::text],jsonb_build_object('region',null,'streak',0));s:=jsonb_set(s,array['classic','caveEnds',target::text],'0');s:=ml_private.emit(s,'off-map','S'||(target+1)||' 移出地图，等待下个个人开始返回');end loop;end if;
 if definition='basic-023' then
  select coalesce(jsonb_agg(v order by ord),'[]') into cards from jsonb_array_elements(s#>'{stage4,blocks}') with ordinality q(v,ord) where not((v->>'owner')::int=a and v->'region'=c#>'{stage4,region}');
  cards:=cards||jsonb_build_array(jsonb_build_object('region',c#>'{stage4,region}','owner',a,'effect',c->'effect','until',(s#>>array['stage3','starts',a::text])::int+1,'exempt',coalesce(c#>'{stage4,officeExempt}','[]')));s:=jsonb_set(s,'{stage4,blocks}',cards);
 end if;
 if definition='basic-032' then s:=jsonb_set(s,array['stage4','deserts',c#>>'{stage4,region}'],jsonb_build_object('owner',a,'effect',c->'effect'));end if;
 if definition='basic-033' then
  if s->>'version'='web-v0.1.8' then s:=ml_private.playtest_flood(s,c#>>'{stage4,region}',a,c->'effect');if s->>'_floodFailed'='true' then s:=s-'_floodFailed';return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))))||jsonb_build_object('_boardHandled',true);end if;tasks:=tasks||(s->'_shoreTasks');s:=s-'_shoreTasks';else s:=jsonb_set(s,array['stage4','water',c#>>'{stage4,region}'],jsonb_build_object('owner',a,'effect',c->'effect'));end if;
  for target in select (v#>>'{}')::int from ml_private.arr(s->'order') v loop
   if ml_private.stage4_on_board(s,target) and ml_private.game_data(s,'map')#>>array[s#>>array['players',target::text,'cell'],'region']=c#>>'{stage4,region}' and ml_private.stage4_board_effect(s,target,c->'effect') and not ml_private.classic_native(s,target) and jsonb_array_length(s#>array['players',target::text,'hand'])>0 then tasks:=tasks||jsonb_build_array(jsonb_build_object('kind','water','actor',target,'data',jsonb_build_object('entry',true)));end if;
  end loop;
 end if;
 if definition in ('basic-013','basic-031') then
  region:=case when definition='basic-013' then '操场' else '教学楼' end;
  select coalesce(jsonb_agg(ml_private.stage3_task('board-force',jsonb_build_object('actor',v,'serial',c->'serial','data',jsonb_build_object('region',region,'steps',case when definition='basic-013' then 1 else 3 end))) order by ord),'[]') into tasks from jsonb_array_elements(s->'order') with ordinality q(v,ord) where targets @> jsonb_build_array(v);
  tasks:=tasks||jsonb_build_array(ml_private.stage3_task('board-force-after',jsonb_build_object('serial',c->'serial')));
 end if;
 if definition='basic-021' and jsonb_array_length(targets)>0 then
  if jsonb_array_length(s#>'{random,dice}')>0 then roll:=(s#>>'{random,dice,0}')::int;s:=jsonb_set(s,'{random,dice}',(s#>'{random,dice}')-0);else s:=ml_private.int(s,6);roll:=(s->>'_int')::int+1;s:=s-'_int';end if;
  idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx,'stage4','guessDie'],to_jsonb(roll));s:=ml_private.select_choice(s,'board-guess',(targets->>0)::int,at,jsonb_build_object('source',a,'data',jsonb_build_object('serial',c->'serial')));
 end if;
 s:=ml_private.emit(s,'effect',definition||'地图效果结算');s:=ml_private.stage3_prepend(s,tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))));return s||jsonb_build_object('_boardHandled',true);
end $$;
create or replace function ml_private.stage4_map_choose(s jsonb,cmd jsonb,at double precision,timeout boolean) returns jsonb language plpgsql volatile
set search_path=pg_catalog,ml_private as $$ declare choice jsonb:=s->'choice';a integer:=(choice->>'actor')::int;kind text:=choice->>'kind';option text:=cmd->>'option';mode text:=choice#>>'{data,mode}';card text:=cmd->>'card';ap boolean;pending jsonb;roll integer;cell text:=cmd->>'cell';cells jsonb;origin text;jobs jsonb;begin
 if kind='native-shore' then if timeout then cell:=choice#>>'{cells,0}';end if;perform ml_private.need(cell is not null and choice->'cells' ? cell and ml_private.stage4_board_empty(s,a,cell,jsonb_build_array(a)),'请选择合法岸边');s:=s||jsonb_build_object('_gearReactiveSkip',true);s:=ml_private.stage3_relocate(s,a,cell,false,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');return s-'_relocationTasks'-'_gearReactiveSkip';end if;
 if kind='board-path' then
  if option is null and timeout then select key into option from jsonb_each(choice->'options') order by key::int limit 1;end if;perform ml_private.need(option is not null and choice->'options' ? option,'请选择一条合法路径');return ml_private.stage4_queue_path(s,a,choice->'options'->option,(choice#>>'{data,serial}')::int);
 elsif kind='board-tax' then
  ap:=mode='desert' and (cmd->>'action'='ap' or timeout and (s#>>array['players',a::text,'ap'])::int>0);ap:=coalesce(ap,false);
  if card is null and timeout then select v#>>'{}' into card from ml_private.arr(s#>array['players',a::text,'hand']) v order by v#>>'{}' limit 1;end if;
  if mode='desert' then perform ml_private.need(case when ap then (s#>>array['players',a::text,'ap'])::int>0 else card is not null and choice->'cards' ? card end,'请选择1AP或一张手牌');else perform ml_private.need(card is not null and choice->'cards' ? card,'请选择一张上交牌');end if;
  return ml_private.stage4_pay(s,a,(choice->>'source')::int,mode,card,ap);
 elsif kind='board-guess' then
  pending:=s#>'{cardStack,stack,-1}';roll:=(pending#>>'{stage4,guessDie}')::int;perform ml_private.need(timeout or jsonb_typeof(cmd->'guess')='number' and (cmd->>'guess')::numeric=trunc((cmd->>'guess')::numeric) and (cmd->>'guess')::int between 1 and 6,'请选择1—6');
  s:=ml_private.emit(s,'dice','卫汶找你：d6 = '||roll,to_jsonb(roll));if timeout or (cmd->>'guess')::int<>roll then s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('board-teleport',jsonb_build_object('target',a,'serial',pending->'serial'))));end if;return s;
 elsif kind='board-cell' then
  if cell is not null then perform ml_private.need(choice->'cells' ? cell and ml_private.stage4_board_empty(s,(choice->>'source')::int,cell,jsonb_build_array(choice->'source')),'传送落点不合法');s:=ml_private.stage3_relocate(s,(choice->>'source')::int,cell,false);s:=ml_private.stage3_prepend(s,s->'_relocationTasks');s:=s-'_relocationTasks';end if;return s;
 elsif kind='board-return' then
  select coalesce(jsonb_agg(v order by ord),'[]') into cells from jsonb_array_elements(choice->'cells') with ordinality q(v,ord) where ml_private.stage4_board_empty(s,a,v#>>'{}',jsonb_build_array(a));perform ml_private.need(jsonb_array_length(cells)>0,'当前无合法返回格');
  if timeout then s:=ml_private.int(s,jsonb_array_length(cells));cell:=cells->>(s->>'_int')::int;s:=s-'_int';end if;perform ml_private.need(cell is not null and cells ? cell,'请选择合法返回格');
  s:=jsonb_set(s,array['stage4','offMap',a::text],'false');origin:=s#>>array['players',a::text,'cell'];s:=ml_private.stage3_relocate(s,a,cell,false);jobs:=s->'_relocationTasks';s:=s-'_relocationTasks';
  if origin=cell and ml_private.stage4_board_water(s,cell,a) and not ml_private.classic_native(s,a) and jsonb_array_length(s#>array['players',a::text,'hand'])>0 then jobs:=jsonb_build_array(jsonb_build_object('kind','water','actor',a,'data',jsonb_build_object('entry',true)))||jobs;end if;
  if origin=cell and ml_private.stage4_desert(s,a) is not null then jobs:=jobs||jsonb_build_array(ml_private.stage3_task('board-desert',jsonb_build_object('actor',a)));end if;
  s:=ml_private.stage3_prepend(s,jobs);return ml_private.emit(s,'return','S'||(a+1)||' 返回地图'||cell);
 end if;raise exception '未知阶段四地图选择';
end $$;
create or replace function ml_private.stage4_create_draft(mode text,random_state jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$ declare s jsonb:=jsonb_build_object('random',random_state);firstn integer;pair jsonb;teams jsonb:='[]';pools jsonb:='{}';ids jsonb:=ml_private.stage3_content()->'characterIds';pool jsonb;family text;a integer;begin
 s:=ml_private.int(s,4);firstn:=(s->>'_int')::int;s:=s-'_int';s:=ml_private.shuffle(s,'[0,1,2,3]');pair:=jsonb_build_array(s->'_shuffle'->0,s->'_shuffle'->1);s:=s-'_shuffle';
 for a in 0..3 loop family:=case when mode='team' then case when pair @> jsonb_build_array(a) then '机械猴子' else '帝汶家族' end else 'S'||(a+1) end;teams:=teams||jsonb_build_array(family);end loop;
 for family in select distinct x#>>'{}' from ml_private.arr(teams) x loop
 select jsonb_agg(id order by ord) into pool from jsonb_array_elements(ids) with ordinality q(id,ord) where mode='ffa' or ml_private.stage3_content()#>>array['characters',id#>>'{}','faction'] in (family,'中立');pools:=jsonb_set(pools,array[family],pool);end loop;
 return ml_private.create_draft(jsonb_build_object('mode',mode,'order',(select jsonb_agg((firstn+i)%4 order by i) from generate_series(0,3) i),'teams',teams,'pools',pools,'random',s->'random','catalogVersion','web-v0.1.8'),at);
end $$;
create or replace function public.ml_health() returns jsonb language sql security definer set search_path=pg_catalog as $$
with readiness as (select coalesce((select
 value#>>'{manifest,status}'='playable'
 and jsonb_array_length(value#>'{runtimeData,allCards}')=191
 and (select count(*)=76 from jsonb_object_keys(value#>'{runtimeData,cards}'))
 and jsonb_array_length(value#>'{runtimeData,characterIds}')=16
 and value#>>'{characterTraits,character-004,faction}'='帝汶家族'
 and value#>>'{characterTraits,character-004,spawnRegion}'='操场'
 and value#>>'{environment,kind}'='classic-regions-v2'
 and value#>>'{environment,poisonRegionCount}'='11'
 and value#>'{environment,protectedRegions}'='["教学楼","操场","办公室"]'::jsonb
 and value#>>'{environment,caveEveryPersonalEnds}'='3'
 and value#>>'{environment,caveApLoss}'='2'
 and value#>>'{environment,caveDamage}'='1'
 from ml_private.catalog where key='ruleset:web-v0.1.8'),false)
 and exists(select 1 from ml_private.catalog where key='stage4:foundation-v1' and jsonb_array_length(value->'allCards')=191)
 and exists(select 1 from ml_private.catalog where key='stage4:capabilities-v1' and jsonb_array_length(value)=76)
 and exists(select 1 from information_schema.columns where table_schema='ml_private' and table_name='rooms' and column_name='draft')
 and to_regprocedure('ml_private.stage4_actions(jsonb,integer)') is not null
 and to_regprocedure('ml_private.stage4_combat_task(jsonb,jsonb,double precision)') is not null
 and to_regprocedure('ml_private.stage4_movement_task(jsonb,jsonb,double precision)') is not null
 and to_regprocedure('ml_private.stage4_equipment_task(jsonb,jsonb,double precision)') is not null
 and to_regprocedure('ml_private.stage4_equipment_skill(jsonb,jsonb,double precision)') is not null
 and to_regprocedure('ml_private.stage4_create_draft(text,jsonb,double precision)') is not null
 and to_regprocedure('ml_private.stage3_complete_draft(ml_private.rooms,bigint)') is not null
 and to_regprocedure('ml_private.stage4_reserve_interrupt(jsonb,jsonb)') is not null
 and to_regprocedure('ml_private.stage4_cost_quote(jsonb,integer,text,jsonb,integer,bigint)') is not null as ready)
select jsonb_build_object('ok',true,'schemaVersion',2,'engineRevision',19,'ruleVersion','web-v0.1.8',
 'legacyRuleVersions',jsonb_build_array('web-v0.1.1','web-v0.1.2','web-v0.1.3','web-v0.1.4','web-v0.1.5','web-v0.1.6','web-v0.1.7'),
 'feedbackRulesReady',ready,'versionedDataReady',(select count(*)=8 from ml_private.catalog where key in ('ruleset:web-v0.1.1','ruleset:web-v0.1.2','ruleset:web-v0.1.3','ruleset:web-v0.1.4','ruleset:web-v0.1.5','ruleset:web-v0.1.6','ruleset:web-v0.1.7','ruleset:web-v0.1.8')),
 'locationDataReady',ready,'locationRulesReady',ready,'waterRulesReady',ready,'environmentRulesReady',ready,'classicPlayable',ready,'classicPatchReady',ready,
 'draftReady',ready,'characterSkillsReady',ready,'stage3Ready',ready,'stage4Ready',ready,'cardDefinitions',76,'cardInstances',191,'classicRuleVersion','web-v0.1.8','engine','postgresql') from readiness $$;
revoke all on all functions in schema ml_private from public;
DO $$ declare r text;begin foreach r in array array['anon','authenticated'] loop execute format('revoke all on all functions in schema ml_private from %I',r);end loop;end $$;
